window.S24_DATA = {"courseId":"science24-unit-c-excellence-v2","contentVersion":"2.1.0","topicId":"s24-c","title":"Disease Defence and Human Health","topics":[{"id":"01","label":"1. Disease causes and germ theory"},{"id":"02","label":"2. Compare bacteria, viruses and other pathogens"},{"id":"03","label":"3. Communicable disease and unequal risk"},{"id":"04","label":"4. Food safety and preservation"},{"id":"05","label":"5. Sanitation, sterilization and aseptic practice"},{"id":"06","label":"6. Outbreaks, epidemics and historical impact"},{"id":"07","label":"7. Public systems for water, waste and air"},{"id":"08","label":"8. Guidelines, risk decisions and the Walkerton case"},{"id":"09","label":"9. Physical barriers and inflammation"},{"id":"10","label":"10. Antigens, antibodies and immune response"},{"id":"11","label":"11. Blood compatibility, vaccines and immunity"},{"id":"12","label":"12. Medicines, antibiotics and safe choices"},{"id":"13","label":"13. DNA, chromosomes and inheritance"},{"id":"14","label":"14. Genotypes and Punnett squares"},{"id":"15","label":"15. Read and construct pedigrees"},{"id":"16","label":"16. Mutations, mutagens and genetic disorders"},{"id":"17","label":"17. Genetic research and ethical decisions"}],"vocabulary":[{"id":"s24-c-word-disease","term":"disease","topic":"01","meaning":"A condition that disrupts normal body function or health.","example":"An infection can cause disease, but an inherited condition can too.","distinction":"Disease names an outcome; it does not by itself identify a cause.","model":{"meaning":"A condition that disrupts normal body function or health.","features":"Disease names an outcome; it does not by itself identify a cause.","example":"An infection can cause disease, but an inherited condition can too.","nonexample":"Using disease for a different process without evidence."}},{"id":"s24-c-word-pathogen","term":"pathogen","topic":"01","meaning":"An agent able to cause disease in a host.","example":"Some Salmonella bacteria can cause foodborne illness.","distinction":"Most microorganisms are not pathogens.","model":{"meaning":"An agent able to cause disease in a host.","features":"Most microorganisms are not pathogens.","example":"Some Salmonella bacteria can cause foodborne illness.","nonexample":"Using pathogen for a different process without evidence."}},{"id":"s24-c-word-germ-theory","term":"germ theory","topic":"01","meaning":"The evidence-based idea that specific microorganisms can cause infectious diseases.","example":"Compare an organism found in cases with evidence from controls.","distinction":"It does not claim all disease is infectious.","model":{"meaning":"The evidence-based idea that specific microorganisms can cause infectious diseases.","features":"It does not claim all disease is infectious.","example":"Compare an organism found in cases with evidence from controls.","nonexample":"Using germ theory for a different process without evidence."}},{"id":"s24-c-word-risk-factor","term":"risk factor","topic":"01","meaning":"A condition or exposure associated with a changed chance of an outcome.","example":"Improper food temperature can increase foodborne illness risk.","distinction":"A risk factor is not the same as a confirmed diagnosis.","model":{"meaning":"A condition or exposure associated with a changed chance of an outcome.","features":"A risk factor is not the same as a confirmed diagnosis.","example":"Improper food temperature can increase foodborne illness risk.","nonexample":"Using risk factor for a different process without evidence."}},{"id":"s24-c-word-bacterium","term":"bacterium","topic":"02","meaning":"A single-celled organism; some species can cause disease.","example":"A foodborne bacterium may multiply under suitable conditions.","distinction":"Bacteria are cells; viruses use host cells to replicate.","model":{"meaning":"A single-celled organism; some species can cause disease.","features":"Bacteria are cells; viruses use host cells to replicate.","example":"A foodborne bacterium may multiply under suitable conditions.","nonexample":"Using bacterium for a different process without evidence."}},{"id":"s24-c-word-virus","term":"virus","topic":"02","meaning":"An infectious agent that uses a host cell to make new virus particles.","example":"A respiratory virus can spread between people.","distinction":"A virus does not divide independently like a bacterial cell.","model":{"meaning":"An infectious agent that uses a host cell to make new virus particles.","features":"A virus does not divide independently like a bacterial cell.","example":"A respiratory virus can spread between people.","nonexample":"Using virus for a different process without evidence."}},{"id":"s24-c-word-protist","term":"protist","topic":"02","meaning":"A diverse eukaryotic group that includes some parasites.","example":"Giardia can spread through contaminated water.","distinction":"Protist does not mean all members cause disease.","model":{"meaning":"A diverse eukaryotic group that includes some parasites.","features":"Protist does not mean all members cause disease.","example":"Giardia can spread through contaminated water.","nonexample":"Using protist for a different process without evidence."}},{"id":"s24-c-word-fungus","term":"fungus","topic":"02","meaning":"A group of organisms including yeasts and moulds; some cause infections.","example":"A fungus can cause athlete's foot.","distinction":"A fungal infection is not a bacterial infection.","model":{"meaning":"A group of organisms including yeasts and moulds; some cause infections.","features":"A fungal infection is not a bacterial infection.","example":"A fungus can cause athlete's foot.","nonexample":"Using fungus for a different process without evidence."}},{"id":"s24-c-word-communicable-disease","term":"communicable disease","topic":"03","meaning":"A disease that can spread between hosts through a transmission route.","example":"A respiratory infection may spread between people.","distinction":"Spreadability differs from severity.","model":{"meaning":"A disease that can spread between hosts through a transmission route.","features":"Spreadability differs from severity.","example":"A respiratory infection may spread between people.","nonexample":"Using communicable disease for a different process without evidence."}},{"id":"s24-c-word-non-communicable-disease","term":"non-communicable disease","topic":"03","meaning":"A disease not spread from person to person by an infectious agent.","example":"Some inherited disorders are non-communicable.","distinction":"Non-communicable does not mean there is only one cause.","model":{"meaning":"A disease not spread from person to person by an infectious agent.","features":"Non-communicable does not mean there is only one cause.","example":"Some inherited disorders are non-communicable.","nonexample":"Using non-communicable disease for a different process without evidence."}},{"id":"s24-c-word-transmission-route","term":"transmission route","topic":"03","meaning":"The pathway an infectious agent takes between source and host.","example":"Contaminated water can carry a pathogen into the digestive tract.","distinction":"The route is not identical to the social condition that permits exposure.","model":{"meaning":"The pathway an infectious agent takes between source and host.","features":"The route is not identical to the social condition that permits exposure.","example":"Contaminated water can carry a pathogen into the digestive tract.","nonexample":"Using transmission route for a different process without evidence."}},{"id":"s24-c-word-health-inequity","term":"health inequity","topic":"03","meaning":"An avoidable and unfair difference in health opportunities or outcomes linked to social conditions.","example":"Unequal access to treated water can change exposure risk.","distinction":"It is not a judgment about a person's worth or choices.","model":{"meaning":"An avoidable and unfair difference in health opportunities or outcomes linked to social conditions.","features":"It is not a judgment about a person's worth or choices.","example":"Unequal access to treated water can change exposure risk.","nonexample":"Using health inequity for a different process without evidence."}},{"id":"s24-c-word-food-preservation","term":"food preservation","topic":"04","meaning":"Processing or storage used to slow spoilage or reduce food-safety hazards.","example":"Refrigeration slows many microbial growth processes.","distinction":"It is not a guarantee of sterility.","model":{"meaning":"Processing or storage used to slow spoilage or reduce food-safety hazards.","features":"It is not a guarantee of sterility.","example":"Refrigeration slows many microbial growth processes.","nonexample":"Using food preservation for a different process without evidence."}},{"id":"s24-c-word-pasteurization","term":"pasteurization","topic":"04","meaning":"Controlled heating that reduces specified harmful microbes in a product.","example":"Commercial milk is commonly pasteurized.","distinction":"Pasteurization differs from sterilization and later safe storage still matters.","model":{"meaning":"Controlled heating that reduces specified harmful microbes in a product.","features":"Pasteurization differs from sterilization and later safe storage still matters.","example":"Commercial milk is commonly pasteurized.","nonexample":"Using pasteurization for a different process without evidence."}},{"id":"s24-c-word-cross-contamination","term":"cross-contamination","topic":"04","meaning":"Transfer of harmful material from one food or surface to another.","example":"An unwashed board transfers raw-meat microbes to salad.","distinction":"Cooling after transfer does not undo contamination.","model":{"meaning":"Transfer of harmful material from one food or surface to another.","features":"Cooling after transfer does not undo contamination.","example":"An unwashed board transfers raw-meat microbes to salad.","nonexample":"Using cross-contamination for a different process without evidence."}},{"id":"s24-c-word-refrigeration","term":"refrigeration","topic":"04","meaning":"Cold storage that slows many biological and chemical changes.","example":"A chilled lunch stays colder than one left on a counter.","distinction":"Cold storage does not necessarily kill pathogens.","model":{"meaning":"Cold storage that slows many biological and chemical changes.","features":"Cold storage does not necessarily kill pathogens.","example":"A chilled lunch stays colder than one left on a counter.","nonexample":"Using refrigeration for a different process without evidence."}},{"id":"s24-c-word-antiseptic","term":"antiseptic","topic":"05","meaning":"A product intended to reduce microorganisms on living tissue when used as directed.","example":"Some first-aid products are labeled for skin.","distinction":"It is not interchangeable with a hard-surface disinfectant.","model":{"meaning":"A product intended to reduce microorganisms on living tissue when used as directed.","features":"It is not interchangeable with a hard-surface disinfectant.","example":"Some first-aid products are labeled for skin.","nonexample":"Using antiseptic for a different process without evidence."}},{"id":"s24-c-word-disinfectant","term":"disinfectant","topic":"05","meaning":"A product or process used to reduce specified microorganisms on suitable non-living surfaces.","example":"A labeled product may be used on a counter as directed.","distinction":"Disinfection is not necessarily sterilization.","model":{"meaning":"A product or process used to reduce specified microorganisms on suitable non-living surfaces.","features":"Disinfection is not necessarily sterilization.","example":"A labeled product may be used on a counter as directed.","nonexample":"Using disinfectant for a different process without evidence."}},{"id":"s24-c-word-sterilization","term":"sterilization","topic":"05","meaning":"A validated process intended to eliminate all viable microorganisms from an item.","example":"Specialized equipment can sterilize suitable instruments.","distinction":"A quick wipe or cold storage is not sterilization.","model":{"meaning":"A validated process intended to eliminate all viable microorganisms from an item.","features":"A quick wipe or cold storage is not sterilization.","example":"Specialized equipment can sterilize suitable instruments.","nonexample":"Using sterilization for a different process without evidence."}},{"id":"s24-c-word-aseptic-technique","term":"aseptic technique","topic":"05","meaning":"A set of practices that prevents contamination during a task.","example":"Keeping prepared equipment away from unclean surfaces is aseptic practice.","distinction":"It is a procedure, not a chemical product.","model":{"meaning":"A set of practices that prevents contamination during a task.","features":"It is a procedure, not a chemical product.","example":"Keeping prepared equipment away from unclean surfaces is aseptic practice.","nonexample":"Using aseptic technique for a different process without evidence."}},{"id":"s24-c-word-outbreak","term":"outbreak","topic":"06","meaning":"More cases than expected in a defined place and time.","example":"An unusual cluster at one school can trigger an investigation.","distinction":"It does not by itself mean worldwide spread.","model":{"meaning":"More cases than expected in a defined place and time.","features":"It does not by itself mean worldwide spread.","example":"An unusual cluster at one school can trigger an investigation.","nonexample":"Using outbreak for a different process without evidence."}},{"id":"s24-c-word-epidemic","term":"epidemic","topic":"06","meaning":"An increase above expected cases across a population or region.","example":"A regional rise over several weeks may be an epidemic.","distinction":"Severity and geographic spread are different questions.","model":{"meaning":"An increase above expected cases across a population or region.","features":"Severity and geographic spread are different questions.","example":"A regional rise over several weeks may be an epidemic.","nonexample":"Using epidemic for a different process without evidence."}},{"id":"s24-c-word-pandemic","term":"pandemic","topic":"06","meaning":"An epidemic that has spread across multiple countries or continents.","example":"The 1918 influenza pandemic affected many regions.","distinction":"A single local outbreak is not a pandemic.","model":{"meaning":"An epidemic that has spread across multiple countries or continents.","features":"A single local outbreak is not a pandemic.","example":"The 1918 influenza pandemic affected many regions.","nonexample":"Using pandemic for a different process without evidence."}},{"id":"s24-c-word-historical-context","term":"historical context","topic":"06","meaning":"The time, place, social conditions and evidence needed to interpret a past event.","example":"Compare 1918 reports with the care and reporting available then.","distinction":"A dated figure is not automatically a current statistic.","model":{"meaning":"The time, place, social conditions and evidence needed to interpret a past event.","features":"A dated figure is not automatically a current statistic.","example":"Compare 1918 reports with the care and reporting available then.","nonexample":"Using historical context for a different process without evidence."}},{"id":"s24-c-word-water-treatment","term":"water treatment","topic":"07","meaning":"Processes used to reduce hazards in drinking water before distribution.","example":"Filtration and disinfection may be parts of a treatment system.","distinction":"Clear appearance alone does not show effective treatment.","model":{"meaning":"Processes used to reduce hazards in drinking water before distribution.","features":"Clear appearance alone does not show effective treatment.","example":"Filtration and disinfection may be parts of a treatment system.","nonexample":"Using water treatment for a different process without evidence."}},{"id":"s24-c-word-surveillance","term":"surveillance","topic":"07","meaning":"Systematic collection and interpretation of health or environmental information.","example":"Regular water samples can reveal a changing pattern.","distinction":"One observation is not a complete trend.","model":{"meaning":"Systematic collection and interpretation of health or environmental information.","features":"One observation is not a complete trend.","example":"Regular water samples can reveal a changing pattern.","nonexample":"Using surveillance for a different process without evidence."}},{"id":"s24-c-word-wastewater","term":"wastewater","topic":"07","meaning":"Used water containing human or other wastes that needs management.","example":"A community treatment plant reduces release of harmful material.","distinction":"It is not the same as untreated drinking water.","model":{"meaning":"Used water containing human or other wastes that needs management.","features":"It is not the same as untreated drinking water.","example":"A community treatment plant reduces release of harmful material.","nonexample":"Using wastewater for a different process without evidence."}},{"id":"s24-c-word-public-advisory","term":"public advisory","topic":"07","meaning":"A time- and place-specific notice that recommends protective action.","example":"A water or air notice may guide temporary behaviour.","distinction":"It is not an individual diagnosis.","model":{"meaning":"A time- and place-specific notice that recommends protective action.","features":"It is not an individual diagnosis.","example":"A water or air notice may guide temporary behaviour.","nonexample":"Using public advisory for a different process without evidence."}},{"id":"s24-c-word-risk-assessment","term":"risk assessment","topic":"08","meaning":"A structured comparison of hazards, exposure, likelihood and possible consequences.","example":"A water operator assesses a positive sample and possible users exposed.","distinction":"A hazard name alone is not a complete risk estimate.","model":{"meaning":"A structured comparison of hazards, exposure, likelihood and possible consequences.","features":"A hazard name alone is not a complete risk estimate.","example":"A water operator assesses a positive sample and possible users exposed.","nonexample":"Using risk assessment for a different process without evidence."}},{"id":"s24-c-word-public-health-guideline","term":"public-health guideline","topic":"08","meaning":"A recommendation or rule intended to reduce a stated population health risk.","example":"A sampling and notification protocol guides water-system action.","distinction":"A guideline should be tied to mechanism and evidence.","model":{"meaning":"A recommendation or rule intended to reduce a stated population health risk.","features":"A guideline should be tied to mechanism and evidence.","example":"A sampling and notification protocol guides water-system action.","nonexample":"Using public-health guideline for a different process without evidence."}},{"id":"s24-c-word-warning-sign","term":"warning sign","topic":"08","meaning":"An observation that calls for investigation or action.","example":"An unexpected test result can be a warning sign.","distinction":"It is not necessarily a final diagnosis of the whole system.","model":{"meaning":"An observation that calls for investigation or action.","features":"It is not necessarily a final diagnosis of the whole system.","example":"An unexpected test result can be a warning sign.","nonexample":"Using warning sign for a different process without evidence."}},{"id":"s24-c-word-escalation","term":"escalation","topic":"08","meaning":"Passing a concern to the person or authority able to act, following a defined process.","example":"A confirmed test result triggers timely review and public notice when appropriate.","distinction":"Recording a concern without action is not complete escalation.","model":{"meaning":"Passing a concern to the person or authority able to act, following a defined process.","features":"Recording a concern without action is not complete escalation.","example":"A confirmed test result triggers timely review and public notice when appropriate.","nonexample":"Using escalation for a different process without evidence."}},{"id":"s24-c-word-barrier-defence","term":"barrier defence","topic":"09","meaning":"A body surface or substance that reduces pathogen entry.","example":"Intact skin blocks many external organisms.","distinction":"A barrier is not an antibody response.","model":{"meaning":"A body surface or substance that reduces pathogen entry.","features":"A barrier is not an antibody response.","example":"Intact skin blocks many external organisms.","nonexample":"Using barrier defence for a different process without evidence."}},{"id":"s24-c-word-cilia","term":"cilia","topic":"09","meaning":"Tiny moving projections that help move mucus and trapped particles along airways.","example":"Airway cilia help clear inhaled material.","distinction":"Cilia are not the same as body hair.","model":{"meaning":"Tiny moving projections that help move mucus and trapped particles along airways.","features":"Cilia are not the same as body hair.","example":"Airway cilia help clear inhaled material.","nonexample":"Using cilia for a different process without evidence."}},{"id":"s24-c-word-inflammation","term":"inflammation","topic":"09","meaning":"A local response to injury or infection involving signals, blood vessels and immune cells.","example":"A sliver may lead to redness and swelling.","distinction":"It does not by itself prove a bacterial infection.","model":{"meaning":"A local response to injury or infection involving signals, blood vessels and immune cells.","features":"It does not by itself prove a bacterial infection.","example":"A sliver may lead to redness and swelling.","nonexample":"Using inflammation for a different process without evidence."}},{"id":"s24-c-word-macrophage","term":"macrophage","topic":"09","meaning":"An immune cell that can engulf material and help coordinate responses.","example":"A macrophage may engulf microbes in damaged tissue.","distinction":"It is a cell, not an antibody molecule.","model":{"meaning":"An immune cell that can engulf material and help coordinate responses.","features":"It is a cell, not an antibody molecule.","example":"A macrophage may engulf microbes in damaged tissue.","nonexample":"Using macrophage for a different process without evidence."}},{"id":"s24-c-word-antigen","term":"antigen","topic":"10","meaning":"A feature that can be recognized by an immune response.","example":"A protein on a microbe may act as an antigen.","distinction":"An antigen is not the same molecule as an antibody.","model":{"meaning":"A feature that can be recognized by an immune response.","features":"An antigen is not the same molecule as an antibody.","example":"A protein on a microbe may act as an antigen.","nonexample":"Using antigen for a different process without evidence."}},{"id":"s24-c-word-antibody","term":"antibody","topic":"10","meaning":"A protein produced by B-cell descendants that binds a matching target.","example":"An antibody may bind a matching viral surface feature.","distinction":"Binding alone is not the whole immune response.","model":{"meaning":"A protein produced by B-cell descendants that binds a matching target.","features":"Binding alone is not the whole immune response.","example":"An antibody may bind a matching viral surface feature.","nonexample":"Using antibody for a different process without evidence."}},{"id":"s24-c-word-active-immunity","term":"active immunity","topic":"10","meaning":"Protection developed through a person's own immune response after infection or vaccination.","example":"Vaccination can stimulate immune memory.","distinction":"It is not necessarily lifelong or complete.","model":{"meaning":"Protection developed through a person's own immune response after infection or vaccination.","features":"It is not necessarily lifelong or complete.","example":"Vaccination can stimulate immune memory.","nonexample":"Using active immunity for a different process without evidence."}},{"id":"s24-c-word-passive-immunity","term":"passive immunity","topic":"10","meaning":"Temporary protection supplied by antibodies from another source.","example":"Some maternal antibodies pass to an infant.","distinction":"The recipient has not made those antibodies through the same active response.","model":{"meaning":"Temporary protection supplied by antibodies from another source.","features":"The recipient has not made those antibodies through the same active response.","example":"Some maternal antibodies pass to an infant.","nonexample":"Using passive immunity for a different process without evidence."}},{"id":"s24-c-word-blood-group-antigen","term":"blood-group antigen","topic":"11","meaning":"A marker on red blood cells used in a compatibility model.","example":"A-type red cells carry A antigen.","distinction":"It is not the whole clinical compatibility result.","model":{"meaning":"A marker on red blood cells used in a compatibility model.","features":"It is not the whole clinical compatibility result.","example":"A-type red cells carry A antigen.","nonexample":"Using blood-group antigen for a different process without evidence."}},{"id":"s24-c-word-rhd","term":"RhD","topic":"11","meaning":"An antigen used in the positive/negative part of common red-cell typing.","example":"O-negative red cells lack RhD antigen.","distinction":"RhD is only one of several clinically important markers.","model":{"meaning":"An antigen used in the positive/negative part of common red-cell typing.","features":"RhD is only one of several clinically important markers.","example":"O-negative red cells lack RhD antigen.","nonexample":"Using RhD for a different process without evidence."}},{"id":"s24-c-word-vaccine","term":"vaccine","topic":"11","meaning":"A preparation that stimulates an immune response to a specified target.","example":"A vaccine may use a pathogen component or mRNA platform.","distinction":"Vaccines are not all weakened or dead whole pathogens.","model":{"meaning":"A preparation that stimulates an immune response to a specified target.","features":"Vaccines are not all weakened or dead whole pathogens.","example":"A vaccine may use a pathogen component or mRNA platform.","nonexample":"Using vaccine for a different process without evidence."}},{"id":"s24-c-word-immune-memory","term":"immune memory","topic":"11","meaning":"A lasting capacity of some immune cells to respond to a previously encountered target.","example":"A later exposure may trigger a faster response.","distinction":"Memory does not guarantee absolute or lifelong protection.","model":{"meaning":"A lasting capacity of some immune cells to respond to a previously encountered target.","features":"Memory does not guarantee absolute or lifelong protection.","example":"A later exposure may trigger a faster response.","nonexample":"Using immune memory for a different process without evidence."}},{"id":"s24-c-word-antibiotic","term":"antibiotic","topic":"12","meaning":"A medicine used to treat or prevent certain bacterial infections.","example":"A clinician may prescribe one for a confirmed or likely bacterial infection.","distinction":"It does not directly treat a viral cold.","model":{"meaning":"A medicine used to treat or prevent certain bacterial infections.","features":"It does not directly treat a viral cold.","example":"A clinician may prescribe one for a confirmed or likely bacterial infection.","nonexample":"Using antibiotic for a different process without evidence."}},{"id":"s24-c-word-antibiotic-resistance","term":"antibiotic resistance","topic":"12","meaning":"The ability of bacteria to survive an antibiotic that previously worked against them.","example":"A resistant bacterial strain may spread under selection.","distinction":"It is the microbes, not the patient's body, that become resistant.","model":{"meaning":"The ability of bacteria to survive an antibiotic that previously worked against them.","features":"It is the microbes, not the patient's body, that become resistant.","example":"A resistant bacterial strain may spread under selection.","nonexample":"Using antibiotic resistance for a different process without evidence."}},{"id":"s24-c-word-active-ingredient","term":"active ingredient","topic":"12","meaning":"The substance in a medicine responsible for its intended effect.","example":"Two brands may contain the same active ingredient.","distinction":"Brand names do not prove different ingredients.","model":{"meaning":"The substance in a medicine responsible for its intended effect.","features":"Brand names do not prove different ingredients.","example":"Two brands may contain the same active ingredient.","nonexample":"Using active ingredient for a different process without evidence."}},{"id":"s24-c-word-over-the-counter-medicine","term":"over-the-counter medicine","topic":"12","meaning":"A medicine available without an individual prescription, with directions and warnings.","example":"A cold symptom product may be sold over the counter.","distinction":"Available without prescription does not mean risk-free.","model":{"meaning":"A medicine available without an individual prescription, with directions and warnings.","features":"Available without prescription does not mean risk-free.","example":"A cold symptom product may be sold over the counter.","nonexample":"Using over-the-counter medicine for a different process without evidence."}},{"id":"s24-c-word-dna","term":"DNA","topic":"13","meaning":"A molecule that carries hereditary information in a sequence of bases.","example":"A and T pair across a DNA double strand.","distinction":"DNA is the material, not the whole chromosome image.","model":{"meaning":"A molecule that carries hereditary information in a sequence of bases.","features":"DNA is the material, not the whole chromosome image.","example":"A and T pair across a DNA double strand.","nonexample":"Using DNA for a different process without evidence."}},{"id":"s24-c-word-gene","term":"gene","topic":"13","meaning":"A DNA region whose information contributes to a functional product.","example":"A gene may help specify a protein.","distinction":"A complex trait is not always controlled by one gene.","model":{"meaning":"A DNA region whose information contributes to a functional product.","features":"A complex trait is not always controlled by one gene.","example":"A gene may help specify a protein.","nonexample":"Using gene for a different process without evidence."}},{"id":"s24-c-word-chromosome","term":"chromosome","topic":"13","meaning":"An organized DNA-containing structure visible in a karyotype during cell division.","example":"Chromosome 21 appears in a pair in a typical body-cell set.","distinction":"A chromosome contains many genes.","model":{"meaning":"An organized DNA-containing structure visible in a karyotype during cell division.","features":"A chromosome contains many genes.","example":"Chromosome 21 appears in a pair in a typical body-cell set.","nonexample":"Using chromosome for a different process without evidence."}},{"id":"s24-c-word-karyotype","term":"karyotype","topic":"13","meaning":"An arranged image of chromosomes used to inspect number and large structural patterns.","example":"An extra chromosome 21 is visible in a karyotype.","distinction":"It does not reveal every DNA variant or a person's gender identity.","model":{"meaning":"An arranged image of chromosomes used to inspect number and large structural patterns.","features":"It does not reveal every DNA variant or a person's gender identity.","example":"An extra chromosome 21 is visible in a karyotype.","nonexample":"Using karyotype for a different process without evidence."}},{"id":"s24-c-word-allele","term":"allele","topic":"14","meaning":"A version of a gene used in an inheritance model.","example":"T and t represent two versions for a plant-height model.","distinction":"An allele is not a whole chromosome.","model":{"meaning":"A version of a gene used in an inheritance model.","features":"An allele is not a whole chromosome.","example":"T and t represent two versions for a plant-height model.","nonexample":"Using allele for a different process without evidence."}},{"id":"s24-c-word-genotype","term":"genotype","topic":"14","meaning":"The allele combination assigned to an organism for the trait being modeled.","example":"Tt is one plant genotype.","distinction":"Genotype letters are not the same as observed height.","model":{"meaning":"The allele combination assigned to an organism for the trait being modeled.","features":"Genotype letters are not the same as observed height.","example":"Tt is one plant genotype.","nonexample":"Using genotype for a different process without evidence."}},{"id":"s24-c-word-phenotype","term":"phenotype","topic":"14","meaning":"An observable trait or characteristic produced through genes and often environment.","example":"A Tt plant may be tall in the model.","distinction":"One phenotype need not correspond to only one genotype.","model":{"meaning":"An observable trait or characteristic produced through genes and often environment.","features":"One phenotype need not correspond to only one genotype.","example":"A Tt plant may be tall in the model.","nonexample":"Using phenotype for a different process without evidence."}},{"id":"s24-c-word-punnett-square","term":"Punnett square","topic":"14","meaning":"A grid for organizing possible allele combinations from two parents.","example":"A Tt × tt grid has two Tt and two tt cells.","distinction":"Four cells are probabilities, not a family prediction.","model":{"meaning":"A grid for organizing possible allele combinations from two parents.","features":"Four cells are probabilities, not a family prediction.","example":"A Tt × tt grid has two Tt and two tt cells.","nonexample":"Using Punnett square for a different process without evidence."}},{"id":"s24-c-word-pedigree","term":"pedigree","topic":"15","meaning":"A diagram showing relationships and a trait's observed status across generations.","example":"Workbook p. 31 shows Sue, Joe, Jim and Tim shaded.","distinction":"It does not automatically reveal every genotype.","model":{"meaning":"A diagram showing relationships and a trait's observed status across generations.","features":"It does not automatically reveal every genotype.","example":"Workbook p. 31 shows Sue, Joe, Jim and Tim shaded.","nonexample":"Using pedigree for a different process without evidence."}},{"id":"s24-c-word-generation","term":"generation","topic":"15","meaning":"People placed at the same level of descent in a pedigree.","example":"The workbook diagram has three generation rows.","distinction":"A row is not a count of children for one person.","model":{"meaning":"People placed at the same level of descent in a pedigree.","features":"A row is not a count of children for one person.","example":"The workbook diagram has three generation rows.","nonexample":"Using generation for a different process without evidence."}},{"id":"s24-c-word-carrier","term":"carrier","topic":"15","meaning":"In a recessive model, a person who has one recessive allele but does not show the modeled condition.","example":"An unshaded partner could be a carrier in a possible recessive explanation.","distinction":"Unshaded status does not prove carrier status.","model":{"meaning":"In a recessive model, a person who has one recessive allele but does not show the modeled condition.","features":"Unshaded status does not prove carrier status.","example":"An unshaded partner could be a carrier in a possible recessive explanation.","nonexample":"Using carrier for a different process without evidence."}},{"id":"s24-c-word-evidence-limit","term":"evidence limit","topic":"15","meaning":"A boundary on what the given observations can establish.","example":"Missing genotypes prevent a unique dominance conclusion in Q12.","distinction":"Uncertainty is not a reason to ignore the clear family relationships.","model":{"meaning":"A boundary on what the given observations can establish.","features":"Uncertainty is not a reason to ignore the clear family relationships.","example":"Missing genotypes prevent a unique dominance conclusion in Q12.","nonexample":"Using evidence limit for a different process without evidence."}},{"id":"s24-c-word-mutation","term":"mutation","topic":"16","meaning":"A change in DNA sequence or chromosome structure/number in a specified context.","example":"A copying error can change one DNA base.","distinction":"Mutation does not always mean harmful disease.","model":{"meaning":"A change in DNA sequence or chromosome structure/number in a specified context.","features":"Mutation does not always mean harmful disease.","example":"A copying error can change one DNA base.","nonexample":"Using mutation for a different process without evidence."}},{"id":"s24-c-word-mutagen","term":"mutagen","topic":"16","meaning":"An agent or exposure that can increase the rate of DNA changes.","example":"Some forms of radiation can damage DNA.","distinction":"Exposure is not a guaranteed disorder.","model":{"meaning":"An agent or exposure that can increase the rate of DNA changes.","features":"Exposure is not a guaranteed disorder.","example":"Some forms of radiation can damage DNA.","nonexample":"Using mutagen for a different process without evidence."}},{"id":"s24-c-word-genetic-disorder","term":"genetic disorder","topic":"16","meaning":"A health condition related to particular genetic changes, often with varied expression.","example":"Trisomy 21 is a chromosome-number condition.","distinction":"A genetic finding does not tell the whole story of a person.","model":{"meaning":"A health condition related to particular genetic changes, often with varied expression.","features":"A genetic finding does not tell the whole story of a person.","example":"Trisomy 21 is a chromosome-number condition.","nonexample":"Using genetic disorder for a different process without evidence."}},{"id":"s24-c-word-inherited-variant","term":"inherited variant","topic":"16","meaning":"A genetic difference passed through a reproductive cell from a parent.","example":"A child can inherit an allele present in a parent's egg or sperm.","distinction":"A body-cell-only change is not automatically inherited.","model":{"meaning":"A genetic difference passed through a reproductive cell from a parent.","features":"A body-cell-only change is not automatically inherited.","example":"A child can inherit an allele present in a parent's egg or sperm.","nonexample":"Using inherited variant for a different process without evidence."}},{"id":"s24-c-word-genetic-research","term":"genetic research","topic":"17","meaning":"Systematic study of genes, variants and their relationships to function or health.","example":"Researchers compare variant patterns and outcomes.","distinction":"A research association is not always a causal diagnosis.","model":{"meaning":"Systematic study of genes, variants and their relationships to function or health.","features":"A research association is not always a causal diagnosis.","example":"Researchers compare variant patterns and outcomes.","nonexample":"Using genetic research for a different process without evidence."}},{"id":"s24-c-word-genetic-screening","term":"genetic screening","topic":"17","meaning":"Testing used to look for specified genetic patterns or risks.","example":"A screen may identify a chromosome pattern needing interpretation.","distinction":"A screen is not a complete prediction of a person's future.","model":{"meaning":"Testing used to look for specified genetic patterns or risks.","features":"A screen is not a complete prediction of a person's future.","example":"A screen may identify a chromosome pattern needing interpretation.","nonexample":"Using genetic screening for a different process without evidence."}},{"id":"s24-c-word-informed-consent","term":"informed consent","topic":"17","meaning":"A person's voluntary decision after understanding purpose, risks and alternatives.","example":"A participant agrees to a genetic study after reviewing its use of data.","distinction":"A signature without understanding is not enough.","model":{"meaning":"A person's voluntary decision after understanding purpose, risks and alternatives.","features":"A signature without understanding is not enough.","example":"A participant agrees to a genetic study after reviewing its use of data.","nonexample":"Using informed consent for a different process without evidence."}},{"id":"s24-c-word-genetic-privacy","term":"genetic privacy","topic":"17","meaning":"Control and protection of information about a person's genetic data.","example":"A research project limits access to individual results.","distinction":"Anonymized-looking data may still carry privacy concerns.","model":{"meaning":"Control and protection of information about a person's genetic data.","features":"Anonymized-looking data may still carry privacy concerns.","example":"A research project limits access to individual results.","nonexample":"Using genetic privacy for a different process without evidence."}}],"banks":{"multiple-choice":[{"kind":"mc","prompt":"A learner says the warm room itself infected everyone who ate a lunch. Which correction is strongest?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Distinguish a condition that changes growth from the agent and exposure that could cause infection.","id":"s24-c-l01-error","topic":"01","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l01-error-o0","text":"Warmth can favour growth if a pathogen was present; exposure to the pathogen still needs evidence."},{"id":"s24-c-l01-error-o1","text":"Warm conditions alone are sufficient to introduce a pathogen into uncontaminated food."},{"id":"s24-c-l01-error-o2","text":"Temperature alone identifies the exact bacterium."},{"id":"s24-c-l01-error-o3","text":"An inherited condition is established solely by the timing of illness after this meal."}],"answer":"s24-c-l01-error-o0"},{"kind":"mc","prompt":"Which observation would best begin testing a foodborne explanation?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A comparison across cases and exposures tests the claim better than appearance or assumption.","id":"s24-c-l01-guided1","topic":"01","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l01-guided1-o0","text":"Compare what affected and unaffected people ate and when symptoms began."},{"id":"s24-c-l01-guided1-o1","text":"Ask only whether the room looked clean."},{"id":"s24-c-l01-guided1-o2","text":"Compare package appearance without checking what affected and unaffected people actually ate."},{"id":"s24-c-l01-guided1-o3","text":"Assume everyone at the school had the same exposure."}],"answer":"s24-c-l01-guided1-o0"},{"kind":"mc","prompt":"Why might a hamburger left warm become riskier over time?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Growth requires an organism and suitable conditions; risk is not a guaranteed outcome.","id":"s24-c-l01-guided2","topic":"01","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l01-guided2-o0","text":"Some bacteria already present may reproduce under suitable conditions."},{"id":"s24-c-l01-guided2-o1","text":"Warmth by itself introduces a new pathogen into otherwise uncontaminated food."},{"id":"s24-c-l01-guided2-o2","text":"Warmth guarantees every eater will become sick."},{"id":"s24-c-l01-guided2-o3","text":"Chilling slows growth but by itself removes every microbe already present."}],"answer":"s24-c-l01-guided2-o0"},{"kind":"mc","prompt":"A student lists poverty as a pathogen. What is the reasoning error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Keep an infectious agent distinct from conditions that shape risk and response.","id":"s24-c-l01-independent1","topic":"01","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l01-independent1-o0","text":"A social condition can alter exposure and access to care but is not itself an infectious agent."},{"id":"s24-c-l01-independent1-o1","text":"Social conditions can never affect health."},{"id":"s24-c-l01-independent1-o2","text":"Every disease linked to poverty is inherited."},{"id":"s24-c-l01-independent1-o3","text":"A pathogen is just another word for any risk factor."}],"answer":"s24-c-l01-independent1-o0"},{"kind":"mc","prompt":"Two people ate the same meal; one became ill. What is a defensible conclusion?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Different outcomes do not establish or exclude a food source without more evidence.","id":"s24-c-l01-independent2","topic":"01","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l01-independent2-o0","text":"Investigate agent, dose, other exposures and host factors before assigning a cause."},{"id":"s24-c-l01-independent2-o1","text":"The different outcomes prove one person handled the food incorrectly."},{"id":"s24-c-l01-independent2-o2","text":"The meal is proven safe because one person stayed well."},{"id":"s24-c-l01-independent2-o3","text":"The room temperature alone proves a diagnosis."}],"answer":"s24-c-l01-independent2-o0"},{"kind":"mc","prompt":"A learner says a cold virus divides by itself on a sandwich like a bacterial cell. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Bacteria are cells that may divide independently; viruses use host cells for replication.","id":"s24-c-l02-error","topic":"02","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l02-error-o0","text":"A virus needs a suitable host cell to make more virus particles."},{"id":"s24-c-l02-error-o1","text":"Bacteria never reproduce in food."},{"id":"s24-c-l02-error-o2","text":"Viruses and fungi are the same type of cellular organism."},{"id":"s24-c-l02-error-o3","text":"A virus can multiply on food without entering a host cell."}],"answer":"s24-c-l02-error-o0"},{"kind":"mc","prompt":"Which pair is correctly matched in the workbook examples?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The examples involve different groups and need different transmission explanations.","id":"s24-c-l02-guided1","topic":"02","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l02-guided1-o0","text":"Giardia — protist; athlete's foot — fungus."},{"id":"s24-c-l02-guided1-o1","text":"Giardia — virus; athlete's foot — bacterium."},{"id":"s24-c-l02-guided1-o2","text":"Giardia — fungus; athlete's foot — protist."},{"id":"s24-c-l02-guided1-o3","text":"Both are bacterial diseases with the same exposure route."}],"answer":"s24-c-l02-guided1-o0"},{"kind":"mc","prompt":"Which route could explain Giardia exposure in a hiking case?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The waterborne route connects an environmental source with entry into the digestive system.","id":"s24-c-l02-guided2","topic":"02","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l02-guided2-o0","text":"Swallowing contaminated untreated water."},{"id":"s24-c-l02-guided2-o1","text":"Knowing that beavers can carry Giardia without a water-exposure pathway."},{"id":"s24-c-l02-guided2-o2","text":"Being outdoors without evidence of a contaminated water source."},{"id":"s24-c-l02-guided2-o3","text":"Having a naturally occurring DNA allele."}],"answer":"s24-c-l02-guided2-o0"},{"kind":"mc","prompt":"An antibiotic helped one infection, so a learner wants it for every viral cold. Which response uses mechanism?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Treatment depends on the agent and clinical context, not the general word 'infection'.","id":"s24-c-l02-independent1","topic":"02","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l02-independent1-o0","text":"Antibiotics target bacteria; they do not directly act on a cold virus."},{"id":"s24-c-l02-independent1-o1","text":"Fever is enough to classify this infection as bacterial."},{"id":"s24-c-l02-independent1-o2","text":"Viral particles split independently like bacteria."},{"id":"s24-c-l02-independent1-o3","text":"A medicine that helped once must work for every cause."}],"answer":"s24-c-l02-independent1-o0"},{"kind":"mc","prompt":"A rash is described as definitely fungal from appearance alone. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A symptom can suggest possibilities but does not identify the agent by itself.","id":"s24-c-l02-independent2","topic":"02","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l02-independent2-o0","text":"Evidence distinguishing fungal infection from other infectious and non-infectious causes."},{"id":"s24-c-l02-independent2-o1","text":"A complete list of all nearby microbes, regardless of exposure route."},{"id":"s24-c-l02-independent2-o2","text":"Proof that all skin rashes are contagious."},{"id":"s24-c-l02-independent2-o3","text":"A claim that fungi are viruses."}],"answer":"s24-c-l02-independent2-o0"},{"kind":"mc","prompt":"A learner calls crowded housing a pathogen. Which correction is best?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Separate a social condition from the microorganism and transmission route.","id":"s24-c-l03-error","topic":"03","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l03-error-o0","text":"It can increase contact and exposure opportunities; a pathogen is the disease-causing agent."},{"id":"s24-c-l03-error-o1","text":"It can never influence transmission."},{"id":"s24-c-l03-error-o2","text":"It is a kind of virus."},{"id":"s24-c-l03-error-o3","text":"It proves every resident has an infection."}],"answer":"s24-c-l03-error-o0"},{"kind":"mc","prompt":"Which condition is communicable in the relevant sense?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Communicable describes spread of an infectious condition between hosts.","id":"s24-c-l03-guided1","topic":"03","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l03-guided1-o0","text":"An infection that can pass between hosts through a route."},{"id":"s24-c-l03-guided1-o1","text":"A chromosome-number pattern inherited through reproduction."},{"id":"s24-c-l03-guided1-o2","text":"A broken bone from a fall."},{"id":"s24-c-l03-guided1-o3","text":"A nutritional deficiency with no infectious agent."}],"answer":"s24-c-l03-guided1-o0"},{"kind":"mc","prompt":"Which question helps compare two old mortality charts fairly?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Time, denominator and measurement type determine whether a comparison is meaningful.","id":"s24-c-l03-guided2","topic":"03","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l03-guided2-o0","text":"Do they use the same date, population, age range and measure?"},{"id":"s24-c-l03-guided2-o1","text":"Compare bar colours without checking the legend, date or denominator."},{"id":"s24-c-l03-guided2-o2","text":"Compare the place names rather than the rates and time periods."},{"id":"s24-c-l03-guided2-o3","text":"Can a dated number be called today's rate?"}],"answer":"s24-c-l03-guided2-o0"},{"kind":"mc","prompt":"A student says poor water access means residents are biologically more likely to be infected. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The mechanism is exposure through a system, not a trait assigned to a group.","id":"s24-c-l03-independent1","topic":"03","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l03-independent1-o0","text":"Unequal water infrastructure changes exposure; it does not define inherent biology of residents."},{"id":"s24-c-l03-independent1-o1","text":"Water cannot carry infectious agents."},{"id":"s24-c-l03-independent1-o2","text":"Inherited factors alone determine whether a person becomes infected."},{"id":"s24-c-l03-independent1-o3","text":"Public systems cannot reduce exposure."}],"answer":"s24-c-l03-independent1-o0"},{"kind":"mc","prompt":"Two diseases both harm health, but only one spreads by contact. What should the classification use?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Communicability is about spread between hosts; severity is another dimension.","id":"s24-c-l03-independent2","topic":"03","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l03-independent2-o0","text":"The demonstrated transmission mechanism, not just severity or symptom."},{"id":"s24-c-l03-independent2-o1","text":"Use the larger raw case count without adjusting for population size."},{"id":"s24-c-l03-independent2-o2","text":"Whether someone is worried about it."},{"id":"s24-c-l03-independent2-o3","text":"Use an undated number without checking how or when it was measured."}],"answer":"s24-c-l03-independent2-o0"},{"kind":"mc","prompt":"A student says refrigeration sterilizes food. Which correction is best?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Preservation methods change conditions or reduce hazards in different ways; cold storage is not sterilization.","id":"s24-c-l04-error","topic":"04","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l04-error-o0","text":"Cold slows many microbes; it does not reliably eliminate every pathogen."},{"id":"s24-c-l04-error-o1","text":"Cold creates new pathogens."},{"id":"s24-c-l04-error-o2","text":"Refrigeration is identical to pasteurization."},{"id":"s24-c-l04-error-o3","text":"Food safety depends only on colour."}],"answer":"s24-c-l04-error-o0"},{"kind":"mc","prompt":"Which method primarily reduces available water for microbial growth?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Less available water can limit microbial growth in a specific preservation method.","id":"s24-c-l04-guided1","topic":"04","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l04-guided1-o0","text":"Drying or salting."},{"id":"s24-c-l04-guided1-o1","text":"Leaving food on a warm counter."},{"id":"s24-c-l04-guided1-o2","text":"Using the same unwashed board for raw and ready-to-eat food."},{"id":"s24-c-l04-guided1-o3","text":"Removing the product label."}],"answer":"s24-c-l04-guided1-o0"},{"kind":"mc","prompt":"Why does pasteurization not mean opened milk may stay warm indefinitely?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Controlled processing has limits; safe storage after opening still matters.","id":"s24-c-l04-guided2","topic":"04","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l04-guided2-o0","text":"It reduces targeted microbes through controlled heat but later contamination and growth remain possible."},{"id":"s24-c-l04-guided2-o1","text":"It makes milk completely sterile, so later storage and handling cannot matter."},{"id":"s24-c-l04-guided2-o2","text":"It works only by freezing the product."},{"id":"s24-c-l04-guided2-o3","text":"It protects milk by adding a vaccine rather than by controlled heat treatment."}],"answer":"s24-c-l04-guided2-o0"},{"kind":"mc","prompt":"A salad is prepared on a board used for raw poultry. Which intervention addresses the route?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Cross-contamination occurs during transfer from the raw-food surface to ready-to-eat food.","id":"s24-c-l04-independent1","topic":"04","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l04-independent1-o0","text":"Use separate or properly cleaned and sanitized equipment before the salad is prepared."},{"id":"s24-c-l04-independent1-o1","text":"Only chill the salad after contamination."},{"id":"s24-c-l04-independent1-o2","text":"Assume vegetables kill microbes from poultry."},{"id":"s24-c-l04-independent1-o3","text":"Wait until the board looks dry without cleaning it."}],"answer":"s24-c-l04-independent1-o0"},{"kind":"mc","prompt":"Which statement about freezing is defensible?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Freezing changes growth conditions; organisms may survive and grow after thawing.","id":"s24-c-l04-independent2","topic":"04","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l04-independent2-o0","text":"It slows or stops growth while frozen but cannot be assumed to sterilize the food."},{"id":"s24-c-l04-independent2-o1","text":"It makes all food safe forever."},{"id":"s24-c-l04-independent2-o2","text":"It guarantees every microbe is destroyed."},{"id":"s24-c-l04-independent2-o3","text":"It increases room-temperature bacterial division."}],"answer":"s24-c-l04-independent2-o0"},{"kind":"mc","prompt":"A learner puts hard-surface disinfectant on a cut because it 'kills germs.' What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Microbial action and tissue safety are separate requirements.","id":"s24-c-l05-error","topic":"05","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l05-error-o0","text":"A product for surfaces is not interchangeable with a skin antiseptic; follow the intended-use label."},{"id":"s24-c-l05-error-o1","text":"Skin and countertops are the same material."},{"id":"s24-c-l05-error-o2","text":"Antiseptic means a stronger floor cleaner."},{"id":"s24-c-l05-error-o3","text":"All disinfectants are safe on living tissue."}],"answer":"s24-c-l05-error-o0"},{"kind":"mc","prompt":"What best describes sterilization?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Sterilization has a more demanding outcome than ordinary cleaning or disinfection.","id":"s24-c-l05-guided1","topic":"05","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l05-guided1-o0","text":"A validated process intended to eliminate all viable microorganisms from an item."},{"id":"s24-c-l05-guided1-o1","text":"Any visible wipe of a table."},{"id":"s24-c-l05-guided1-o2","text":"Keeping an item in a refrigerator."},{"id":"s24-c-l05-guided1-o3","text":"Applying hand lotion."}],"answer":"s24-c-l05-guided1-o0"},{"kind":"mc","prompt":"A prepared tool touches an unclean counter. What changed?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Aseptic practice must prevent re-contamination throughout the procedure.","id":"s24-c-l05-guided2","topic":"05","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l05-guided2-o0","text":"It may have become contaminated despite earlier preparation."},{"id":"s24-c-l05-guided2-o1","text":"It became automatically more sterile."},{"id":"s24-c-l05-guided2-o2","text":"The counter no longer contains any microbes."},{"id":"s24-c-l05-guided2-o3","text":"Gloves alone replace surface preparation and sterile equipment."}],"answer":"s24-c-l05-guided2-o0"},{"kind":"mc","prompt":"Which method is intended for suitable non-living surfaces?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Disinfectants and antiseptics differ in intended target and safe use.","id":"s24-c-l05-independent1","topic":"05","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l05-independent1-o0","text":"A disinfectant used according to its label."},{"id":"s24-c-l05-independent1-o1","text":"Use a skin antiseptic on an instrument without checking whether it can sterilize the instrument."},{"id":"s24-c-l05-independent1-o2","text":"An antiseptic chosen without label review."},{"id":"s24-c-l05-independent1-o3","text":"Cooling instruments is enough to make them sterile."}],"answer":"s24-c-l05-independent1-o0"},{"kind":"mc","prompt":"Why is hand cleaning alone insufficient after sterile equipment is put on a dirty surface?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Each new contact can break the chain of controls.","id":"s24-c-l05-independent2","topic":"05","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l05-independent2-o0","text":"The equipment should be treated as potentially contaminated before continuing."},{"id":"s24-c-l05-independent2-o1","text":"Hands can never transfer microbes."},{"id":"s24-c-l05-independent2-o2","text":"Aseptic technique only happens before the task."},{"id":"s24-c-l05-independent2-o3","text":"The original cleaning step makes later contact irrelevant."}],"answer":"s24-c-l05-independent2-o0"},{"kind":"mc","prompt":"A learner calls one school's illness cluster a pandemic. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Pandemic describes broad geographic spread, not the seriousness of one local cluster.","id":"s24-c-l06-error","topic":"06","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l06-error-o0","text":"Evidence of spread across multiple countries or continents."},{"id":"s24-c-l06-error-o1","text":"A symptom that feels severe to one person."},{"id":"s24-c-l06-error-o2","text":"A higher number of students in one classroom."}],"answer":"s24-c-l06-error-o0"},{"kind":"mc","prompt":"A town reports 25 cases this week and usually has about two. What should be investigated first?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A local excess can signal an outbreak, but case definitions, links and reporting still need checking.","id":"s24-c-l06-guided1","topic":"06","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l06-guided1-o0","text":"Whether the increase is real, linked and above the expected baseline in that time and place."},{"id":"s24-c-l06-guided1-o1","text":"Count repeated reports as separate cases without checking whether they describe the same person."},{"id":"s24-c-l06-guided1-o2","text":"Use an old national chart as the current local outbreak rate."}],"answer":"s24-c-l06-guided1-o0"},{"kind":"mc","prompt":"Why can't a 1918 total-death count be directly ranked against a modern rate per 100,000?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A total and a population-adjusted rate answer different questions.","id":"s24-c-l06-guided2","topic":"06","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l06-guided2-o0","text":"The measures and populations differ; convert or obtain comparable measures."},{"id":"s24-c-l06-guided2-o1","text":"The modern number must always be smaller."},{"id":"s24-c-l06-guided2-o2","text":"Historical records are never useful."}],"answer":"s24-c-l06-guided2-o0"},{"kind":"mc","prompt":"The workbook asks about disease impacts on First Nations peoples. Which explanation avoids a one-cause story?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Historical impact requires context and avoids treating diverse peoples as one biological category.","id":"s24-c-l06-independent1","topic":"06","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l06-independent1-o0","text":"Consider introduced pathogens alongside displacement, living conditions, care access and colonial policy with historical evidence."},{"id":"s24-c-l06-independent1-o1","text":"Assign one universal biological weakness to all Indigenous peoples."},{"id":"s24-c-l06-independent1-o2","text":"Ignore differences among communities and eras."}],"answer":"s24-c-l06-independent1-o0"},{"kind":"mc","prompt":"Which claim can a dated plague/tuberculosis/influenza/AIDS table support?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The workbook table is historical evidence whose date, place and measure matter.","id":"s24-c-l06-independent2","topic":"06","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l06-independent2-o0","text":"A comparison of specified cases in their recorded period and place, with limits stated."},{"id":"s24-c-l06-independent2-o1","text":"A permanent ranking of all countries today."},{"id":"s24-c-l06-independent2-o2","text":"A diagnosis for each person in the table."}],"answer":"s24-c-l06-independent2-o0"},{"kind":"mc","prompt":"A learner says a clear glass proves drinking water is safe. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Safety evidence comes from source, treatment, monitoring and distribution, not appearance alone.","id":"s24-c-l07-error","topic":"07","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l07-error-o0","text":"Appearance cannot reveal every microorganism or chemical; testing and system records matter."},{"id":"s24-c-l07-error-o1","text":"Clear water must contain no dissolved material."},{"id":"s24-c-l07-error-o2","text":"A normal taste is sufficient evidence that treatment removed hazards."}],"answer":"s24-c-l07-error-o0"},{"kind":"mc","prompt":"A water sample shows a contamination indicator. What follows first?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A sample is a warning signal that requires interpretation and an appropriate response.","id":"s24-c-l07-guided1","topic":"07","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l07-guided1-o0","text":"Confirm and investigate its location, meaning and the system pathway under current protocols."},{"id":"s24-c-l07-guided1-o1","text":"Treat the result as proof of the same exposure at every tap without locating the sample."},{"id":"s24-c-l07-guided1-o2","text":"Ignore the result because water looks clear."}],"answer":"s24-c-l07-guided1-o0"},{"kind":"mc","prompt":"How can wastewater treatment reduce disease risk?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Waste treatment acts on a route of environmental exposure, but does not replace drinking-water controls.","id":"s24-c-l07-guided2","topic":"07","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l07-guided2-o0","text":"It reduces release of harmful material before water returns to the environment."},{"id":"s24-c-l07-guided2-o1","text":"It permanently removes every microbial and chemical hazard in one treatment step."},{"id":"s24-c-l07-guided2-o2","text":"It also guarantees that the separate drinking-water distribution system cannot fail."}],"answer":"s24-c-l07-guided2-o0"},{"kind":"mc","prompt":"An old workbook lists a fixed air-quality number band. What is the best way to advise someone today?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Air advisories depend on current measurement, location, index and personal context.","id":"s24-c-l07-independent1","topic":"07","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l07-independent1-o0","text":"Use a current local authority's index and time-specific advice."},{"id":"s24-c-l07-independent1-o1","text":"Treat a 2003 band as universal current law."},{"id":"s24-c-l07-independent1-o2","text":"Diagnose disease from the number alone."}],"answer":"s24-c-l07-independent1-o0"},{"kind":"mc","prompt":"Which statement about a landfill liner is defensible?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A control reduces a pathway; it is not proof of zero future risk.","id":"s24-c-l07-independent2","topic":"07","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l07-independent2-o0","text":"It is one design control whose effectiveness depends on construction, operation and monitoring."},{"id":"s24-c-l07-independent2-o1","text":"It guarantees no contaminant can ever reach water."},{"id":"s24-c-l07-independent2-o2","text":"It makes wastewater treatment unnecessary."}],"answer":"s24-c-l07-independent2-o0"},{"kind":"mc","prompt":"A learner blames a named worker for every Walkerton outcome from one timeline line. What is the reasoning flaw?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A timeline supports sequence and questions; it may not establish every person's responsibility.","id":"s24-c-l08-error","topic":"08","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l08-error-o0","text":"Assigning individual fault needs evidence beyond event order, including records of knowledge and authority."},{"id":"s24-c-l08-error-o1","text":"A timeline can identify a cause by itself, without testing the proposed pathway."},{"id":"s24-c-l08-error-o2","text":"One positive result should be dismissed without checking its meaning or location."}],"answer":"s24-c-l08-error-o0"},{"kind":"mc","prompt":"A risk-table row lists population growth. Which response matches the concern?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The response should address system demand and exposure pathways.","id":"s24-c-l08-guided1","topic":"08","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l08-guided1-o0","text":"Scale water, waste, surveillance and emergency communication capacity to the community."},{"id":"s24-c-l08-guided1-o1","text":"Treat crowding itself as an infectious agent instead of a factor affecting exposure."},{"id":"s24-c-l08-guided1-o2","text":"Remove all testing because there are more residents."}],"answer":"s24-c-l08-guided1-o0"},{"kind":"mc","prompt":"The workbook cites textbook p. 186, missing from the supplied PDF. What should the online course do?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Printed page references must match actual source pages; missing evidence stays visibly missing.","id":"s24-c-l08-guided2","topic":"08","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l08-guided2-o0","text":"State the gap and use the original workbook prompt or a teacher-provided timeline without inventing p. 186."},{"id":"s24-c-l08-guided2-o1","text":"Show printed p. 185 while labeling it p. 186."},{"id":"s24-c-l08-guided2-o2","text":"Claim the missing page was verified."}],"answer":"s24-c-l08-guided2-o0"},{"kind":"mc","prompt":"An adverse water result is recorded but not escalated. Which control addresses that failure?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Escalation connects a warning sign to the people and actions able to reduce exposure.","id":"s24-c-l08-independent1","topic":"08","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l08-independent1-o0","text":"A clear rule for prompt confirmation, responsible review and public communication when indicated."},{"id":"s24-c-l08-independent1-o1","text":"Assume recording alone prevents exposure."},{"id":"s24-c-l08-independent1-o2","text":"Wait for visible cloudiness before taking a positive test result seriously."}],"answer":"s24-c-l08-independent1-o0"},{"kind":"mc","prompt":"Which Walkerton response is evidence-based rather than blame-based?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The case asks for a justified mechanism and response tied to documented events.","id":"s24-c-l08-independent2","topic":"08","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l08-independent2-o0","text":"Identify a warning sign, its system control point and a testable prevention action."},{"id":"s24-c-l08-independent2-o1","text":"Name a group as inherently unsafe."},{"id":"s24-c-l08-independent2-o2","text":"Treat one anecdote as the full investigation."}],"answer":"s24-c-l08-independent2-o0"},{"kind":"mc","prompt":"A learner says redness after a sliver proves a particular bacterium is present. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Redness, warmth and swelling show a response but are not organism-specific evidence.","id":"s24-c-l09-error","topic":"09","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l09-error-o0","text":"Inflammation can follow sterile injury; symptoms alone do not identify an organism."},{"id":"s24-c-l09-error-o1","text":"Inflammation can only occur after vaccination."},{"id":"s24-c-l09-error-o2","text":"Redness alone identifies a specific inherited disorder."}],"answer":"s24-c-l09-error-o0"},{"kind":"mc","prompt":"Which structure helps move mucus and trapped particles along airways?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Cilia support clearance after mucus traps inhaled material.","id":"s24-c-l09-guided1","topic":"09","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l09-guided1-o0","text":"Cilia on airway cells."},{"id":"s24-c-l09-guided1-o1","text":"A blood cell circulating nearby, without crossing the damaged barrier."},{"id":"s24-c-l09-guided1-o2","text":"An antibody in the environment rather than a cell responding at the wound."}],"answer":"s24-c-l09-guided1-o0"},{"kind":"mc","prompt":"What can a macrophage do in an early response?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A macrophage is an immune cell that can engulf material; it is not an antibody molecule.","id":"s24-c-l09-guided2","topic":"09","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l09-guided2-o0","text":"Engulf microbes or debris and help coordinate further defence."},{"id":"s24-c-l09-guided2-o1","text":"Become a red-cell antigen."},{"id":"s24-c-l09-guided2-o2","text":"Inflammation immediately rebuilds the damaged skin barrier."}],"answer":"s24-c-l09-guided2-o0"},{"kind":"mc","prompt":"A student says a cough after smoke exposure proves infection. Which response is strongest?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A symptom can arise through more than one mechanism.","id":"s24-c-l09-independent1","topic":"09","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l09-independent1-o0","text":"Smoke can irritate airways and impair clearance; coughing alone does not diagnose infection."},{"id":"s24-c-l09-independent1-o1","text":"Coughing always has one bacterial cause."},{"id":"s24-c-l09-independent1-o2","text":"Smoke improves cilia movement in every case."}],"answer":"s24-c-l09-independent1-o0"},{"kind":"mc","prompt":"Why might a sliver site be warm and swollen?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Inflammation involves tissue signals, blood vessels and immune-cell movement.","id":"s24-c-l09-independent2","topic":"09","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l09-independent2-o0","text":"Local signals change blood flow and fluid movement while immune cells arrive."},{"id":"s24-c-l09-independent2-o1","text":"Inflammation converts damaged body cells into invading microbes."},{"id":"s24-c-l09-independent2-o2","text":"Only antibodies from a vaccine can cause warmth."}],"answer":"s24-c-l09-independent2-o0"},{"kind":"mc","prompt":"A learner calls an antibody the antigen on a microbe. What is the correction?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The two molecules have different roles in recognition and binding.","id":"s24-c-l10-error","topic":"10","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l10-error-o0","text":"An antigen is a recognized feature; an antibody is a protein that may bind a matching feature."},{"id":"s24-c-l10-error-o1","text":"Both words mean the same immune cell."},{"id":"s24-c-l10-error-o2","text":"Antigens are always antibiotics."}],"answer":"s24-c-l10-error-o0"},{"kind":"mc","prompt":"In the workbook's simplified five-step sequence, which event starts the model?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The model begins with encounter and early response before specific activation.","id":"s24-c-l10-guided1","topic":"10","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l10-guided1-o0","text":"A pathogen enters and early cells encounter it."},{"id":"s24-c-l10-guided1-o1","text":"Memory cells appear before any target exists."},{"id":"s24-c-l10-guided1-o2","text":"An antibody is made by a red blood cell."}],"answer":"s24-c-l10-guided1-o0"},{"kind":"mc","prompt":"Which is an example of passive immunity?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Passive protection supplies antibodies rather than forming the same active response.","id":"s24-c-l10-guided2","topic":"10","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l10-guided2-o0","text":"Receiving antibodies made by another source."},{"id":"s24-c-l10-guided2-o1","text":"Building one's own response after vaccination."},{"id":"s24-c-l10-guided2-o2","text":"Rebuilding a physical barrier rather than making a targeted immune response."}],"answer":"s24-c-l10-guided2-o0"},{"kind":"mc","prompt":"Why is the CBE chart's 'active immunity is permanent' claim too broad?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Active responses can persist but do not guarantee lifelong complete protection.","id":"s24-c-l10-independent1","topic":"10","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l10-independent1-o0","text":"Protection and memory can vary by agent, vaccine and time."},{"id":"s24-c-l10-independent1-o1","text":"Immune responses never form memory."},{"id":"s24-c-l10-independent1-o2","text":"Only passive antibodies exist."}],"answer":"s24-c-l10-independent1-o0"},{"kind":"mc","prompt":"A learner says antibodies alone directly destroy every pathogen. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The immune response is a coordinated network, not one universal killing step.","id":"s24-c-l10-independent2","topic":"10","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l10-independent2-o0","text":"Antibody binding can block or mark targets, while other cells and mechanisms may be needed."},{"id":"s24-c-l10-independent2-o1","text":"Antibodies are bacteria that divide independently."},{"id":"s24-c-l10-independent2-o2","text":"An antibody is a population-level warning rather than a protein in an immune response."}],"answer":"s24-c-l10-independent2-o0"},{"kind":"mc","prompt":"A learner says O-negative blood can always be given to anyone without tests. What is wrong?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A broad emergency red-cell donor type is not a universal no-test rule.","id":"s24-c-l11-error","topic":"11","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l11-error-o0","text":"The shorthand concerns red-cell compatibility; clinical selection and testing still matter."},{"id":"s24-c-l11-error-o1","text":"O-negative means all blood products are identical."},{"id":"s24-c-l11-error-o2","text":"The ABO system has no antigens."}],"answer":"s24-c-l11-error-o0"},{"kind":"mc","prompt":"What makes an A-to-B red-cell mismatch hazardous in the classroom model?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The model links red-cell antigens with the recipient's antibody response.","id":"s24-c-l11-guided1","topic":"11","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l11-guided1-o0","text":"A recipient's antibodies may react with incompatible donor red-cell antigens."},{"id":"s24-c-l11-guided1-o1","text":"Family relationship matters more than antigen matching for red-cell compatibility."},{"id":"s24-c-l11-guided1-o2","text":"A respiratory virus is the key factor in ABO red-cell matching."}],"answer":"s24-c-l11-guided1-o0"},{"kind":"mc","prompt":"Which statement describes modern vaccine platforms accurately?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The Canadian Immunization Guide describes more than the older two-category shorthand.","id":"s24-c-l11-guided2","topic":"11","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l11-guided2-o0","text":"Different vaccines may use attenuated organisms, inactivated material, components or mRNA approaches."},{"id":"s24-c-l11-guided2-o1","text":"Every vaccine is a dead whole pathogen."},{"id":"s24-c-l11-guided2-o2","text":"Every vaccine gives passive maternal antibodies."}],"answer":"s24-c-l11-guided2-o0"},{"kind":"mc","prompt":"A prepared antibody product and a vaccine are compared. Which difference matters?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The source of antibodies and potential immune memory differ.","id":"s24-c-l11-independent1","topic":"11","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l11-independent1-o0","text":"The product supplies antibodies; vaccination stimulates the recipient's own active response."},{"id":"s24-c-l11-independent1-o1","text":"Both always last forever."},{"id":"s24-c-l11-independent1-o2","text":"Both are red-cell transfusions."}],"answer":"s24-c-l11-independent1-o0"},{"kind":"mc","prompt":"How should the CBE vaccine/autism page be handled?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A dated source claim needs correction, not false balance.","id":"s24-c-l11-independent2","topic":"11","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l11-independent2-o0","text":"Exclude its false debate framing; the Canadian Immunization Guide states MMR does not cause autism."},{"id":"s24-c-l11-independent2-o1","text":"Teach both claims as equally supported scientific positions."},{"id":"s24-c-l11-independent2-o2","text":"Omit all vaccine science because the old page is wrong."}],"answer":"s24-c-l11-independent2-o0"},{"kind":"mc","prompt":"A learner says antibiotics make a person's body resistant so they no longer work. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Selection can increase resistant bacteria; the host's body is not the resistant organism.","id":"s24-c-l12-error","topic":"12","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l12-error-o0","text":"Resistance refers to bacteria able to survive a medicine, not the body becoming immune to it."},{"id":"s24-c-l12-error-o1","text":"Viruses are bacterial cells."},{"id":"s24-c-l12-error-o2","text":"A medicine that reduces symptoms also kills the organism causing them."}],"answer":"s24-c-l12-error-o0"},{"kind":"mc","prompt":"Why does an antibiotic not directly treat a typical viral cold?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Mechanism depends on the type of infectious agent.","id":"s24-c-l12-guided1","topic":"12","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l12-guided1-o0","text":"Its bacterial targets are not the cold virus's replication machinery."},{"id":"s24-c-l12-guided1-o1","text":"A viral infection always contains no symptoms."},{"id":"s24-c-l12-guided1-o2","text":"The dose is always too small for any illness."}],"answer":"s24-c-l12-guided1-o0"},{"kind":"mc","prompt":"Two non-prescription products list the same active ingredient. What is the first safety concern?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Ingredient lines and dose directions matter more than brand names.","id":"s24-c-l12-guided2","topic":"12","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l12-guided2-o0","text":"Combining them may duplicate the ingredient and exceed directions."},{"id":"s24-c-l12-guided2-o1","text":"Different brand names guarantee the active ingredients cannot overlap."},{"id":"s24-c-l12-guided2-o2","text":"Every combination is automatically safer."}],"answer":"s24-c-l12-guided2-o0"},{"kind":"mc","prompt":"A friend offers leftover antibiotics for a new illness. Which response matches current guidance?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Antibiotics need an appropriate indication and directed use.","id":"s24-c-l12-independent1","topic":"12","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l12-independent1-o0","text":"Do not share them; seek appropriate professional assessment and use medicines as directed."},{"id":"s24-c-l12-independent1-o1","text":"Use them because any infection is bacterial."},{"id":"s24-c-l12-independent1-o2","text":"Change the label instructions to fit the leftovers."}],"answer":"s24-c-l12-independent1-o0"},{"kind":"mc","prompt":"Why can unnecessary antibiotic use contribute to resistance?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Selection changes the composition of bacterial populations over time.","id":"s24-c-l12-independent2","topic":"12","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l12-independent2-o0","text":"It can select bacteria with traits that survive the drug and multiply."},{"id":"s24-c-l12-independent2-o1","text":"It trains the immune response by causing the body to produce an infection indefinitely."},{"id":"s24-c-l12-independent2-o2","text":"It sterilizes all environments permanently."}],"answer":"s24-c-l12-independent2-o0"},{"kind":"mc","prompt":"A learner says a gene, DNA and a chromosome are exactly the same object. What is the correction?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The three names refer to related but different scales of organization.","id":"s24-c-l13-error","topic":"13","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l13-error-o0","text":"A gene is a DNA region; chromosomes package long DNA molecules containing many genes."},{"id":"s24-c-l13-error-o1","text":"A visible chromosome shape directly reveals every gene on that chromosome."},{"id":"s24-c-l13-error-o2","text":"Chromosomes contain no DNA."}],"answer":"s24-c-l13-error-o0"},{"kind":"mc","prompt":"What letters pair across the rungs of A-G-C-T-G?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A pairs with T and C with G at each aligned position.","id":"s24-c-l13-guided1","topic":"13","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l13-guided1-o0","text":"T-C-G-A-C."},{"id":"s24-c-l13-guided1-o1","text":"A-G-C-T-G."},{"id":"s24-c-l13-guided1-o2","text":"G-A-T-C-A."}],"answer":"s24-c-l13-guided1-o0"},{"kind":"mc","prompt":"A karyotype shows three copies of chromosome 21. What pattern is visible?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The image can show a chromosome-number difference at the labelled pair.","id":"s24-c-l13-guided2","topic":"13","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l13-guided2-o0","text":"Trisomy 21."},{"id":"s24-c-l13-guided2-o1","text":"A one-letter DNA substitution."},{"id":"s24-c-l13-guided2-o2","text":"Proof of every future health outcome."}],"answer":"s24-c-l13-guided2-o0"},{"kind":"mc","prompt":"A student uses XX/XY as a universal rule for a person's gender. What is the problem?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Genomic variation and personal identity exceed a simplified classroom karyotype model.","id":"s24-c-l13-independent1","topic":"13","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l13-independent1-o0","text":"They are common chromosome patterns with variations and do not establish gender identity."},{"id":"s24-c-l13-independent1-o1","text":"Chromosomes cannot be observed."},{"id":"s24-c-l13-independent1-o2","text":"Every human body cell contains one unpaired chromosome."}],"answer":"s24-c-l13-independent1-o0"},{"kind":"mc","prompt":"Which claim is beyond what a karyotype image alone can show?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Karyotypes show large patterns, not all sequence-level or future information.","id":"s24-c-l13-independent2","topic":"13","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l13-independent2-o0","text":"A karyotype reveals every small sequence variant and predicts a precise lifetime outcome."},{"id":"s24-c-l13-independent2-o1","text":"The number of visible chromosome 21 copies."},{"id":"s24-c-l13-independent2-o2","text":"Whether a labelled pair appears in the display."}],"answer":"s24-c-l13-independent2-o0"},{"kind":"mc","prompt":"A learner says a four-box Punnett square promises four children with one outcome each. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Each offspring is another possible outcome under the model.","id":"s24-c-l14-error","topic":"14","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l14-error-o0","text":"Boxes show possible allele combinations and probabilities, not guaranteed family outcomes."},{"id":"s24-c-l14-error-o1","text":"The four boxes record four children who have already been born."},{"id":"s24-c-l14-error-o2","text":"Each child must use a different box."}],"answer":"s24-c-l14-error-o0"},{"kind":"mc","prompt":"What gametes can a Tt plant contribute in the simple model?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A gamete receives one allele for the modeled gene.","id":"s24-c-l14-guided1","topic":"14","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l14-guided1-o0","text":"T or t."},{"id":"s24-c-l14-guided1-o1","text":"Only TT."},{"id":"s24-c-l14-guided1-o2","text":"Only tt."}],"answer":"s24-c-l14-guided1-o0"},{"kind":"mc","prompt":"What genotype ratio comes from Ww × Ww?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Combining W and w from each parent gives WW, Ww, Ww and ww.","id":"s24-c-l14-guided2","topic":"14","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l14-guided2-o0","text":"1 WW : 2 Ww : 1 ww."},{"id":"s24-c-l14-guided2-o1","text":"4 WW : 0 Ww : 0 ww."},{"id":"s24-c-l14-guided2-o2","text":"1 WW : 1 ww with no heterozygotes."}],"answer":"s24-c-l14-guided2-o0"},{"kind":"mc","prompt":"If white wool is dominant to black, what phenotype ratio does Ww × Ww predict?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Three of four equally likely boxes have at least one dominant W allele.","id":"s24-c-l14-independent1","topic":"14","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l14-independent1-o0","text":"3 white : 1 black in the simplified model."},{"id":"s24-c-l14-independent1-o1","text":"1 white : 3 black."},{"id":"s24-c-l14-independent1-o2","text":"Four black lambs guaranteed."}],"answer":"s24-c-l14-independent1-o0"},{"kind":"mc","prompt":"Why must the workbook's brown/blue human-eye-colour square have a caution note?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The model teaches allele bookkeeping but not a reliable personal eye-colour forecast.","id":"s24-c-l14-independent2","topic":"14","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l14-independent2-o0","text":"Real eye colour involves multiple genes; the one-gene rule is a classroom simplification."},{"id":"s24-c-l14-independent2-o1","text":"One allele pair is enough to predict every detail of human eye colour."},{"id":"s24-c-l14-independent2-o2","text":"The four boxes guarantee four specific children."}],"answer":"s24-c-l14-independent2-o0"},{"kind":"mc","prompt":"A learner uses the named-family pedigree from workbook p. 31 to answer Q12 on p. 32. What is the error?","hint":"Check the printed question number and the figure immediately above it before interpreting the pattern.","explanation":"Q11 and Q12 use different pedigrees. Evidence from the named-family chart on p. 31 cannot replace the separate Q12 chart on p. 32.","id":"s24-c-v4-l15-error","topic":"15","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-v4-l15-error-o0","text":"Q12 has its own pedigree on p. 32, so its inheritance claim must be tested against that figure."},{"id":"s24-c-v4-l15-error-o1","text":"The family names on p. 31 automatically apply to every later pedigree."},{"id":"s24-c-v4-l15-error-o2","text":"Shading has the same meaning as a person’s name."}],"answer":"s24-c-v4-l15-error-o0"},{"kind":"mc","prompt":"How many generations appear on workbook p. 31?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Generation count follows horizontal descent levels, not affected count.","id":"s24-c-l15-guided1","topic":"15","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l15-guided1-o0","text":"Three."},{"id":"s24-c-l15-guided1-o1","text":"Two, because only two shaded people appear."},{"id":"s24-c-l15-guided1-o2","text":"Four, because four names are shaded."}],"answer":"s24-c-l15-guided1-o0"},{"kind":"mc","prompt":"Which named people are shaded in the source pedigree?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The page key defines shading as affected status; read each named symbol.","id":"s24-c-l15-guided2","topic":"15","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l15-guided2-o0","text":"Sue, Joe, Jim and Tim."},{"id":"s24-c-l15-guided2-o1","text":"Tom, Sara, Kay and Lori."},{"id":"s24-c-l15-guided2-o2","text":"Only Sue and Kay."}],"answer":"s24-c-l15-guided2-o0"},{"kind":"mc","prompt":"How many children does Jim have in the drawn family?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Follow Jim and Kay's parent line to their two descendants.","id":"s24-c-l15-independent1","topic":"15","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l15-independent1-o0","text":"Two: Tim and Lori."},{"id":"s24-c-l15-independent1-o1","text":"Four: Sue, Joe, Tim and Lori."},{"id":"s24-c-l15-independent1-o2","text":"One: Kay."}],"answer":"s24-c-l15-independent1-o0"},{"kind":"mc","prompt":"Which feature of the separate Q12 pedigree supports a recessive interpretation in the intended simple model?","hint":"Look for an affected child whose two parents do not display the modeled trait.","explanation":"The Q12 chart includes two unshaded parents with a shaded child. In the intended fully penetrant dominant-or-recessive classroom model, both parents can be unaffected carriers of a recessive allele.","id":"s24-c-v4-l15-independent2","topic":"15","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-v4-l15-independent2-o0","text":"Two parents who do not display the trait have a child who does display it."},{"id":"s24-c-v4-l15-independent2-o1","text":"Every person in the pedigree displays the trait."},{"id":"s24-c-v4-l15-independent2-o2","text":"The chart prints every person’s genotype."}],"answer":"s24-c-v4-l15-independent2-o0"},{"kind":"mc","prompt":"A learner says every mutation is harmful and inherited. What is the correction?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Location, effect and cell lineage matter before claiming harm or inheritance.","id":"s24-c-l16-error","topic":"16","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l16-error-o0","text":"Effects vary, and a body-cell change is not automatically passed to children."},{"id":"s24-c-l16-error-o1","text":"Every mutation produces an obvious beneficial trait."},{"id":"s24-c-l16-error-o2","text":"Every DNA difference is visible on a karyotype."}],"answer":"s24-c-l16-error-o0"},{"kind":"mc","prompt":"What makes a body-cell change different from one in a reproductive-cell lineage?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Inheritance requires a route through egg or sperm formation.","id":"s24-c-l16-guided1","topic":"16","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l16-guided1-o0","text":"Only a change in reproductive cells normally has a direct route to offspring."},{"id":"s24-c-l16-guided1-o1","text":"Body cells contain no DNA."},{"id":"s24-c-l16-guided1-o2","text":"A reproductive cell cannot contain variants."}],"answer":"s24-c-l16-guided1-o0"},{"kind":"mc","prompt":"A base is copied differently and repair corrects it. What follows?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Repair can prevent a transient copying error from becoming a lasting sequence change.","id":"s24-c-l16-guided2","topic":"16","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l16-guided2-o0","text":"The copying error need not persist as a new variant in that lineage."},{"id":"s24-c-l16-guided2-o1","text":"A genetic disorder is guaranteed."},{"id":"s24-c-l16-guided2-o2","text":"Every DNA copying error changes the total chromosome count."}],"answer":"s24-c-l16-guided2-o0"},{"kind":"mc","prompt":"Why can't exposure to a mutagen prove a specific future disorder?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Risk is probabilistic and mechanism-specific, not an individual guarantee.","id":"s24-c-l16-independent1","topic":"16","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l16-independent1-o0","text":"Exposure may raise risk, but dose, repair, location and chance affect outcomes."},{"id":"s24-c-l16-independent1-o1","text":"Mutagens have no possible effects."},{"id":"s24-c-l16-independent1-o2","text":"A given exposure always causes the same mutation and outcome in every person."}],"answer":"s24-c-l16-independent1-o0"},{"kind":"mc","prompt":"Which statement about amniocentesis is appropriate for this course?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The course can analyze evidence and ethics without making an individual medical decision.","id":"s24-c-l16-independent2","topic":"16","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l16-independent2-o0","text":"It involves possible information, procedure risks and personal decisions needing clinical counselling."},{"id":"s24-c-l16-independent2-o1","text":"The class should choose it for each pregnant person."},{"id":"s24-c-l16-independent2-o2","text":"It guarantees the child's whole future."}],"answer":"s24-c-l16-independent2-o0"},{"kind":"mc","prompt":"A headline says a genetic test proves someone will develop a complex disease. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Genetic association or screening result is not always a certain personal forecast.","id":"s24-c-l17-error","topic":"17","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l17-error-o0","text":"Predictive strength, other genes, environment, age and uncertainty."},{"id":"s24-c-l17-error-o1","text":"More precise-looking chart colours without stronger evidence."},{"id":"s24-c-l17-error-o2","text":"A claim that genetic results can never inform any health decision."}],"answer":"s24-c-l17-error-o0"},{"kind":"mc","prompt":"What makes consent meaningful in a genetic study?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Informed consent includes comprehension and choice about the proposed use.","id":"s24-c-l17-guided1","topic":"17","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l17-guided1-o0","text":"Understanding purpose, data use, risks and alternatives before a voluntary decision."},{"id":"s24-c-l17-guided1-o1","text":"A signature obtained without explanation."},{"id":"s24-c-l17-guided1-o2","text":"A decision based on a headline without checking the original evidence."}],"answer":"s24-c-l17-guided1-o0"},{"kind":"mc","prompt":"Why can genetic privacy matter to relatives?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Family relationships make some genetic findings relevant beyond one data record.","id":"s24-c-l17-guided2","topic":"17","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l17-guided2-o0","text":"Shared inherited information may imply something about family members too."},{"id":"s24-c-l17-guided2-o1","text":"Relatives have identical genetic information whenever they share a pedigree."},{"id":"s24-c-l17-guided2-o2","text":"Genetic data are never personal."}],"answer":"s24-c-l17-guided2-o0"},{"kind":"mc","prompt":"The workbook asks about cloning someone to harvest organs. Which response is ethical reasoning?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A justified response separates a technology claim from the rights of affected people.","id":"s24-c-l17-independent1","topic":"17","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l17-independent1-o0","text":"Assess claimed benefit, harm, consent, dignity, fairness and alternatives rather than treating a person as a resource."},{"id":"s24-c-l17-independent1-o1","text":"Assume the hypothetical is standard clinical practice."},{"id":"s24-c-l17-independent1-o2","text":"Use an unsupported slogan rather than evidence about benefits and harms."}],"answer":"s24-c-l17-independent1-o0"},{"kind":"mc","prompt":"A dated chart calls an idea an 'advance'. What should be checked?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Research examples change; source context and present evidence must be kept separate.","id":"s24-c-l17-independent2","topic":"17","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l17-independent2-o0","text":"Its date, evidence, current status, limits and who benefits or bears risk."},{"id":"s24-c-l17-independent2-o1","text":"A professional-looking logo is enough to establish the chart’s evidence."},{"id":"s24-c-l17-independent2-o2","text":"Whether the old prediction sounds exciting."}],"answer":"s24-c-l17-independent2-o0"}],"fill-in-the-blanks":[{"id":"s24-c-word-disease-blank","kind":"text","topic":"01","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A condition that disrupts normal body function or health.","answers":["disease"],"hint":"An infection can cause disease, but an inherited condition can too.","explanation":"disease: A condition that disrupts normal body function or health. Disease names an outcome; it does not by itself identify a cause."},{"id":"s24-c-word-pathogen-blank","kind":"text","topic":"01","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An agent able to cause disease in a host.","answers":["pathogen"],"hint":"Some Salmonella bacteria can cause foodborne illness.","explanation":"pathogen: An agent able to cause disease in a host. Most microorganisms are not pathogens."},{"id":"s24-c-word-germ-theory-blank","kind":"text","topic":"01","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: The evidence-based idea that specific microorganisms can cause infectious diseases.","answers":["germ theory"],"hint":"Compare an organism found in cases with evidence from controls.","explanation":"germ theory: The evidence-based idea that specific microorganisms can cause infectious diseases. It does not claim all disease is infectious."},{"id":"s24-c-word-risk-factor-blank","kind":"text","topic":"01","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A condition or exposure associated with a changed chance of an outcome.","answers":["risk factor"],"hint":"Improper food temperature can increase foodborne illness risk.","explanation":"risk factor: A condition or exposure associated with a changed chance of an outcome. A risk factor is not the same as a confirmed diagnosis."},{"id":"s24-c-word-bacterium-blank","kind":"text","topic":"02","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A single-celled organism; some species can cause disease.","answers":["bacterium"],"hint":"A foodborne bacterium may multiply under suitable conditions.","explanation":"bacterium: A single-celled organism; some species can cause disease. Bacteria are cells; viruses use host cells to replicate."},{"id":"s24-c-word-virus-blank","kind":"text","topic":"02","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An infectious agent that uses a host cell to make new virus particles.","answers":["virus"],"hint":"A respiratory virus can spread between people.","explanation":"virus: An infectious agent that uses a host cell to make new virus particles. A virus does not divide independently like a bacterial cell."},{"id":"s24-c-word-protist-blank","kind":"text","topic":"02","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A diverse eukaryotic group that includes some parasites.","answers":["protist"],"hint":"Giardia can spread through contaminated water.","explanation":"protist: A diverse eukaryotic group that includes some parasites. Protist does not mean all members cause disease."},{"id":"s24-c-word-fungus-blank","kind":"text","topic":"02","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A group of organisms including yeasts and moulds; some cause infections.","answers":["fungus"],"hint":"A fungus can cause athlete's foot.","explanation":"fungus: A group of organisms including yeasts and moulds; some cause infections. A fungal infection is not a bacterial infection."},{"id":"s24-c-word-communicable-disease-blank","kind":"text","topic":"03","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A disease that can spread between hosts through a transmission route.","answers":["communicable disease"],"hint":"A respiratory infection may spread between people.","explanation":"communicable disease: A disease that can spread between hosts through a transmission route. Spreadability differs from severity."},{"id":"s24-c-word-non-communicable-disease-blank","kind":"text","topic":"03","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A disease not spread from person to person by an infectious agent.","answers":["non-communicable disease"],"hint":"Some inherited disorders are non-communicable.","explanation":"non-communicable disease: A disease not spread from person to person by an infectious agent. Non-communicable does not mean there is only one cause."},{"id":"s24-c-word-transmission-route-blank","kind":"text","topic":"03","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: The pathway an infectious agent takes between source and host.","answers":["transmission route"],"hint":"Contaminated water can carry a pathogen into the digestive tract.","explanation":"transmission route: The pathway an infectious agent takes between source and host. The route is not identical to the social condition that permits exposure."},{"id":"s24-c-word-health-inequity-blank","kind":"text","topic":"03","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An avoidable and unfair difference in health opportunities or outcomes linked to social conditions.","answers":["health inequity"],"hint":"Unequal access to treated water can change exposure risk.","explanation":"health inequity: An avoidable and unfair difference in health opportunities or outcomes linked to social conditions. It is not a judgment about a person's worth or choices."},{"id":"s24-c-word-food-preservation-blank","kind":"text","topic":"04","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Processing or storage used to slow spoilage or reduce food-safety hazards.","answers":["food preservation"],"hint":"Refrigeration slows many microbial growth processes.","explanation":"food preservation: Processing or storage used to slow spoilage or reduce food-safety hazards. It is not a guarantee of sterility."},{"id":"s24-c-word-pasteurization-blank","kind":"text","topic":"04","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Controlled heating that reduces specified harmful microbes in a product.","answers":["pasteurization"],"hint":"Commercial milk is commonly pasteurized.","explanation":"pasteurization: Controlled heating that reduces specified harmful microbes in a product. Pasteurization differs from sterilization and later safe storage still matters."},{"id":"s24-c-word-cross-contamination-blank","kind":"text","topic":"04","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Transfer of harmful material from one food or surface to another.","answers":["cross-contamination"],"hint":"An unwashed board transfers raw-meat microbes to salad.","explanation":"cross-contamination: Transfer of harmful material from one food or surface to another. Cooling after transfer does not undo contamination."},{"id":"s24-c-word-refrigeration-blank","kind":"text","topic":"04","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Cold storage that slows many biological and chemical changes.","answers":["refrigeration"],"hint":"A chilled lunch stays colder than one left on a counter.","explanation":"refrigeration: Cold storage that slows many biological and chemical changes. Cold storage does not necessarily kill pathogens."},{"id":"s24-c-word-antiseptic-blank","kind":"text","topic":"05","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A product intended to reduce microorganisms on living tissue when used as directed.","answers":["antiseptic"],"hint":"Some first-aid products are labeled for skin.","explanation":"antiseptic: A product intended to reduce microorganisms on living tissue when used as directed. It is not interchangeable with a hard-surface disinfectant."},{"id":"s24-c-word-disinfectant-blank","kind":"text","topic":"05","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A product or process used to reduce specified microorganisms on suitable non-living surfaces.","answers":["disinfectant"],"hint":"A labeled product may be used on a counter as directed.","explanation":"disinfectant: A product or process used to reduce specified microorganisms on suitable non-living surfaces. Disinfection is not necessarily sterilization."},{"id":"s24-c-word-sterilization-blank","kind":"text","topic":"05","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A validated process intended to eliminate all viable microorganisms from an item.","answers":["sterilization"],"hint":"Specialized equipment can sterilize suitable instruments.","explanation":"sterilization: A validated process intended to eliminate all viable microorganisms from an item. A quick wipe or cold storage is not sterilization."},{"id":"s24-c-word-aseptic-technique-blank","kind":"text","topic":"05","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A set of practices that prevents contamination during a task.","answers":["aseptic technique"],"hint":"Keeping prepared equipment away from unclean surfaces is aseptic practice.","explanation":"aseptic technique: A set of practices that prevents contamination during a task. It is a procedure, not a chemical product."},{"id":"s24-c-word-outbreak-blank","kind":"text","topic":"06","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: More cases than expected in a defined place and time.","answers":["outbreak"],"hint":"An unusual cluster at one school can trigger an investigation.","explanation":"outbreak: More cases than expected in a defined place and time. It does not by itself mean worldwide spread."},{"id":"s24-c-word-epidemic-blank","kind":"text","topic":"06","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An increase above expected cases across a population or region.","answers":["epidemic"],"hint":"A regional rise over several weeks may be an epidemic.","explanation":"epidemic: An increase above expected cases across a population or region. Severity and geographic spread are different questions."},{"id":"s24-c-word-pandemic-blank","kind":"text","topic":"06","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An epidemic that has spread across multiple countries or continents.","answers":["pandemic"],"hint":"The 1918 influenza pandemic affected many regions.","explanation":"pandemic: An epidemic that has spread across multiple countries or continents. A single local outbreak is not a pandemic."},{"id":"s24-c-word-historical-context-blank","kind":"text","topic":"06","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: The time, place, social conditions and evidence needed to interpret a past event.","answers":["historical context"],"hint":"Compare 1918 reports with the care and reporting available then.","explanation":"historical context: The time, place, social conditions and evidence needed to interpret a past event. A dated figure is not automatically a current statistic."},{"id":"s24-c-word-water-treatment-blank","kind":"text","topic":"07","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Processes used to reduce hazards in drinking water before distribution.","answers":["water treatment"],"hint":"Filtration and disinfection may be parts of a treatment system.","explanation":"water treatment: Processes used to reduce hazards in drinking water before distribution. Clear appearance alone does not show effective treatment."},{"id":"s24-c-word-surveillance-blank","kind":"text","topic":"07","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Systematic collection and interpretation of health or environmental information.","answers":["surveillance"],"hint":"Regular water samples can reveal a changing pattern.","explanation":"surveillance: Systematic collection and interpretation of health or environmental information. One observation is not a complete trend."},{"id":"s24-c-word-wastewater-blank","kind":"text","topic":"07","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Used water containing human or other wastes that needs management.","answers":["wastewater"],"hint":"A community treatment plant reduces release of harmful material.","explanation":"wastewater: Used water containing human or other wastes that needs management. It is not the same as untreated drinking water."},{"id":"s24-c-word-public-advisory-blank","kind":"text","topic":"07","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A time- and place-specific notice that recommends protective action.","answers":["public advisory"],"hint":"A water or air notice may guide temporary behaviour.","explanation":"public advisory: A time- and place-specific notice that recommends protective action. It is not an individual diagnosis."},{"id":"s24-c-word-risk-assessment-blank","kind":"text","topic":"08","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A structured comparison of hazards, exposure, likelihood and possible consequences.","answers":["risk assessment"],"hint":"A water operator assesses a positive sample and possible users exposed.","explanation":"risk assessment: A structured comparison of hazards, exposure, likelihood and possible consequences. A hazard name alone is not a complete risk estimate."},{"id":"s24-c-word-public-health-guideline-blank","kind":"text","topic":"08","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A recommendation or rule intended to reduce a stated population health risk.","answers":["public-health guideline"],"hint":"A sampling and notification protocol guides water-system action.","explanation":"public-health guideline: A recommendation or rule intended to reduce a stated population health risk. A guideline should be tied to mechanism and evidence."},{"id":"s24-c-word-warning-sign-blank","kind":"text","topic":"08","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An observation that calls for investigation or action.","answers":["warning sign"],"hint":"An unexpected test result can be a warning sign.","explanation":"warning sign: An observation that calls for investigation or action. It is not necessarily a final diagnosis of the whole system."},{"id":"s24-c-word-escalation-blank","kind":"text","topic":"08","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Passing a concern to the person or authority able to act, following a defined process.","answers":["escalation"],"hint":"A confirmed test result triggers timely review and public notice when appropriate.","explanation":"escalation: Passing a concern to the person or authority able to act, following a defined process. Recording a concern without action is not complete escalation."},{"id":"s24-c-word-barrier-defence-blank","kind":"text","topic":"09","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A body surface or substance that reduces pathogen entry.","answers":["barrier defence"],"hint":"Intact skin blocks many external organisms.","explanation":"barrier defence: A body surface or substance that reduces pathogen entry. A barrier is not an antibody response."},{"id":"s24-c-word-cilia-blank","kind":"text","topic":"09","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Tiny moving projections that help move mucus and trapped particles along airways.","answers":["cilia"],"hint":"Airway cilia help clear inhaled material.","explanation":"cilia: Tiny moving projections that help move mucus and trapped particles along airways. Cilia are not the same as body hair."},{"id":"s24-c-word-inflammation-blank","kind":"text","topic":"09","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A local response to injury or infection involving signals, blood vessels and immune cells.","answers":["inflammation"],"hint":"A sliver may lead to redness and swelling.","explanation":"inflammation: A local response to injury or infection involving signals, blood vessels and immune cells. It does not by itself prove a bacterial infection."},{"id":"s24-c-word-macrophage-blank","kind":"text","topic":"09","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An immune cell that can engulf material and help coordinate responses.","answers":["macrophage"],"hint":"A macrophage may engulf microbes in damaged tissue.","explanation":"macrophage: An immune cell that can engulf material and help coordinate responses. It is a cell, not an antibody molecule."},{"id":"s24-c-word-antigen-blank","kind":"text","topic":"10","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A feature that can be recognized by an immune response.","answers":["antigen"],"hint":"A protein on a microbe may act as an antigen.","explanation":"antigen: A feature that can be recognized by an immune response. An antigen is not the same molecule as an antibody."},{"id":"s24-c-word-antibody-blank","kind":"text","topic":"10","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A protein produced by B-cell descendants that binds a matching target.","answers":["antibody"],"hint":"An antibody may bind a matching viral surface feature.","explanation":"antibody: A protein produced by B-cell descendants that binds a matching target. Binding alone is not the whole immune response."},{"id":"s24-c-word-active-immunity-blank","kind":"text","topic":"10","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Protection developed through a person's own immune response after infection or vaccination.","answers":["active immunity"],"hint":"Vaccination can stimulate immune memory.","explanation":"active immunity: Protection developed through a person's own immune response after infection or vaccination. It is not necessarily lifelong or complete."},{"id":"s24-c-word-passive-immunity-blank","kind":"text","topic":"10","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Temporary protection supplied by antibodies from another source.","answers":["passive immunity"],"hint":"Some maternal antibodies pass to an infant.","explanation":"passive immunity: Temporary protection supplied by antibodies from another source. The recipient has not made those antibodies through the same active response."},{"id":"s24-c-word-blood-group-antigen-blank","kind":"text","topic":"11","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A marker on red blood cells used in a compatibility model.","answers":["blood-group antigen"],"hint":"A-type red cells carry A antigen.","explanation":"blood-group antigen: A marker on red blood cells used in a compatibility model. It is not the whole clinical compatibility result."},{"id":"s24-c-word-rhd-blank","kind":"text","topic":"11","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An antigen used in the positive/negative part of common red-cell typing.","answers":["RhD"],"hint":"O-negative red cells lack RhD antigen.","explanation":"RhD: An antigen used in the positive/negative part of common red-cell typing. RhD is only one of several clinically important markers."},{"id":"s24-c-word-vaccine-blank","kind":"text","topic":"11","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A preparation that stimulates an immune response to a specified target.","answers":["vaccine"],"hint":"A vaccine may use a pathogen component or mRNA platform.","explanation":"vaccine: A preparation that stimulates an immune response to a specified target. Vaccines are not all weakened or dead whole pathogens."},{"id":"s24-c-word-immune-memory-blank","kind":"text","topic":"11","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A lasting capacity of some immune cells to respond to a previously encountered target.","answers":["immune memory"],"hint":"A later exposure may trigger a faster response.","explanation":"immune memory: A lasting capacity of some immune cells to respond to a previously encountered target. Memory does not guarantee absolute or lifelong protection."},{"id":"s24-c-word-antibiotic-blank","kind":"text","topic":"12","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A medicine used to treat or prevent certain bacterial infections.","answers":["antibiotic"],"hint":"A clinician may prescribe one for a confirmed or likely bacterial infection.","explanation":"antibiotic: A medicine used to treat or prevent certain bacterial infections. It does not directly treat a viral cold."},{"id":"s24-c-word-antibiotic-resistance-blank","kind":"text","topic":"12","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: The ability of bacteria to survive an antibiotic that previously worked against them.","answers":["antibiotic resistance"],"hint":"A resistant bacterial strain may spread under selection.","explanation":"antibiotic resistance: The ability of bacteria to survive an antibiotic that previously worked against them. It is the microbes, not the patient's body, that become resistant."},{"id":"s24-c-word-active-ingredient-blank","kind":"text","topic":"12","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: The substance in a medicine responsible for its intended effect.","answers":["active ingredient"],"hint":"Two brands may contain the same active ingredient.","explanation":"active ingredient: The substance in a medicine responsible for its intended effect. Brand names do not prove different ingredients."},{"id":"s24-c-word-over-the-counter-medicine-blank","kind":"text","topic":"12","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A medicine available without an individual prescription, with directions and warnings.","answers":["over-the-counter medicine"],"hint":"A cold symptom product may be sold over the counter.","explanation":"over-the-counter medicine: A medicine available without an individual prescription, with directions and warnings. Available without prescription does not mean risk-free."},{"id":"s24-c-word-dna-blank","kind":"text","topic":"13","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A molecule that carries hereditary information in a sequence of bases.","answers":["DNA"],"hint":"A and T pair across a DNA double strand.","explanation":"DNA: A molecule that carries hereditary information in a sequence of bases. DNA is the material, not the whole chromosome image."},{"id":"s24-c-word-gene-blank","kind":"text","topic":"13","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A DNA region whose information contributes to a functional product.","answers":["gene"],"hint":"A gene may help specify a protein.","explanation":"gene: A DNA region whose information contributes to a functional product. A complex trait is not always controlled by one gene."},{"id":"s24-c-word-chromosome-blank","kind":"text","topic":"13","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An organized DNA-containing structure visible in a karyotype during cell division.","answers":["chromosome"],"hint":"Chromosome 21 appears in a pair in a typical body-cell set.","explanation":"chromosome: An organized DNA-containing structure visible in a karyotype during cell division. A chromosome contains many genes."},{"id":"s24-c-word-karyotype-blank","kind":"text","topic":"13","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An arranged image of chromosomes used to inspect number and large structural patterns.","answers":["karyotype"],"hint":"An extra chromosome 21 is visible in a karyotype.","explanation":"karyotype: An arranged image of chromosomes used to inspect number and large structural patterns. It does not reveal every DNA variant or a person's gender identity."},{"id":"s24-c-word-allele-blank","kind":"text","topic":"14","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A version of a gene used in an inheritance model.","answers":["allele"],"hint":"T and t represent two versions for a plant-height model.","explanation":"allele: A version of a gene used in an inheritance model. An allele is not a whole chromosome."},{"id":"s24-c-word-genotype-blank","kind":"text","topic":"14","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: The allele combination assigned to an organism for the trait being modeled.","answers":["genotype"],"hint":"Tt is one plant genotype.","explanation":"genotype: The allele combination assigned to an organism for the trait being modeled. Genotype letters are not the same as observed height."},{"id":"s24-c-word-phenotype-blank","kind":"text","topic":"14","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An observable trait or characteristic produced through genes and often environment.","answers":["phenotype"],"hint":"A Tt plant may be tall in the model.","explanation":"phenotype: An observable trait or characteristic produced through genes and often environment. One phenotype need not correspond to only one genotype."},{"id":"s24-c-word-punnett-square-blank","kind":"text","topic":"14","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A grid for organizing possible allele combinations from two parents.","answers":["Punnett square"],"hint":"A Tt × tt grid has two Tt and two tt cells.","explanation":"Punnett square: A grid for organizing possible allele combinations from two parents. Four cells are probabilities, not a family prediction."},{"id":"s24-c-word-pedigree-blank","kind":"text","topic":"15","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A diagram showing relationships and a trait's observed status across generations.","answers":["pedigree"],"hint":"Workbook p. 31 shows Sue, Joe, Jim and Tim shaded.","explanation":"pedigree: A diagram showing relationships and a trait's observed status across generations. It does not automatically reveal every genotype."},{"id":"s24-c-word-generation-blank","kind":"text","topic":"15","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: People placed at the same level of descent in a pedigree.","answers":["generation"],"hint":"The workbook diagram has three generation rows.","explanation":"generation: People placed at the same level of descent in a pedigree. A row is not a count of children for one person."},{"id":"s24-c-word-carrier-blank","kind":"text","topic":"15","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: In a recessive model, a person who has one recessive allele but does not show the modeled condition.","answers":["carrier"],"hint":"An unshaded partner could be a carrier in a possible recessive explanation.","explanation":"carrier: In a recessive model, a person who has one recessive allele but does not show the modeled condition. Unshaded status does not prove carrier status."},{"id":"s24-c-word-evidence-limit-blank","kind":"text","topic":"15","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A boundary on what the given observations can establish.","answers":["evidence limit"],"hint":"Missing genotypes prevent a unique dominance conclusion in Q12.","explanation":"evidence limit: A boundary on what the given observations can establish. Uncertainty is not a reason to ignore the clear family relationships."},{"id":"s24-c-word-mutation-blank","kind":"text","topic":"16","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A change in DNA sequence or chromosome structure/number in a specified context.","answers":["mutation"],"hint":"A copying error can change one DNA base.","explanation":"mutation: A change in DNA sequence or chromosome structure/number in a specified context. Mutation does not always mean harmful disease."},{"id":"s24-c-word-mutagen-blank","kind":"text","topic":"16","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: An agent or exposure that can increase the rate of DNA changes.","answers":["mutagen"],"hint":"Some forms of radiation can damage DNA.","explanation":"mutagen: An agent or exposure that can increase the rate of DNA changes. Exposure is not a guaranteed disorder."},{"id":"s24-c-word-genetic-disorder-blank","kind":"text","topic":"16","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A health condition related to particular genetic changes, often with varied expression.","answers":["genetic disorder"],"hint":"Trisomy 21 is a chromosome-number condition.","explanation":"genetic disorder: A health condition related to particular genetic changes, often with varied expression. A genetic finding does not tell the whole story of a person."},{"id":"s24-c-word-inherited-variant-blank","kind":"text","topic":"16","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A genetic difference passed through a reproductive cell from a parent.","answers":["inherited variant"],"hint":"A child can inherit an allele present in a parent's egg or sperm.","explanation":"inherited variant: A genetic difference passed through a reproductive cell from a parent. A body-cell-only change is not automatically inherited."},{"id":"s24-c-word-genetic-research-blank","kind":"text","topic":"17","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Systematic study of genes, variants and their relationships to function or health.","answers":["genetic research"],"hint":"Researchers compare variant patterns and outcomes.","explanation":"genetic research: Systematic study of genes, variants and their relationships to function or health. A research association is not always a causal diagnosis."},{"id":"s24-c-word-genetic-screening-blank","kind":"text","topic":"17","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Testing used to look for specified genetic patterns or risks.","answers":["genetic screening"],"hint":"A screen may identify a chromosome pattern needing interpretation.","explanation":"genetic screening: Testing used to look for specified genetic patterns or risks. A screen is not a complete prediction of a person's future."},{"id":"s24-c-word-informed-consent-blank","kind":"text","topic":"17","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: A person's voluntary decision after understanding purpose, risks and alternatives.","answers":["informed consent"],"hint":"A participant agrees to a genetic study after reviewing its use of data.","explanation":"informed consent: A person's voluntary decision after understanding purpose, risks and alternatives. A signature without understanding is not enough."},{"id":"s24-c-word-genetic-privacy-blank","kind":"text","topic":"17","difficulty":"Foundation","role":"retrieval","prompt":"Name the term: Control and protection of information about a person's genetic data.","answers":["genetic privacy"],"hint":"A research project limits access to individual results.","explanation":"genetic privacy: Control and protection of information about a person's genetic data. Anonymized-looking data may still carry privacy concerns."}],"practice":[{"id":"s24-c-word-disease-flash","kind":"flash","topic":"01","difficulty":"Foundation","prompt":"Explain disease and give an example.","answer":"A condition that disrupts normal body function or health. Example: An infection can cause disease, but an inherited condition can too."},{"id":"s24-c-word-pathogen-flash","kind":"flash","topic":"01","difficulty":"Foundation","prompt":"Explain pathogen and give an example.","answer":"An agent able to cause disease in a host. Example: Some Salmonella bacteria can cause foodborne illness."},{"id":"s24-c-word-germ-theory-flash","kind":"flash","topic":"01","difficulty":"Foundation","prompt":"Explain germ theory and give an example.","answer":"The evidence-based idea that specific microorganisms can cause infectious diseases. Example: Compare an organism found in cases with evidence from controls."},{"id":"s24-c-word-risk-factor-flash","kind":"flash","topic":"01","difficulty":"Foundation","prompt":"Explain risk factor and give an example.","answer":"A condition or exposure associated with a changed chance of an outcome. Example: Improper food temperature can increase foodborne illness risk."},{"id":"s24-c-word-bacterium-flash","kind":"flash","topic":"02","difficulty":"Foundation","prompt":"Explain bacterium and give an example.","answer":"A single-celled organism; some species can cause disease. Example: A foodborne bacterium may multiply under suitable conditions."},{"id":"s24-c-word-virus-flash","kind":"flash","topic":"02","difficulty":"Foundation","prompt":"Explain virus and give an example.","answer":"An infectious agent that uses a host cell to make new virus particles. Example: A respiratory virus can spread between people."},{"id":"s24-c-word-protist-flash","kind":"flash","topic":"02","difficulty":"Foundation","prompt":"Explain protist and give an example.","answer":"A diverse eukaryotic group that includes some parasites. Example: Giardia can spread through contaminated water."},{"id":"s24-c-word-fungus-flash","kind":"flash","topic":"02","difficulty":"Foundation","prompt":"Explain fungus and give an example.","answer":"A group of organisms including yeasts and moulds; some cause infections. Example: A fungus can cause athlete's foot."},{"id":"s24-c-word-communicable-disease-flash","kind":"flash","topic":"03","difficulty":"Foundation","prompt":"Explain communicable disease and give an example.","answer":"A disease that can spread between hosts through a transmission route. Example: A respiratory infection may spread between people."},{"id":"s24-c-word-non-communicable-disease-flash","kind":"flash","topic":"03","difficulty":"Foundation","prompt":"Explain non-communicable disease and give an example.","answer":"A disease not spread from person to person by an infectious agent. Example: Some inherited disorders are non-communicable."},{"id":"s24-c-word-transmission-route-flash","kind":"flash","topic":"03","difficulty":"Foundation","prompt":"Explain transmission route and give an example.","answer":"The pathway an infectious agent takes between source and host. Example: Contaminated water can carry a pathogen into the digestive tract."},{"id":"s24-c-word-health-inequity-flash","kind":"flash","topic":"03","difficulty":"Foundation","prompt":"Explain health inequity and give an example.","answer":"An avoidable and unfair difference in health opportunities or outcomes linked to social conditions. Example: Unequal access to treated water can change exposure risk."},{"id":"s24-c-word-food-preservation-flash","kind":"flash","topic":"04","difficulty":"Foundation","prompt":"Explain food preservation and give an example.","answer":"Processing or storage used to slow spoilage or reduce food-safety hazards. Example: Refrigeration slows many microbial growth processes."},{"id":"s24-c-word-pasteurization-flash","kind":"flash","topic":"04","difficulty":"Foundation","prompt":"Explain pasteurization and give an example.","answer":"Controlled heating that reduces specified harmful microbes in a product. Example: Commercial milk is commonly pasteurized."},{"id":"s24-c-word-cross-contamination-flash","kind":"flash","topic":"04","difficulty":"Foundation","prompt":"Explain cross-contamination and give an example.","answer":"Transfer of harmful material from one food or surface to another. Example: An unwashed board transfers raw-meat microbes to salad."},{"id":"s24-c-word-refrigeration-flash","kind":"flash","topic":"04","difficulty":"Foundation","prompt":"Explain refrigeration and give an example.","answer":"Cold storage that slows many biological and chemical changes. Example: A chilled lunch stays colder than one left on a counter."},{"id":"s24-c-word-antiseptic-flash","kind":"flash","topic":"05","difficulty":"Foundation","prompt":"Explain antiseptic and give an example.","answer":"A product intended to reduce microorganisms on living tissue when used as directed. Example: Some first-aid products are labeled for skin."},{"id":"s24-c-word-disinfectant-flash","kind":"flash","topic":"05","difficulty":"Foundation","prompt":"Explain disinfectant and give an example.","answer":"A product or process used to reduce specified microorganisms on suitable non-living surfaces. Example: A labeled product may be used on a counter as directed."},{"id":"s24-c-word-sterilization-flash","kind":"flash","topic":"05","difficulty":"Foundation","prompt":"Explain sterilization and give an example.","answer":"A validated process intended to eliminate all viable microorganisms from an item. Example: Specialized equipment can sterilize suitable instruments."},{"id":"s24-c-word-aseptic-technique-flash","kind":"flash","topic":"05","difficulty":"Foundation","prompt":"Explain aseptic technique and give an example.","answer":"A set of practices that prevents contamination during a task. Example: Keeping prepared equipment away from unclean surfaces is aseptic practice."},{"id":"s24-c-word-outbreak-flash","kind":"flash","topic":"06","difficulty":"Foundation","prompt":"Explain outbreak and give an example.","answer":"More cases than expected in a defined place and time. Example: An unusual cluster at one school can trigger an investigation."},{"id":"s24-c-word-epidemic-flash","kind":"flash","topic":"06","difficulty":"Foundation","prompt":"Explain epidemic and give an example.","answer":"An increase above expected cases across a population or region. Example: A regional rise over several weeks may be an epidemic."},{"id":"s24-c-word-pandemic-flash","kind":"flash","topic":"06","difficulty":"Foundation","prompt":"Explain pandemic and give an example.","answer":"An epidemic that has spread across multiple countries or continents. Example: The 1918 influenza pandemic affected many regions."},{"id":"s24-c-word-historical-context-flash","kind":"flash","topic":"06","difficulty":"Foundation","prompt":"Explain historical context and give an example.","answer":"The time, place, social conditions and evidence needed to interpret a past event. Example: Compare 1918 reports with the care and reporting available then."},{"id":"s24-c-word-water-treatment-flash","kind":"flash","topic":"07","difficulty":"Foundation","prompt":"Explain water treatment and give an example.","answer":"Processes used to reduce hazards in drinking water before distribution. Example: Filtration and disinfection may be parts of a treatment system."},{"id":"s24-c-word-surveillance-flash","kind":"flash","topic":"07","difficulty":"Foundation","prompt":"Explain surveillance and give an example.","answer":"Systematic collection and interpretation of health or environmental information. Example: Regular water samples can reveal a changing pattern."},{"id":"s24-c-word-wastewater-flash","kind":"flash","topic":"07","difficulty":"Foundation","prompt":"Explain wastewater and give an example.","answer":"Used water containing human or other wastes that needs management. Example: A community treatment plant reduces release of harmful material."},{"id":"s24-c-word-public-advisory-flash","kind":"flash","topic":"07","difficulty":"Foundation","prompt":"Explain public advisory and give an example.","answer":"A time- and place-specific notice that recommends protective action. Example: A water or air notice may guide temporary behaviour."},{"id":"s24-c-word-risk-assessment-flash","kind":"flash","topic":"08","difficulty":"Foundation","prompt":"Explain risk assessment and give an example.","answer":"A structured comparison of hazards, exposure, likelihood and possible consequences. Example: A water operator assesses a positive sample and possible users exposed."},{"id":"s24-c-word-public-health-guideline-flash","kind":"flash","topic":"08","difficulty":"Foundation","prompt":"Explain public-health guideline and give an example.","answer":"A recommendation or rule intended to reduce a stated population health risk. Example: A sampling and notification protocol guides water-system action."},{"id":"s24-c-word-warning-sign-flash","kind":"flash","topic":"08","difficulty":"Foundation","prompt":"Explain warning sign and give an example.","answer":"An observation that calls for investigation or action. Example: An unexpected test result can be a warning sign."},{"id":"s24-c-word-escalation-flash","kind":"flash","topic":"08","difficulty":"Foundation","prompt":"Explain escalation and give an example.","answer":"Passing a concern to the person or authority able to act, following a defined process. Example: A confirmed test result triggers timely review and public notice when appropriate."},{"id":"s24-c-word-barrier-defence-flash","kind":"flash","topic":"09","difficulty":"Foundation","prompt":"Explain barrier defence and give an example.","answer":"A body surface or substance that reduces pathogen entry. Example: Intact skin blocks many external organisms."},{"id":"s24-c-word-cilia-flash","kind":"flash","topic":"09","difficulty":"Foundation","prompt":"Explain cilia and give an example.","answer":"Tiny moving projections that help move mucus and trapped particles along airways. Example: Airway cilia help clear inhaled material."},{"id":"s24-c-word-inflammation-flash","kind":"flash","topic":"09","difficulty":"Foundation","prompt":"Explain inflammation and give an example.","answer":"A local response to injury or infection involving signals, blood vessels and immune cells. Example: A sliver may lead to redness and swelling."},{"id":"s24-c-word-macrophage-flash","kind":"flash","topic":"09","difficulty":"Foundation","prompt":"Explain macrophage and give an example.","answer":"An immune cell that can engulf material and help coordinate responses. Example: A macrophage may engulf microbes in damaged tissue."},{"id":"s24-c-word-antigen-flash","kind":"flash","topic":"10","difficulty":"Foundation","prompt":"Explain antigen and give an example.","answer":"A feature that can be recognized by an immune response. Example: A protein on a microbe may act as an antigen."},{"id":"s24-c-word-antibody-flash","kind":"flash","topic":"10","difficulty":"Foundation","prompt":"Explain antibody and give an example.","answer":"A protein produced by B-cell descendants that binds a matching target. Example: An antibody may bind a matching viral surface feature."},{"id":"s24-c-word-active-immunity-flash","kind":"flash","topic":"10","difficulty":"Foundation","prompt":"Explain active immunity and give an example.","answer":"Protection developed through a person's own immune response after infection or vaccination. Example: Vaccination can stimulate immune memory."},{"id":"s24-c-word-passive-immunity-flash","kind":"flash","topic":"10","difficulty":"Foundation","prompt":"Explain passive immunity and give an example.","answer":"Temporary protection supplied by antibodies from another source. Example: Some maternal antibodies pass to an infant."},{"id":"s24-c-word-blood-group-antigen-flash","kind":"flash","topic":"11","difficulty":"Foundation","prompt":"Explain blood-group antigen and give an example.","answer":"A marker on red blood cells used in a compatibility model. Example: A-type red cells carry A antigen."},{"id":"s24-c-word-rhd-flash","kind":"flash","topic":"11","difficulty":"Foundation","prompt":"Explain RhD and give an example.","answer":"An antigen used in the positive/negative part of common red-cell typing. Example: O-negative red cells lack RhD antigen."},{"id":"s24-c-word-vaccine-flash","kind":"flash","topic":"11","difficulty":"Foundation","prompt":"Explain vaccine and give an example.","answer":"A preparation that stimulates an immune response to a specified target. Example: A vaccine may use a pathogen component or mRNA platform."},{"id":"s24-c-word-immune-memory-flash","kind":"flash","topic":"11","difficulty":"Foundation","prompt":"Explain immune memory and give an example.","answer":"A lasting capacity of some immune cells to respond to a previously encountered target. Example: A later exposure may trigger a faster response."},{"id":"s24-c-word-antibiotic-flash","kind":"flash","topic":"12","difficulty":"Foundation","prompt":"Explain antibiotic and give an example.","answer":"A medicine used to treat or prevent certain bacterial infections. Example: A clinician may prescribe one for a confirmed or likely bacterial infection."},{"id":"s24-c-word-antibiotic-resistance-flash","kind":"flash","topic":"12","difficulty":"Foundation","prompt":"Explain antibiotic resistance and give an example.","answer":"The ability of bacteria to survive an antibiotic that previously worked against them. Example: A resistant bacterial strain may spread under selection."},{"id":"s24-c-word-active-ingredient-flash","kind":"flash","topic":"12","difficulty":"Foundation","prompt":"Explain active ingredient and give an example.","answer":"The substance in a medicine responsible for its intended effect. Example: Two brands may contain the same active ingredient."},{"id":"s24-c-word-over-the-counter-medicine-flash","kind":"flash","topic":"12","difficulty":"Foundation","prompt":"Explain over-the-counter medicine and give an example.","answer":"A medicine available without an individual prescription, with directions and warnings. Example: A cold symptom product may be sold over the counter."},{"id":"s24-c-word-dna-flash","kind":"flash","topic":"13","difficulty":"Foundation","prompt":"Explain DNA and give an example.","answer":"A molecule that carries hereditary information in a sequence of bases. Example: A and T pair across a DNA double strand."},{"id":"s24-c-word-gene-flash","kind":"flash","topic":"13","difficulty":"Foundation","prompt":"Explain gene and give an example.","answer":"A DNA region whose information contributes to a functional product. Example: A gene may help specify a protein."},{"id":"s24-c-word-chromosome-flash","kind":"flash","topic":"13","difficulty":"Foundation","prompt":"Explain chromosome and give an example.","answer":"An organized DNA-containing structure visible in a karyotype during cell division. Example: Chromosome 21 appears in a pair in a typical body-cell set."},{"id":"s24-c-word-karyotype-flash","kind":"flash","topic":"13","difficulty":"Foundation","prompt":"Explain karyotype and give an example.","answer":"An arranged image of chromosomes used to inspect number and large structural patterns. Example: An extra chromosome 21 is visible in a karyotype."},{"id":"s24-c-word-allele-flash","kind":"flash","topic":"14","difficulty":"Foundation","prompt":"Explain allele and give an example.","answer":"A version of a gene used in an inheritance model. Example: T and t represent two versions for a plant-height model."},{"id":"s24-c-word-genotype-flash","kind":"flash","topic":"14","difficulty":"Foundation","prompt":"Explain genotype and give an example.","answer":"The allele combination assigned to an organism for the trait being modeled. Example: Tt is one plant genotype."},{"id":"s24-c-word-phenotype-flash","kind":"flash","topic":"14","difficulty":"Foundation","prompt":"Explain phenotype and give an example.","answer":"An observable trait or characteristic produced through genes and often environment. Example: A Tt plant may be tall in the model."},{"id":"s24-c-word-punnett-square-flash","kind":"flash","topic":"14","difficulty":"Foundation","prompt":"Explain Punnett square and give an example.","answer":"A grid for organizing possible allele combinations from two parents. Example: A Tt × tt grid has two Tt and two tt cells."},{"id":"s24-c-word-pedigree-flash","kind":"flash","topic":"15","difficulty":"Foundation","prompt":"Explain pedigree and give an example.","answer":"A diagram showing relationships and a trait's observed status across generations. Example: Workbook p. 31 shows Sue, Joe, Jim and Tim shaded."},{"id":"s24-c-word-generation-flash","kind":"flash","topic":"15","difficulty":"Foundation","prompt":"Explain generation and give an example.","answer":"People placed at the same level of descent in a pedigree. Example: The workbook diagram has three generation rows."},{"id":"s24-c-word-carrier-flash","kind":"flash","topic":"15","difficulty":"Foundation","prompt":"Explain carrier and give an example.","answer":"In a recessive model, a person who has one recessive allele but does not show the modeled condition. Example: An unshaded partner could be a carrier in a possible recessive explanation."},{"id":"s24-c-word-evidence-limit-flash","kind":"flash","topic":"15","difficulty":"Foundation","prompt":"Explain evidence limit and give an example.","answer":"A boundary on what the given observations can establish. Example: Missing genotypes prevent a unique dominance conclusion in Q12."},{"id":"s24-c-word-mutation-flash","kind":"flash","topic":"16","difficulty":"Foundation","prompt":"Explain mutation and give an example.","answer":"A change in DNA sequence or chromosome structure/number in a specified context. Example: A copying error can change one DNA base."},{"id":"s24-c-word-mutagen-flash","kind":"flash","topic":"16","difficulty":"Foundation","prompt":"Explain mutagen and give an example.","answer":"An agent or exposure that can increase the rate of DNA changes. Example: Some forms of radiation can damage DNA."},{"id":"s24-c-word-genetic-disorder-flash","kind":"flash","topic":"16","difficulty":"Foundation","prompt":"Explain genetic disorder and give an example.","answer":"A health condition related to particular genetic changes, often with varied expression. Example: Trisomy 21 is a chromosome-number condition."},{"id":"s24-c-word-inherited-variant-flash","kind":"flash","topic":"16","difficulty":"Foundation","prompt":"Explain inherited variant and give an example.","answer":"A genetic difference passed through a reproductive cell from a parent. Example: A child can inherit an allele present in a parent's egg or sperm."},{"id":"s24-c-word-genetic-research-flash","kind":"flash","topic":"17","difficulty":"Foundation","prompt":"Explain genetic research and give an example.","answer":"Systematic study of genes, variants and their relationships to function or health. Example: Researchers compare variant patterns and outcomes."},{"id":"s24-c-word-genetic-screening-flash","kind":"flash","topic":"17","difficulty":"Foundation","prompt":"Explain genetic screening and give an example.","answer":"Testing used to look for specified genetic patterns or risks. Example: A screen may identify a chromosome pattern needing interpretation."},{"id":"s24-c-word-informed-consent-flash","kind":"flash","topic":"17","difficulty":"Foundation","prompt":"Explain informed consent and give an example.","answer":"A person's voluntary decision after understanding purpose, risks and alternatives. Example: A participant agrees to a genetic study after reviewing its use of data."},{"id":"s24-c-word-genetic-privacy-flash","kind":"flash","topic":"17","difficulty":"Foundation","prompt":"Explain genetic privacy and give an example.","answer":"Control and protection of information about a person's genetic data. Example: A research project limits access to individual results."}]},"checks":{"s24-c-required-01":{"id":"s24-c-required-01","title":"Disease causes and germ theory · required check","route":"lesson-01","questions":[{"kind":"mc","prompt":"What would make a germ claim stronger than a guess?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Germ theory is tested with specific evidence, comparisons and alternative explanations.","id":"s24-c-l01-required1","topic":"01","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l01-required1-o0","text":"Consistent evidence linking a specified organism, exposure and cases while checking alternatives."},{"id":"s24-c-l01-required1-o1","text":"A single vivid story without comparisons."},{"id":"s24-c-l01-required1-o2","text":"The fact that all microbes are harmful."},{"id":"s24-c-l01-required1-o3","text":"A label that calls any warm food contaminated."}],"answer":"s24-c-l01-required1-o0"},{"kind":"mc","prompt":"Which statement best separates cause and contributing condition in a food-illness case?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The agent and the conditions that affect exposure or growth play different roles.","id":"s24-c-l01-required2","topic":"01","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l01-required2-o0","text":"A pathogen may cause infection; warm storage may increase its amount if it is present."},{"id":"s24-c-l01-required2-o1","text":"Warm storage is the pathogen and the bacterium is the temperature."},{"id":"s24-c-l01-required2-o2","text":"If a food looks normal no pathogen can be present."},{"id":"s24-c-l01-required2-o3","text":"A risk factor proves a particular person's diagnosis."}],"answer":"s24-c-l01-required2-o0"}],"writing":[{"id":"s24-c-l01-write1","prompt":"A school cafeteria finds three people ill after one meal. Write a causal claim, two pieces of evidence that would support it, and one competing explanation to check. Explain your evidence or steps."},{"id":"s24-c-l01-write2","prompt":"Without opening the lesson, explain why a warm hamburger can become risky while warmth alone is not a pathogen. Explain a relevant limit or condition."}]},"s24-c-required-02":{"id":"s24-c-required-02","title":"Compare bacteria, viruses and other pathogens · required check","route":"lesson-02","questions":[{"kind":"mc","prompt":"Which comparison of bacteria and viruses is accurate?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The distinction concerns cellular organization and reproduction, not merely whether illness occurs.","id":"s24-c-l02-required1","topic":"02","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l02-required1-o0","text":"Bacteria are cells; viruses require host-cell machinery to replicate."},{"id":"s24-c-l02-required1-o1","text":"Viruses are cells that divide by binary fission in food."},{"id":"s24-c-l02-required1-o2","text":"Bacteria have no cellular structure."},{"id":"s24-c-l02-required1-o3","text":"Both are identical in size, reproduction and treatment."}],"answer":"s24-c-l02-required1-o0"},{"kind":"mc","prompt":"A water sample may contain a protist. Which conclusion follows?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Category, pathogenicity and actual exposure are separate pieces of evidence.","id":"s24-c-l02-required2","topic":"02","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l02-required2-o0","text":"A particular disease claim needs identification and exposure evidence, since not all protists are pathogens."},{"id":"s24-c-l02-required2-o1","text":"Every protist in water causes beaver fever."},{"id":"s24-c-l02-required2-o2","text":"Only beavers can carry a waterborne pathogen."},{"id":"s24-c-l02-required2-o3","text":"The sample proves every hiker is infected."}],"answer":"s24-c-l02-required2-o0"}],"writing":[{"id":"s24-c-l02-write1","prompt":"A student sees a skin rash and says “it must be bacteria.” Explain why that conclusion is premature and what evidence would help distinguish causes. Explain your evidence or steps."},{"id":"s24-c-l02-write2","prompt":"From memory, compare where a bacterium and a virus make more of themselves, then name one infection route for a protist. Explain a relevant limit or condition."}]},"s24-c-required-03":{"id":"s24-c-required-03","title":"Communicable disease and unequal risk · required check","route":"lesson-03","questions":[{"kind":"mc","prompt":"Which statement uses a historical life-expectancy chart responsibly?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Historical data support claims about their time and method, not an eternal ranking.","id":"s24-c-l03-required1","topic":"03","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l03-required1-o0","text":"It reports the chart's period and measure, then seeks newer data for a current claim."},{"id":"s24-c-l03-required1-o1","text":"It applies the old ranking to all people today."},{"id":"s24-c-l03-required1-o2","text":"It treats income as a pathogen."},{"id":"s24-c-l03-required1-o3","text":"It ignores differences in data collection."}],"answer":"s24-c-l03-required1-o0"},{"kind":"mc","prompt":"A class compares disease risk between communities. What is the strongest explanation?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A mechanistic, contextual explanation avoids both biological and statistical overreach.","id":"s24-c-l03-required2","topic":"03","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l03-required2-o0","text":"Name the agent and route, then examine exposure, infrastructure and access separately."},{"id":"s24-c-l03-required2-o1","text":"Assign the difference to one group's worth."},{"id":"s24-c-l03-required2-o2","text":"Treat risk factors as proof of each person's diagnosis."},{"id":"s24-c-l03-required2-o3","text":"Ignore the denominator and time period."}],"answer":"s24-c-l03-required2-o0"}],"writing":[{"id":"s24-c-l03-write1","prompt":"Compare two communities with different water access. Identify the pathogen route, two conditions that may change exposure, and one action that does not blame residents. Explain your evidence or steps."},{"id":"s24-c-l03-write2","prompt":"From memory, name one communicable and one non-communicable condition, and say why a risk factor is not a pathogen. Explain a relevant limit or condition."}]},"s24-c-required-04":{"id":"s24-c-required-04","title":"Food safety and preservation · required check","route":"lesson-04","questions":[{"kind":"mc","prompt":"Why do clean preparation surfaces and cold storage both matter?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Layered controls address different mechanisms and limitations.","id":"s24-c-l04-required1","topic":"04","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l04-required1-o0","text":"They interrupt different points: transfer of microbes and later growth conditions."},{"id":"s24-c-l04-required1-o1","text":"They are the same chemical procedure."},{"id":"s24-c-l04-required1-o2","text":"Either one guarantees all hazards disappear."},{"id":"s24-c-l04-required1-o3","text":"Only storage matters after raw food touches salad."}],"answer":"s24-c-l04-required1-o0"},{"kind":"mc","prompt":"A learner writes 'every preservation method kills germs.' What is a stronger summary?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Mechanism-based explanations are needed for the workbook's ten named methods.","id":"s24-c-l04-required2","topic":"04","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l04-required2-o0","text":"Methods such as drying, chilling and heat processing act through different mechanisms and have different limits."},{"id":"s24-c-l04-required2-o1","text":"All ten workbook methods are identical."},{"id":"s24-c-l04-required2-o2","text":"No method changes risk."},{"id":"s24-c-l04-required2-o3","text":"A method's name proves all foods are sterile."}],"answer":"s24-c-l04-required2-o0"}],"writing":[{"id":"s24-c-l04-write1","prompt":"Design a safe sequence for preparing raw chicken and a salad. Explain one contamination control and one time/temperature control, including the limit of each. Explain your evidence or steps."},{"id":"s24-c-l04-write2","prompt":"From memory, compare what refrigeration, drying and pasteurization change. Which one can be assumed to sterilize food? Explain a relevant limit or condition."}]},"s24-c-required-05":{"id":"s24-c-required-05","title":"Sanitation, sterilization and aseptic practice · required check","route":"lesson-05","questions":[{"kind":"mc","prompt":"Which pair correctly matches method and target?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Terms identify intended use and process, not interchangeable levels of strength.","id":"s24-c-l05-required1","topic":"05","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l05-required1-o0","text":"Antiseptic—living tissue; disinfectant—suitable non-living surface."},{"id":"s24-c-l05-required1-o1","text":"Disinfectant—any open wound; antiseptic—every floor."},{"id":"s24-c-l05-required1-o2","text":"Sterilization—ordinary refrigeration; asepsis—a chemical bottle."},{"id":"s24-c-l05-required1-o3","text":"Antibiotic—sterilize a workbench; vaccine—clean a cut."}],"answer":"s24-c-l05-required1-o0"},{"kind":"mc","prompt":"A student lists four aseptic steps. What makes the explanation complete?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The source task calls for practices tied to mechanisms, with practical work under supervision.","id":"s24-c-l05-required2","topic":"05","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l05-required2-o0","text":"Each step names the contamination route it prevents and stays within trained procedures."},{"id":"s24-c-l05-required2-o1","text":"The four steps are interchangeable because they interrupt the same route."},{"id":"s24-c-l05-required2-o2","text":"The list assumes gloves make every surface sterile."},{"id":"s24-c-l05-required2-o3","text":"The steps invite an unsupervised procedure at home."}],"answer":"s24-c-l05-required2-o0"}],"writing":[{"id":"s24-c-l05-write1","prompt":"A classroom investigation uses cleaned tools and a prepared surface. Identify two points where contamination could still enter and explain controls; keep any practical steps teacher-supervised. Explain your evidence or steps."},{"id":"s24-c-l05-write2","prompt":"From memory, choose the term for living tissue, hard surfaces, complete validated elimination and prevention during a procedure. Explain a relevant limit or condition."}]},"s24-c-required-06":{"id":"s24-c-required-06","title":"Outbreaks, epidemics and historical impact · required check","route":"lesson-06","questions":[{"kind":"mc","prompt":"A disease is severe locally but has no documented international spread. Which label is best supported?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Scale of spread is separate from case severity.","id":"s24-c-l06-required1","topic":"06","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l06-required1-o0","text":"A local outbreak or regional epidemic may fit; pandemic is not established."},{"id":"s24-c-l06-required1-o1","text":"Pandemic must fit because severity is high."},{"id":"s24-c-l06-required1-o2","text":"No public-health term can be used until all cases recover."}],"answer":"s24-c-l06-required1-o0"},{"kind":"mc","prompt":"Which comparison of two epidemics is methodologically strongest?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Comparable definitions and measures are needed for a fair historical analysis.","id":"s24-c-l06-required2","topic":"06","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l06-required2-o0","text":"Compare periods, case definitions, populations and rates before drawing conclusions."},{"id":"s24-c-l06-required2-o1","text":"Rank raw counts from different centuries without denominators."},{"id":"s24-c-l06-required2-o2","text":"Treat every historical report as complete and identical."}],"answer":"s24-c-l06-required2-o0"}],"writing":[{"id":"s24-c-l06-write1","prompt":"A news post calls one city's disease cluster a pandemic. Write what evidence would support a local outbreak description and what additional evidence would be needed for pandemic language. Explain your evidence or steps."},{"id":"s24-c-l06-write2","prompt":"From memory, explain why case count alone cannot distinguish outbreak, epidemic and pandemic, and name two context fields for a historical comparison. Explain a relevant limit or condition."}]},"s24-c-required-07":{"id":"s24-c-required-07","title":"Public systems for water, waste and air · required check","route":"lesson-07","questions":[{"kind":"mc","prompt":"Which sequence best explains a community drinking-water response?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Detection, correction and communication are distinct necessary steps.","id":"s24-c-l07-required1","topic":"07","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l07-required1-o0","text":"Sample and interpret → address treatment/distribution issue → communicate precautions when needed."},{"id":"s24-c-l07-required1-o1","text":"Judge by appearance → ignore tests → wait for illness."},{"id":"s24-c-l07-required1-o2","text":"Publish an alert without locating or investigating the concern."}],"answer":"s24-c-l07-required1-o0"},{"kind":"mc","prompt":"An air notice recommends reduced strenuous activity for a defined group. What does the notice establish?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A public advisory guides exposure decisions using current monitoring evidence.","id":"s24-c-l07-required2","topic":"07","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l07-required2-o0","text":"Current monitoring supports a time-and-place-specific risk recommendation, not an individual diagnosis."},{"id":"s24-c-l07-required2-o1","text":"Every resident is already ill."},{"id":"s24-c-l07-required2-o2","text":"The old textbook's agency name and scale are necessarily current."}],"answer":"s24-c-l07-required2-o0"}],"writing":[{"id":"s24-c-l07-write1","prompt":"A community receives both a drinking-water warning and an air-quality notice. For each, name the pathway, one measurement or observation, one system-level action and one limit of the evidence. Explain your evidence or steps."},{"id":"s24-c-l07-write2","prompt":"Without looking, write the sequence source → monitoring → control → communication for a drinking-water example. Explain a relevant limit or condition."}]},"s24-c-required-08":{"id":"s24-c-required-08","title":"Guidelines, risk decisions and the Walkerton case · required check","route":"lesson-08","questions":[{"kind":"mc","prompt":"Why may public-health guidelines matter?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Guidelines help a system act consistently when their mechanisms and limits are clear.","id":"s24-c-l08-required1","topic":"08","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l08-required1-o0","text":"They connect evidence to consistent actions at known risk points and can be revised as evidence changes."},{"id":"s24-c-l08-required1-o1","text":"They make monitoring unnecessary forever."},{"id":"s24-c-l08-required1-o2","text":"They remove the need to communicate with people."}],"answer":"s24-c-l08-required1-o0"},{"kind":"mc","prompt":"A table names travel as a risk factor. Which explanation is strongest?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A risk factor describes a pathway or condition, not a trait that makes people dangerous.","id":"s24-c-l08-required2","topic":"08","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l08-required2-o0","text":"Travel can alter where exposure or detection occurs; surveillance and timely information address that route."},{"id":"s24-c-l08-required2-o1","text":"Travellers are pathogens."},{"id":"s24-c-l08-required2-o2","text":"All travel causes infection."}],"answer":"s24-c-l08-required2-o0"}],"writing":[{"id":"s24-c-l08-write1","prompt":"Using the original Walkerton workbook task or a teacher-provided timeline, choose one warning sign, one missed or effective control, and one recommendation. Mark any claim that requires evidence beyond the timeline. Explain your evidence or steps."},{"id":"s24-c-l08-write2","prompt":"From memory, explain how to turn a risk factor into a justified public-health response without blaming a group. Explain a relevant limit or condition."}]},"s24-c-required-09":{"id":"s24-c-required-09","title":"Physical barriers and inflammation · required check","route":"lesson-09","questions":[{"kind":"mc","prompt":"Which ordering fits a breached skin barrier?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A breach creates the opportunity; the local response follows injury or entry.","id":"s24-c-l09-required1","topic":"09","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l09-required1-o0","text":"Entry opportunity → tissue signals and inflammation → immune cells help clear material."},{"id":"s24-c-l09-required1-o1","text":"Antibody first → skin forms a sliver → no tissue response."},{"id":"s24-c-l09-required1-o2","text":"All pathogens disappear before a barrier is breached."}],"answer":"s24-c-l09-required1-o0"},{"kind":"mc","prompt":"The workbook barrier chart asks for structures and functions. What is a complete answer?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The source task is about distinct physical or chemical mechanisms at entry points.","id":"s24-c-l09-required2","topic":"09","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l09-required2-o0","text":"Match each named structure to how it blocks, traps or clears material and note its limits."},{"id":"s24-c-l09-required2-o1","text":"Write 'immune system' in every blank."},{"id":"s24-c-l09-required2-o2","text":"Assume every barrier is an antibody."}],"answer":"s24-c-l09-required2-o0"}],"writing":[{"id":"s24-c-l09-write1","prompt":"A person has irritated airways after smoke exposure. Explain one barrier mechanism that may be impaired, one possible inflammatory response, and one reason not to diagnose an infection from coughing alone. Explain your evidence or steps."},{"id":"s24-c-l09-write2","prompt":"From memory, trace a pathogen's path past one barrier and into an inflammatory response; name the role of a macrophage. Explain a relevant limit or condition."}]},"s24-c-required-10":{"id":"s24-c-required-10","title":"Antigens, antibodies and immune response · required check","route":"lesson-10","questions":[{"kind":"mc","prompt":"Which branch belongs under acquired immunity in the workbook flowchart?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Adaptive/acquired protection can arise through the person's response or supplied antibodies.","id":"s24-c-l10-required1","topic":"10","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l10-required1-o0","text":"Active response by the person and passive receipt of antibodies."},{"id":"s24-c-l10-required1-o1","text":"Only intact skin and cilia."},{"id":"s24-c-l10-required1-o2","text":"Only public sanitation, with no targeted response within the body."}],"answer":"s24-c-l10-required1-o0"},{"kind":"mc","prompt":"What makes the five-step diagram a useful but limited model?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A model simplifies complex interacting processes and needs its scope stated.","id":"s24-c-l10-required2","topic":"10","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l10-required2-o0","text":"It identifies roles and an approximate sequence, while actual immune events overlap and vary."},{"id":"s24-c-l10-required2-o1","text":"Every antigen follows one exact clock sequence."},{"id":"s24-c-l10-required2-o2","text":"Its numbered arrows prove all infections have the same outcome."}],"answer":"s24-c-l10-required2-o0"}],"writing":[{"id":"s24-c-l10-write1","prompt":"Compare a vaccinated person and a newborn receiving maternal antibodies. For each, identify where protective antibodies or memory arise and one limit of the comparison. Explain your evidence or steps."},{"id":"s24-c-l10-write2","prompt":"From memory, distinguish antigen, antibody, active immunity and passive immunity in four linked sentences. Explain a relevant limit or condition."}]},"s24-c-required-11":{"id":"s24-c-required-11","title":"Blood compatibility, vaccines and immunity · required check","route":"lesson-11","questions":[{"kind":"mc","prompt":"Which claim about blood products is carefully qualified?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Compatibility is component-specific and clinically assessed.","id":"s24-c-l11-required1","topic":"11","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l11-required1-o0","text":"O-negative red cells often have a broad emergency role, while plasma and patient testing follow their own rules."},{"id":"s24-c-l11-required1-o1","text":"O-negative plasma and red cells are universally interchangeable."},{"id":"s24-c-l11-required1-o2","text":"ABO typing alone predicts every transfusion reaction."}],"answer":"s24-c-l11-required1-o0"},{"kind":"mc","prompt":"A student says vaccination guarantees lifelong protection from every infection. What is the correction?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Vaccination can build protection without making every outcome absolute.","id":"s24-c-l11-required2","topic":"11","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l11-required2-o0","text":"Protection depends on the target, vaccine, schedule, response and time; no universal guarantee follows."},{"id":"s24-c-l11-required2-o1","text":"Vaccines never stimulate memory."},{"id":"s24-c-l11-required2-o2","text":"Only antibiotics can prevent infection."}],"answer":"s24-c-l11-required2-o0"}],"writing":[{"id":"s24-c-l11-write1","prompt":"A poster claims 'O-negative means no compatibility checks' and 'all vaccines contain dead germs.' Correct both claims and name the context each missing detail changes. Explain your evidence or steps."},{"id":"s24-c-l11-write2","prompt":"Without looking, explain how a red-cell antigen mismatch differs from a vaccine target and why both require careful wording. Explain a relevant limit or condition."}]},"s24-c-required-12":{"id":"s24-c-required-12","title":"Medicines, antibiotics and safe choices · required check","route":"lesson-12","questions":[{"kind":"mc","prompt":"Which statement distinguishes antibiotic, antiviral and symptom-relief purposes?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Match a product to its mechanism and purpose, not just the word 'medicine'.","id":"s24-c-l12-required1","topic":"12","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l12-required1-o0","text":"They target different problems; a symptom product may ease discomfort without removing the virus."},{"id":"s24-c-l12-required1-o1","text":"All three are identical cures for every infection."},{"id":"s24-c-l12-required1-o2","text":"An antibiotic is a vaccine for viral colds."}],"answer":"s24-c-l12-required1-o0"},{"kind":"mc","prompt":"What should a learner do when label warnings or interactions are unclear?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Classroom label literacy cannot replace personal medical guidance.","id":"s24-c-l12-required2","topic":"12","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l12-required2-o0","text":"Read the active ingredients and directions and ask a pharmacist or clinician for individual advice."},{"id":"s24-c-l12-required2-o1","text":"Guess a dose from a class example."},{"id":"s24-c-l12-required2-o2","text":"Ignore the warning if the product is sold without a prescription."}],"answer":"s24-c-l12-required2-o0"}],"writing":[{"id":"s24-c-l12-write1","prompt":"A friend wants an antibiotic for a cold and two symptom products with the same active ingredient. Explain the two different concerns and the evidence-based next step. Explain your evidence or steps."},{"id":"s24-c-l12-write2","prompt":"From memory, complete this correction: bacteria can become ___; people do not become ___ to antibiotics. Why does a viral cold not need an antibiotic for its virus? Explain a relevant limit or condition."}]},"s24-c-required-13":{"id":"s24-c-required-13","title":"DNA, chromosomes and inheritance · required check","route":"lesson-13","questions":[{"kind":"mc","prompt":"Which evidence would support calling a pattern XXY in a source karyotype?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The label follows the observed chromosome set, not a personal diagnosis or unrelated symptom.","id":"s24-c-l13-required1","topic":"13","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l13-required1-o0","text":"Two X chromosomes and one Y chromosome visibly grouped as sex chromosomes."},{"id":"s24-c-l13-required1-o1","text":"Three copies of chromosome 21."},{"id":"s24-c-l13-required1-o2","text":"A person reporting a cough."}],"answer":"s24-c-l13-required1-o0"},{"kind":"mc","prompt":"A page says 'normal human has 46 chromosomes.' How should the course frame it?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Typical count is a useful reference, not a universal claim about all cells or people.","id":"s24-c-l13-required2","topic":"13","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l13-required2-o0","text":"Most body cells typically have 46; variations exist and require careful interpretation."},{"id":"s24-c-l13-required2-o1","text":"Every cell in every human always has 46."},{"id":"s24-c-l13-required2-o2","text":"Chromosome count alone describes a person's worth."}],"answer":"s24-c-l13-required2-o0"}],"writing":[{"id":"s24-c-l13-write1","prompt":"A student says a karyotype can reveal every gene and tell exactly what a person will be like. Correct the claim with one thing it can show and two things it cannot establish. Explain your evidence or steps."},{"id":"s24-c-l13-write2","prompt":"From memory, arrange DNA, gene and chromosome by relationship and solve the complement of A-C-T. Explain a relevant limit or condition."}]},"s24-c-required-14":{"id":"s24-c-required-14","title":"Genotypes and Punnett squares · required check","route":"lesson-14","questions":[{"kind":"mc","prompt":"A Tt plant is crossed with tt. Which prediction is correct?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Tt contributes T or t and tt contributes t, producing a 1:1 split.","id":"s24-c-l14-required1","topic":"14","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l14-required1-o0","text":"Half Tt tall and half tt short under the model."},{"id":"s24-c-l14-required1-o1","text":"All TT tall."},{"id":"s24-c-l14-required1-o2","text":"All tt short."}],"answer":"s24-c-l14-required1-o0"},{"kind":"mc","prompt":"Two white Ww sheep have two white lambs. Does this disprove a 3:1 prediction?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Probabilities describe independent chances, not exact short sequences.","id":"s24-c-l14-required2","topic":"14","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l14-required2-o0","text":"No; a small family may differ from the long-run probability."},{"id":"s24-c-l14-required2-o1","text":"Yes; the square guarantees one black in every four births."},{"id":"s24-c-l14-required2-o2","text":"Yes; all offspring must be WW."}],"answer":"s24-c-l14-required2-o0"}],"writing":[{"id":"s24-c-l14-write1","prompt":"Two white heterozygous sheep have only two lambs, both white. Explain why that observation does not disprove the Ww × Ww square, then give its predicted genotype and phenotype ratios. Explain your evidence or steps."},{"id":"s24-c-l14-write2","prompt":"From memory, write the four combinations from Tt × tt and state why a human eye-colour cross needs a limitation note. Explain a relevant limit or condition."}]},"s24-c-required-16":{"id":"s24-c-required-16","title":"Mutations, mutagens and genetic disorders · required check","route":"lesson-16","questions":[{"kind":"mc","prompt":"A DNA change lies outside a protein-coding sequence. Which conclusion is justified?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Regulatory regions and other contexts can matter, and evidence is needed.","id":"s24-c-l16-required1","topic":"16","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l16-required1-o0","text":"Its effect still depends on location and function; it cannot be assumed harmful or harmless from that fact alone."},{"id":"s24-c-l16-required1-o1","text":"Every non-coding change is harmless."},{"id":"s24-c-l16-required1-o2","text":"Every non-coding change is lethal."}],"answer":"s24-c-l16-required1-o0"},{"kind":"mc","prompt":"Which chain is most careful when explaining a possible genetic disorder?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A causal explanation needs more than the word mutation.","id":"s24-c-l16-required2","topic":"16","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l16-required2-o0","text":"Describe the change, cell lineage and functional effect, then the evidence linking it to the condition."},{"id":"s24-c-l16-required2-o1","text":"Name one exposure and guarantee a named disorder."},{"id":"s24-c-l16-required2-o2","text":"Assume all inherited variants cause illness."}],"answer":"s24-c-l16-required2-o0"}],"writing":[{"id":"s24-c-l16-write1","prompt":"A friend says every mutation is inherited and every inherited change is harmful. Correct both parts with a body-cell/germ-cell distinction and one possible effect of a variant. Explain your evidence or steps."},{"id":"s24-c-l16-write2","prompt":"From memory, explain why a mutagen increases risk without guaranteeing a named disorder, and why cell type matters for inheritance. Explain a relevant limit or condition."}]},"s24-c-required-17":{"id":"s24-c-required-17","title":"Genetic research and ethical decisions · required check","route":"lesson-17","questions":[{"kind":"mc","prompt":"What can a genetic screen establish most directly?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A screen measures defined genetic information; interpretation may require more evidence.","id":"s24-c-l17-required1","topic":"17","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l17-required1-o0","text":"The specified pattern it measured, interpreted within its accuracy and context."},{"id":"s24-c-l17-required1-o1","text":"Every future symptom and life choice."},{"id":"s24-c-l17-required1-o2","text":"A person's worth or full identity."}],"answer":"s24-c-l17-required1-o0"},{"kind":"mc","prompt":"Which four-part question set best evaluates a new genetic technology?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Scientific value and ethical acceptability require several linked kinds of evidence.","id":"s24-c-l17-required2","topic":"17","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l17-required2-o0","text":"Benefit evidence, harms/uncertainty, consent/privacy, and fair access or alternatives."},{"id":"s24-c-l17-required2-o1","text":"Only speed, marketing, colour and novelty."},{"id":"s24-c-l17-required2-o2","text":"Only whether the technology is possible."}],"answer":"s24-c-l17-required2-o0"}],"writing":[{"id":"s24-c-l17-write1","prompt":"Choose one workbook genetic-research advance. State a plausible benefit, a limitation, whose consent is needed, one fairness question and a less harmful alternative where relevant. Explain your evidence or steps."},{"id":"s24-c-l17-write2","prompt":"From memory, give four questions you would ask before accepting a claim that a genetic technology will improve health. Explain a relevant limit or condition."}]},"s24-c-required-15-v2":{"id":"s24-c-required-15-v2","title":"Read and construct pedigrees · required check","route":"lesson-15","questions":[{"kind":"mc","prompt":"The original wording calls shaded people 'infected' and then asks for inherited pattern. What should online instruction do?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The source is visible, while the authored science distinguishes infection from inherited traits.","id":"s24-c-l15-required1","topic":"15","difficulty":"Application","role":"required1","options":[{"id":"s24-c-l15-required1-o0","text":"Preserve the source wording but explain shading as an affected trait status for this genetics model."},{"id":"s24-c-l15-required1-o1","text":"Teach ordinary infection as a simple allele automatically inherited by children."},{"id":"s24-c-l15-required1-o2","text":"Delete the diagram so the inconsistency cannot be seen."}],"answer":"s24-c-l15-required1-o0"},{"kind":"mc","prompt":"What must a constructed pedigree include to make its symbols interpretable?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A keyed diagram shows observations and relationships; the workbook's eye-colour rule remains a limited model.","id":"s24-c-l15-required2","topic":"15","difficulty":"Application","role":"required2","options":[{"id":"s24-c-l15-required2-o0","text":"A key for symbols and shading, generation structure and the stated relationships."},{"id":"s24-c-l15-required2-o1","text":"Names alone, without symbols or relationship lines, are enough to show inheritance."},{"id":"s24-c-l15-required2-o2","text":"A claim that eye colour is always one-gene in real people."}],"answer":"s24-c-l15-required2-o0"}],"writing":[{"id":"s24-c-l15-write1","prompt":"Construct the workbook Q13 family with a symbol key, but label its brown/blue eye rule as a simplified model. Then write one fact the diagram shows and one genotype it cannot prove without extra information. Explain your evidence or steps."},{"id":"s24-c-l15-write2-v2","prompt":"Compare the two source figures: state one fact shown by Q11 on p. 31, then identify the specific parent-child pattern in Q12 on p. 32 that supports a recessive interpretation in the intended simple model."}]},"s24-c-final-v2":{"id":"s24-c-final-v2","title":"Unit C integrated review · required final check","route":"lesson-18","questions":[{"kind":"mc","prompt":"Several diners report illness after a shared meal. Which first claim is most defensible?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"An investigation separates exposure, organism and alternative explanations.","id":"s24-c-review-q1","topic":"18","difficulty":"Application","role":"review1","options":[{"id":"s24-c-review-q1-o0","text":"Compare meals, symptom timing and organism evidence before naming a foodborne cause."},{"id":"s24-c-review-q1-o1","text":"Warm air alone proves a specific pathogen caused every case."},{"id":"s24-c-review-q1-o2","text":"One diner who stayed well proves the meal was safe."},{"id":"s24-c-review-q1-o3","text":"Every microorganism in the meal must be harmful."}],"answer":"s24-c-review-q1-o0"},{"kind":"mc","prompt":"A cooked food is placed on a board used for raw meat. What failure and control should be identified?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Cooking one item does not prevent later transfer from a contaminated surface.","id":"s24-c-review-q2","topic":"18","difficulty":"Application","role":"review2","options":[{"id":"s24-c-review-q2-o0","text":"Cross-contamination can transfer microorganisms; separate and clean food-contact surfaces."},{"id":"s24-c-review-q2-o1","text":"The cooked food is protected because cooking made the board sterile."},{"id":"s24-c-review-q2-o2","text":"Refrigeration will undo any contamination already transferred."},{"id":"s24-c-review-q2-o3","text":"A clean-looking board proves no microorganism remains."}],"answer":"s24-c-review-q2-o0"},{"kind":"mc","prompt":"A disease appears in several countries after local outbreaks. Which description avoids treating a label as a cause?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Outbreak scale describes distribution; it does not explain mechanism.","id":"s24-c-review-q3","topic":"18","difficulty":"Application","role":"review3","options":[{"id":"s24-c-review-q3-o0","text":"Describe the extent and time pattern as pandemic spread, then investigate the pathogen and route separately."},{"id":"s24-c-review-q3-o1","text":"The word pandemic identifies the exact organism."},{"id":"s24-c-review-q3-o2","text":"International spread proves every exposed person is ill."},{"id":"s24-c-review-q3-o3","text":"An epidemic can only occur in one household."}],"answer":"s24-c-review-q3-o0"},{"kind":"mc","prompt":"A community water alert follows missed test results. Which response addresses the system?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The Walkerton case illustrates why multiple controls and reliable reporting matter.","id":"s24-c-review-q4","topic":"18","difficulty":"Application","role":"review4","options":[{"id":"s24-c-review-q4-o0","text":"Follow current public advice while investigators check treatment, sampling, reporting and corrective action."},{"id":"s24-c-review-q4-o1","text":"Assume clear-looking water is safe without testing."},{"id":"s24-c-review-q4-o2","text":"Treat one household's boiling as proof the treatment plant worked."},{"id":"s24-c-review-q4-o3","text":"Ignore monitoring because filtration is always sufficient."}],"answer":"s24-c-review-q4-o0"},{"kind":"mc","prompt":"A student has a red, warm cut and later makes a targeted antibody response. Which comparison is accurate?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Innate inflammation and adaptive specificity play different roles.","id":"s24-c-review-q5","topic":"18","difficulty":"Application","role":"review5","options":[{"id":"s24-c-review-q5-o0","text":"Inflammation is a broad response; antibodies recognize particular targets."},{"id":"s24-c-review-q5-o1","text":"Inflammation proves a specific antibody already exists."},{"id":"s24-c-review-q5-o2","text":"Antibodies are the skin barrier before entry."},{"id":"s24-c-review-q5-o3","text":"Both responses require antibiotics to begin."}],"answer":"s24-c-review-q5-o0"},{"kind":"mc","prompt":"A viral illness spreads while someone takes an antibiotic for a separate bacterial infection. What should the course explanation say?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Cause and treatment mechanism must be matched; do not infer a personal prescription.","id":"s24-c-review-q6","topic":"18","difficulty":"Application","role":"review6","options":[{"id":"s24-c-review-q6-o0","text":"An antibiotic targets bacteria and does not directly stop viral replication; treatment decisions need clinical guidance."},{"id":"s24-c-review-q6-o1","text":"The antibiotic automatically cures any virus in the body."},{"id":"s24-c-review-q6-o2","text":"The person becomes resistant rather than bacteria."},{"id":"s24-c-review-q6-o3","text":"All fever proves a bacterial cause."}],"answer":"s24-c-review-q6-o0"},{"kind":"mc","prompt":"A Tt × tt model has two Tt and two tt boxes. Which interpretation is justified?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Punnett boxes describe chances in a specified one-gene model, not guaranteed family counts.","id":"s24-c-review-q7","topic":"18","difficulty":"Application","role":"review7","options":[{"id":"s24-c-review-q7-o0","text":"Each offspring has a one-half model probability of each genotype under the stated assumptions."},{"id":"s24-c-review-q7-o1","text":"The next four offspring must include exactly two of each genotype."},{"id":"s24-c-review-q7-o2","text":"The model proves a real human eye colour outcome."},{"id":"s24-c-review-q7-o3","text":"The t allele disappears whenever T is present."}],"answer":"s24-c-review-q7-o0"},{"kind":"mc","prompt":"The separate Q12 pedigree on workbook p. 32 shows two unaffected parents with an affected child. What is the best interpretation in the intended simple model?","hint":"Test whether a fully penetrant dominant trait could appear in a child when neither parent displays it.","explanation":"A recessive model fits because two unaffected carriers can have an affected child. This conclusion belongs to Q12’s own figure, not the named-family Q11 figure on p. 31.","id":"s24-c-v4-review-q8","topic":"18","difficulty":"Application","role":"review8","options":[{"id":"s24-c-v4-review-q8-o0","text":"The pattern supports recessive inheritance within the stated simple model."},{"id":"s24-c-v4-review-q8-o1","text":"The named people in Q11 prove the Q12 pattern is dominant."},{"id":"s24-c-v4-review-q8-o2","text":"The diagram proves every unshaded person has no recessive allele."},{"id":"s24-c-v4-review-q8-o3","text":"The shaded symbols identify an infectious pathogen."}],"answer":"s24-c-v4-review-q8-o0"}],"writing":[{"id":"s24-c-review-write1","prompt":"Trace a communicable disease pathway from exposure to response. Explain an individual action and a public-health action, with evidence and limits."},{"id":"s24-c-review-write2","prompt":"Explain how an inherited allele can affect a trait while environment and uncertainty still matter. Use one accurate inheritance model and identify its limits."}]}},"resources":[{"id":"s24-c-textbook","title":"Science 24 · Unit C: Disease Defence and Human Health","kind":"source-textbook","pdf":"assets/textbook.pdf","physicalPageCount":49,"sha256":"04418c17978f6192e36310817d04674af80991a408dd97404da985d0850e34ad","pages":[{"printed":154,"physical":1,"label":"154","image":"assets/reader-pages/textbook-page-01.jpg","text":"154\nUNITUNIT\nDisease\nDefence and\nHuman Health\nDisease\nDefence and\nHuman Health\nToday in Canada you can expect to live longer than your\ngreat-grandparents. This was not always the case. In the past,\nmany people died from widespread outbreaks of disease.\nWhat causes disease? How does disease spread? How does the\nbody protect itself from disease? How do the characteristics\nyou inherit from your parents affect your health? How does\nthe environment influence health?\nFor centuries, scientists have searched for\nanswers to all of these questions. They discovered\nthat disease-causing agents spread disease. In this\nunit you will learn about disease-carrying agents\nsuch as Giardia, which is present in water.\nToday, antibiotics treat many diseases\nsuccessfully. Research about how characteristics\nare passed from parent to child helps us better\nunderstand inherited diseases.\nIn this unit you will learn about all of these\nthings, and about how public health helps to keep\nus all healthier than our great-grandparents.\nKnowledge about these topics can benefit your\nlife in many ways. \nCC\n154\nSC2-09*UC/Q  6/9/04  11:05 AM  Page 154","originalImage":"assets/textbook-page-01.jpg"},{"printed":156,"physical":2,"label":"156","image":"assets/reader-pages/textbook-page-02.jpg","text":"Your head is throbbing. Your\nthroat is so raw that it hurts to talk.\nYou start to cough.\nBefore you cough again, consider\nyour actions. The germs that cause\ncolds are so small that you need a\nmicroscope to see them. But every\ntime you cough without covering\nyour mouth, you are sharing germs\nwith others nearby.\nDisease-causing agents such as\ncold viruses are all around you. In\nthis chapter, you will investigate the\nconditions that allow these agents to\ngrow and spread. You will learn\nabout other causes of disease and\nabout the differences between \ndiseases spread by germs and those\nthat are not caused or spread in this\nway. You will also find out how\nlifestyle, diet, and environmental\nfactors such as lack of cleanliness play\na role in disease. As you investigate\nways to prevent the contamination of\nfood, you will also learn about\ntechniques used to destroy bacteria\nthat contaminate food.\nAs you understand more about\ndisease, you will see why you need to\nprotect yourself from disease — and\nhow to do it. In addition, you will\nunderstand how important your\npersonal actions are the next time\nyou start to sneeze!\n156 MHR • Disease Defence and Human Health\nCHAPTERCHAPTER\nDisease9\n• What causes disease?\n• What can you do to avoid\ngetting a cold?\n• How might your lifestyle\nincease your risk for\ndisease?\n• How can you prevent\nfood poisoning?\nSC2-09/Q  5/21/03  10:11 AM  Page 156","originalImage":"assets/textbook-page-02.jpg"},{"printed":157,"physical":3,"label":"157","image":"assets/reader-pages/textbook-page-03.jpg","text":"Disease• MHR 157\nWhat You Will LearnYou Will LearnY\nIn this chapter you will learn:\n• what causes human disease\n• how disease spreads\n• the difference between communicable and non-\ncommunicable diseases\n• how to handle food safely\n• about techniques used to kill germs\nWhy It Is Important\nSkills You Will Use\n• Every year, many people get sick or die from diseases\nthat could have been prevented. Knowing about the\ncauses and spread of disease can help you make better\ndecisions about taking care of your health.\nIn this chapter you will:\n• identify causes of disease\n• distinguish between communicable and non-\ncommunicable diseases\n• investigate techniques used to prevent food contamination\n• assess the impact of techniques used to kill germs\nSC2-09/Q  5/21/03  10:11 AM  Page 157","originalImage":"assets/textbook-page-03.jpg"},{"printed":158,"physical":4,"label":"158","image":"assets/reader-pages/textbook-page-04.jpg","text":"Causes of Human Disease\n158 MHR • Disease Defence and Human Health\n9.1\nWhy do people get sick? In the past, people\nthought diseases were caused by various spirits or\ngods. Some people still hold these ideas. Scientists\nhave another theory.\nDisease, or illness, prevents the normal  \nfunctioning of the body. As a result of the invention \nof \nthe microscope, scientists like Louis Pasteur and \nRobert Koch found and identified micro-organisms  \nknown as microbes . The microbes that cause disease \nare called pathogens or germs.\nPathogens are not the only things that cause \ndisease. Some diseases are caused by a poor \nenvironment. For example, air pollution can damage \nthe lungs. \nOther diseases are genetic; for example, muscular \ndystrophy. This disease causes progressive weakness \nof the muscles.\nDisease may also arise from a combination of \nfactors that include the environment, diet, lifestyle, \ngenetics, pathogens, and stress. For example, have \nyou ever noticed how often you get sick when you \nare worried about a relationship? Often, when people \nare stressed, they eat poorly and may stop exercising. \nThe diet and lifestyle choices they make combine \nwith stress to make them more likely to get sick.\nPathogens live in toilets, air conditioners, and \ndirty wash cloths. If these are not cleaned regularly, \nthe number of pathogens may increase. Indoor and \noutdoor pollutants can affect your health to a greater \nor lesser degree, depending on the type and amount \nof pollutants and your sensitivity to them. \nFigure 9.1 In the 1800s, French winemakers were upset \nbecause their wine kept turning to vinegar. Louis Pasteur \ndiscovered that a microbe was causing the spoilage. \nHe heated \nthe grape juice to kill the microbes. This technique is still used \ntoday and is called pasteurization\n.\nFigure 9.2 Robert Koch identified the pathogen that cau ses \nanthrax. He discovered that a pathogen coul d spread from a \nsick person to a healthy person.\nIdentify five factors that may interact with\none another and possibly make you sick.\nSC2-09/Q  5/21/03  10:11 AM  Page 158","originalImage":"assets/textbook-page-04.jpg"},{"printed":159,"physical":5,"label":"159","image":"assets/reader-pages/textbook-page-05.jpg","text":"Disease• MHR 159\n1.Temperature — Most bacteria are active at warm temperatures.\nRefrigeration or \nfreezing slows bacterial growth. Bacteria die when\ntemperatures get \ntoo high.\n2.Moisture — Bacteria need water. Many cannot reproduce without it.\n3.`— Bacteria thrive on sugar, protein, or fats.\nViruses\nLike bacteria, viruses can be found anywhere there are cells to infect — and you are made of trillions of \nsuch cells.\nViruses, such as the common cold virus, are much smaller than \nbacteria. They reproduce by taking over cells in the body. V iruses use \nthe part of the body cell usually used to reproduce cells. In this way, the \nnumber of viruses quickly multiplies, and they invade other body cells.\nPathogens\nPathogens are disease-causing microbes. Most pathogens are \nmicroscopic. These include some bacteria, viruses, fungi, and \nprotists.\nBacteria\nBacteria are on your skin, in your mouth, in the air you breathe, and \nin the food you eat. Why can’t you see them? Because they are single-\ncelled organisms so small that you need a microscope to see one.\nSome bacteria are beneficial to humans. Yogurt, for example, is \nmade from milk and a bacterium that causes milk to go sour. \nOther bacteria are harmful to humans. They cause disease and\nspoil food.\nBoth the harmful and helpful kinds of bacteria reproduce quickly \nand form colonies when conditions are good. The box below shows \nthe type of environment bacteria like.\nGingivitis is one of the most common \ndiseases in the world. It is an inflammation\nof the gums caused by bacterial plaque, a\nsticky, clear film that forms constantly on\nyour teeth. Brushing and flossing daily is\nthe best way to combat gum disease.\nList the conditions\nthat bacteria need to\ngrow. Explain why\neach is important.\nFigure 9.4 The HIV virus that causes AIDS looks like a bomb. It is a virus that flows\nthrough the bloodstream of infected individuals. An infected person may contaminate\nthe blood of an uninfected person in one of several ways. These include:\n• having sexual intercourse\n• sharing intravenous needles\n• receiving a transfusion of infected blood\n• moving through the birth canal of an infected mother\nFigure 9.3\nSC2-09/Q  5/21/03  10:11 AM  Page 159","originalImage":"assets/textbook-page-05.jpg"},{"printed":162,"physical":6,"label":"162","image":"assets/reader-pages/textbook-page-06.jpg","text":"Protists\nProtists are single-celled organisms that share some characteristics\nwith both animals and plants. Two common protists are the\namoeba and the paramecium.\nSome protists cause serious diseases such as malaria, African\nsleeping sickness, and amoebic dysentery. Malaria is spread by\nmosquitoes, sleeping sickness by Tsetse flies. Amoeba can be\npicked up from contaminated water or food.\nA protist called Giardia lives in the intestines of infected\nhumans or animals. Gi ardia may be found in water, food, soil, or\nsurfaces that have been contaminated with the feces from infected\nhumans or animals. You can become infected after you drink the \ncontaminated water.\nTo prevent getting Giardia, drink only safe water. \nFungi\nFungi include molds, yeasts, and \nmushrooms. They cannot make \ntheir own food by photosynthesis. \nSome fungi are parasites and can \nlive only on host organisms. Fungi, \nsuch as mushrooms taste great on \npizza or salad. Others cause disease. \nTwo examples of this are athlete’s \nfoot and ringworm, two fungi that \nlive on the body.\nCheck Your Understanding\n1. Describe three factors that cause disease. Provide an example for each one.\n2. What is a pathogen? Give three examples of pathogens.\n3. Explain how viruses such as the AIDS virus spread.\n4. What might happen to the bacteria in a hamburger you left on the counter\nfor a few hours? Explain why.\n162 MHR • Disease Defence and Human Health\nFigure 9.5 Giardia is the\nmost common protist in the\nworld. In Canada, it is also\ncalled beaver fever because\nbeavers often carry and\nspread the protist.\nFigure 9.6 Athlete’s foot is caused by a fungus \nthat lives on the skin. It breeds under warm, moist\nconditions such as those found in sweaty socks and\nshoes. To prevent it, wear leather shoes and sandals\nso your feet can “breathe.” Wear sandals or slippers\nin places such as change rooms with showers.\npasteurization\ndisease\nmicrobes\npathogens\nbacteria\nviruses\nfungi\nprotist\nparasites\nKey Terms\nHow do protists spread?\nSC2-09/Q  5/21/03  10:11 AM  Page 162","originalImage":"assets/textbook-page-06.jpg"},{"printed":163,"physical":7,"label":"163","image":"assets/reader-pages/textbook-page-07.jpg","text":"Disease• MHR 163\nYou can catch a cold from a friend, but can you get diabetes from one?\nThe answer is no. You can catch a cold from someone because a cold is a\ncommunicable disease. Colds are caused by pathogens that can spread from\none person to another.\nBut diabetes is a non-communicable disease. It is not caused by a\npathogen. Such diseases cannot spread from person to person.\n1.Communicable diseases — These diseases are caused by pathogens.\nThe diseases are communicable because the pathogen carrying the\ndisease \ncan spread from one organism to another. The flu, the\ncommon cold, \nand AIDS are all examples of communicable diseases.\nT\nable 9.1 shows how such diseases spread.\n2.Non-communicable diseases — These diseases are not caused by\npathogens. A\ns a result, they cannot be passed from one organism to\nanother.\nInterestingly, we do not know the cause of all non-communicable diseases.\nToday, doctors have a good idea of how people get such non-communicable\ndiseases as diabetes, cancer, and arthritis. They are still not sure what causes\ndepression and multiple sclerosis. But we do know one thing — people who\nhave them do not pass them on to others.\nTable 9.1 Communicable Diseases and Effects on Health\nSample Disease and Type \nHow Spread of Pathogen That Causes It Effects of Disease\nAirborne\n• commonly spread by coughing and sneezing (a) common cold — virus (a) runny nose, sore throat, cough, low-\n• first sites of infection are the nose, throat, grade fever\nand lungs (b) influenza (flu) — virus (b) fever, aches and pains, cold-like \nsymptoms, extreme fatigue\nWater-borne\n• contaminated water (a) dysentery — bacterium (a) severe cramps, diarrhea (often with \n• disease often spreads through feces that blood and mucus), fever, vomiting\ncontain bacteria. Feces from infected  humans (b) E. coli 0157 — bacterium (b) cramps, bloody diarrhea, complications\nor animals can end up in the water system such as kidney failure\n(for example, swimming pools, hot tubs,\nstreams, ponds).\nCarried in Food\n• unsafe food handling (a) botulism (form of food (a) double vision; difficulty speaking, \n• improper methods used to preserve food breathing, and swallowing\n• improper storage of food\npoisoning) — bacterium\n(b) salmonellosis (form of food (b) fever, headache, nausea, vomiting, \npoisoning) — bacterium diarrhea\nDirect Contact\n• direct contact with an infected person or (a) meningitis — bacterium (a) severe headache, high fever, vomiting, \nwith materials handled by an infected person and virus neck stiffness, joint pain\n(b) STDs (sexually transmitted (b) vary according to disease but often \ndiseases) — bacterium and virus include sores, irregular discharge, itching\n9.2\nDescribe four ways in\nwhich communicable\ndiseases can be transmitted.\nCommunicable and Non-\ncommunicable Diseases\nList the two general types \nof disease and explain the\ndifference between the types.\nSC2-09/Q  5/21/03  10:11 AM  Page 163","originalImage":"assets/textbook-page-07.jpg"},{"printed":164,"physical":8,"label":"164","image":"assets/reader-pages/textbook-page-08.jpg","text":"The Importance of a Clean Environment \nDiseases can be spread by air, water, food, and contact. Why aren’t we all sick\nmost of the time?\nThe answer has to do with our environment. Clean environments reduce the\nnumber of viruses and bacteria present. As a result, there are fewer pathogens\nto make us sick.\nSome environments have to be super clean. There are so many pathogens \nassociated with human feces that bathrooms have to be sanitary. This means \nmaintaining clean, germ-free conditions to help prevent disease. This form of \ncleaning uses special cleaners such as chlorine and anti-bacterial soaps to eliminate \nmost bacteria and viruses. Sanitary cleaning and handling practices should be used \nin all environments where there is a chance of high numbers of bacteria and viruses.\nPeople who work with food must wear protective gloves when they are handling\nfood, to avoid spreading pathogens to people who will eat the food they serve.\nAnother reason they need to handle food carefully is to prevent food poisoning.\nFood poisoning results from eating food that is infected with harmful micro-\norganisms. Such food can make you very ill. In some cases, it can be fatal.\n164 MHR • Disease Defence and Human Health\nFoods containing  \nchicken may beco me \ncontaminated with \nbacteria if they  are not \nhandled properly. To \nprevent salmonell osis, \nchicken needs to  be\nkept hot or cooled\nrapidly after it is cooked\nthoroughly. Chicken not\neaten right away should\nbe refrigerated.\nHow does a clean\nenvironment protect\nyou from disease?\nSC2-09/Q  5/21/03  10:11 AM  Page 164","originalImage":"assets/textbook-page-08.jpg"},{"printed":165,"physical":9,"label":"165","image":"assets/reader-pages/textbook-page-09.jpg","text":"How Do You Get a Non-communicable Disease?\nCommunicable diseases are caused by bacteria and viruses spread by air, water,\nfood, and contact. \nMany non-communicable diseases are the result of bad environmental\nconditions, poor diets, unhealthy lifestyles, and genetics.\nCheck the figures that follow to see how each of these can result in disease.\nDisease• MHR 165\nFigure 9.7 Where do you \nfind the most polluted air?\nWhether or not you\n \nsmoke, it is probably in \nyour home. This is \nbecause it is difficult to \ncirculate fresh air inside \na building. Exposure \nto polluted air (from \ncigarettes, for example) \ncauses diseases such as \nemphysema. Emphysema \nis \na lung condition in \nwhich breathing becomes \ndifficult. \nFigure 9.10 Genetics refers to\nthe characteristics you inherit\nfrom your birth parents.\nGenetic factors are associated\nwith diseases such as cystic\nfibrosis (CF), which damages\nthe respiratory and digestive\nsystems. Exercise may benefit\npeople with CF by improving\ntheir strength and endurance. \nFigure 9.8 If you eat this\nmeal once in a while, don’t\nworry! If you eat this way\nregularly, however, you\nhave a poor diet. People\nwith poor diets often \nsuffer from high levels \nof sickness. For example, \na diet high in fat and\ncholesterol may cause\nheart disease. In heart\ndisease, blood flow to \nthe arteries supplying \nthe heart becomes more\nand more restricted.\nCheck Your Understanding \n1. Define “communicable disease.” List three examples.\n2. Define “non-communicable disease.” List three examples.\n3. Make a table with three columns.\n• In the first column, list at least five diseases you or your family members\nhave or have had.\n• In the second column, identify each disease as communicable or non-\ncommunicable.\n• In the third column, list the effects of each disease on health.\nFigure 9.9 Screen time may be important to you. But \nyou need to balance the amount of down time with active\nexercise. Lack of exercise can result in obesity. People who\nare 10 percent over the ideal body weight for their height\nand bone structure are obese. Being obese strains your\nheart’s ability to function and increases your chances of\ndeveloping Type II diabetes. \ncommunicable\nnon-communicable\nbotulism\nsalmonellosis\nsanitary\nKey Terms\nSC2-09/Q  5/21/03  10:11 AM  Page 165","originalImage":"assets/textbook-page-09.jpg"},{"printed":166,"physical":10,"label":"166","image":"assets/reader-pages/textbook-page-10.jpg","text":"Who Is Most Likely \nto Get Sick?\nIn Canada, the average female can expect to live 81 years. The average male will likely see his 75th \nbirthday. In Sierra \nLeone, an African country, the average female will live only 35 years and the average \nmale 33 \nyears. The difference has to do with living conditions.\nCanada is a wealthy country. Most Canadians have enough food, clean water\nto drink, air that is relatively unpolluted, proper health care, and access to public\neducation. The majority of adult Canadians also have paying jobs.\nPeople in Sierra Leone have access to few or none of these \nthings. In short, they \nlive in poverty. This means that their basic  \nneeds for food, water, health care, and education are not met.\nChildren born in poor countries often die of starvation. They \nare also more likely to get a communicable disease. Because there \nis little health care, they often die from such illnesses.\nThose who do survive to adulthood continue to be more likely\nto get a communicable disease. In Canada, pollution-control\nplants purify drinking water. In poor countries, drinking water\ncomes directly from streams and rivers, which may be full of\nbacteria, viruses, and parasites.\n166 MHR • Disease Defence and Human Health\n9.3\nSierra Leone Canada\nDeaths by Disease Group\nCommunicable diseases\nNon-communicable diseases\nInjuries\n \n86%\n6%8%\n42%\n47%\n11%\nSC2 09 16F\nFigure 9.11 What fraction of people in Sierra\nLeone die from communicable diseases? How\ndoes that compare to the number of people in\nCanada who die from such diseases? \nWhat Are Your Risk Factors?\nNo matter where you live, the same risk factors increase your \nchance of getting sick:\n•not eating properly,\n•drinking unclean water,\n•not having a toilet,\n•not practising personal hygiene, such as washing hands\nfrequently,\n•having sex,\n•smoking tobacco, and\n•consuming alcohol.\n• More than one billion people lack\nclean water.\n• More than two billion people lack toilets.\n• Every year, nearly a billion people suffer\nfrom illnesses caused by contaminated\nwater. The young and the elderly are the\nmost at risk.\n• Over half of the children that die every\nyear die from malnutrition.\nSC2-09/Q  5/21/03  10:11 AM  Page 166","originalImage":"assets/textbook-page-10.jpg"},{"printed":167,"physical":11,"label":"167","image":"assets/reader-pages/textbook-page-11.jpg","text":"Table 9.2 Risk Factors and Disease\nDisease• MHR 167\nRisk Factor Possible Disease Source of Risk\nnot eating properly obesity, diabetes, heart disease, cancer, tuberculosis economic, social\ndrinking unclean water diarrhea, parasites, E. coli economic\nnot having a toilet diarrhea, tuberculosis, parasites economic\nnot practising personal hygiene tuberculosis, food poisoning economic, social\nsuch as washing hands frequently\nhaving sex AIDS and STDs social\nsmoking tobacco emphysema, bronchitis, and other respiratory conditions; social\narteriosclerosis and other circulatory diseases; cancer\nconsuming excess alcohol liver disease, dementia, malnutrition social\nCheck Your Understanding \n1. What is poverty?\n2. Use Table 9.2 to identify what diseases you may be at risk of getting.\nExplain how you could reduce your risk of getting each one.\n3. Defend the statement, “Access to safe water reflects the health of a\ncountry’s people.”\n4.\nWhat type of disease kills most people in poor countries? in rich countries?\nFigure 9.12 Natural disasters, like this flood in Badger, Newfoundl and, in 2003, can result in sanitation \nproblems.  Once the ice thaws, water run-o ff provides breeding grounds for bacteria and viruses. As a \nresult, victims may have limited access to clean water. Large numbers of injured people may overload \nmedical facilities. People may get infections from the unsanitary conditions.\nIn poor countries, all of these problems are worse. In addition, food supplies may not be handled \nor stored properly. As a result, they may become contaminated.\npoverty\nKey Terms\nSC2-09/Q  5/21/03  10:11 AM  Page 167","originalImage":"assets/textbook-page-11.jpg"},{"printed":168,"physical":12,"label":"168","image":"assets/reader-pages/textbook-page-12.jpg","text":"168 MHR • Disease Defence and Human Health\n9.4\nChoose five different \nmethods of food \npreservation. Explain \nhow each one prevents \nfood poisoning.\nMethod Process and Effect on Decomposers\n• Removes moisture so that pathogens cannot grow.\n• Jars filled with food are boiled in a hot water bath to kill existing pathogens.\n• Removes moisture from cells and makes pH inhospitable for bacteria growth.\nsmoking or drying food \ncanning\nsalting\nrefrigeration\n• Bacteria need warm temperatures in order to live and reproduce. Refrigeration slows down the growth of\npathogens.\nfreezing • Freezing causes bacteria to enter a dormant stage.\n• It also prevents the growth of pathogens.\nchemical additives • Additives such as sugar and salt slow the growth of bacteria.\nvacuum packaging • Bacteria need air in order to survive. Vacuum packaging removes air from the package. This reduces the\nnumber of bacteria that spoil food.\n• Unfortunately, some botulism bacteria like low-oxygen environments. They reproduce well in foods\npackaged this way, and can cause food poisoning.\nirradiation • Food is exposed to certain types of radiation energy. This destroys pathogens in meat, fish, and poultry.\npasteurization • Bacteria cannot survive in extremely high temperatures. Pasteurization involves heating a liquid such as\nmilk to a high temperature for a specific period of time. The liquid is then cooled rapidly and refrigerated.\n• It destroys harmful bacteria without changing the flavour or nutritional value of the food.\nStop Disease in Its Tracks\nFood Preservation\nPreserving food prevents or limits the growth of pathogens that cause \nfood poisoning. Table 9.3 explains how each method of food preservation \nhelps prevent or limit this growth.\nTable 9.3 Methods of Food Preservation\nToday, dentists, first-aid volunteers, and even fast-food servers wear\nrubber gloves to protect themselves — and you — from disease.\nPreventing Food Poisoning\nThe staphylococcus bacteria or staph bacteria that cause food \npoisoning\n enter food when you cough, sneeze,  or handle  food \nwithout washing\n your hands properly. Rubber gloves prevent some \nof the\n spread of these bacteria. Careful cleaning of  the cooking \nutensils and area also help. Change dishcloths daily — bacteria \ngrow in used dishcloths. Do not  use sponges,  which provide \ngreat \nbreeding grounds\n for bacteria.\nEach year, there are a few cases of a \nform of food poisoning called botulism. \nThe bacterium that causes botulism\n \nhas the ability to grow in the absence \nof air and produce the deadliest toxin \nknown. The death rate is high if it is \nnot treated immediately. Botulism \ncomes from Latin word botulus, which \nmeans sausage. \nSC2-09/Q  5/21/03  10:11 AM  Page 168","originalImage":"assets/textbook-page-12.jpg"},{"printed":169,"physical":13,"label":"169","image":"assets/reader-pages/textbook-page-13.jpg","text":"Let’s Go \non a Picnic! \nThink About It \nUse what you have learned about safe food handling\npractices to plan a picnic for friends on a hot,\nsunny day. \nWhat to Do \n1Use a chart to organize the following information. \n•In the first column, list each of the foods on\nthe menu: chicken wraps, coleslaw, home-\ncanned black bean salsa, coconut cream pie,\nlemonade, fresh strawberries.\n•In the second column, describe how it\nshould be prepared.\n•In the third column, describe how it should\nbe kept safe from contamination.\n•In the fourth column, identify what form of\nfood poisoning might occur if it is handled\nimproperly.\nAnalyze \n1. (a)If the canned salsa is two years old and the\nseal is broken, what type of illness might\nthe picnickers get? \n(b)What would the symptoms be? \n2.\nWhat advice would you give to a friend who \nwanted to eat potato salad left on a picnic \ntable for several hours?\nExtend Your Skills \n3.Describe your favourite meal. For each food, list\nthe steps you need to follow to keep it safe to\neat. Include steps during and after preparation.\n4.The picnickers decide to help clean up. If\nthere is a choice between dishcloths and paper\ntowels, which would you recommend using?\nExplain why.\nDisease• MHR 169\n9–B9–B\nConsider the foods that have to be kept in a refrigerator. List 10\nor more food products that need to be refrigerated to slow\ndown the rate of food spoilage.\nSKILLCHECK\nInitiating and Planning\n Communication and Teamwork\nInitiating and Planning\nPerforming and Recording\nAnalyzing and Interpreting\n Communication and Teamwork\nThe glass dome over the salad bar is actually a sneeze\nguard to keep bacteria out of salads. \nFigure 9.13\nSC2-09/Q  5/21/03  10:12 AM  Page 169","originalImage":"assets/textbook-page-13.jpg"},{"printed":170,"physical":14,"label":"170","image":"assets/reader-pages/textbook-page-14.jpg","text":"Keeping Hospitals Healthy\nTwo hundred years ago, people expected to die when \nthey went \nto the hospital. Hospitals were so unsanitary \nthat patients often picked up diseases in the hospital. \nToday, this is less common because of the work of \nscientists such as Florence Nightingale, Joseph Lister, \nand Robert Koch.\nIn the 1800s, Florence Nightingale worked in a military \nhospital in Turkey. She reduced the death rate by making \nsure the hospital and patients were kept clean, improving \nwater quality, and bandaging wounds to prevent infections \nfrom spreading to other patients.\nAround the same time, an English surgeon named \nJoseph \nLister realized that many patients died of infections \nfollowing surgery. He began spraying carbolic acid on \npatient wounds and into the air of operating theatres. \nCarbolic \nacid kills pathogens on surfaces and on skin.\nRobert Koch discovered that hot steam was effective in \nkilling pathogens. He began using steam to destroy living \norganisms. This process is called\n sterilization.\n170 MHR • Disease Defence and Human Health\nFigure 9.14 Florence Nightingale \nWhat is the purpose of\nsterilization?\nAseptic Methods\nModern medicine uses many techniques to keep hospital rooms  \nand equipment aseptic or free of pathogens. Aseptic practices \ninclude: \n•using sterile bandages, instruments, linens, masks, and\nclothing during surgery;\n•scrubbing all exposed skin of the surgeon before and after\nsurgery;\n•having surgical staff wear rubber gloves to prevent the\nspread of pathogens that might hide under fingernails.\nIn addition, antiseptics are used on people to disinfect the skin.\nSuch antiseptics include iodine solution and alcohol.\nDisinfectants are used on objects and surfaces to sterilize them. \nSome common disinfectants include iodine, chlorine, bleach, and \nantibacterial soaps.\nSC2-09/Q  5/21/03  10:12 AM  Page 170","originalImage":"assets/textbook-page-14.jpg"},{"printed":174,"physical":15,"label":"174","image":"assets/reader-pages/textbook-page-15.jpg","text":"How do you get rid of\nhuman waste? For centuries, people\ndumped it in water. By 1858, the\nThames River in London, England\nwas so full of sewage that the city\nstank. The smell was so strong that\npeople in the House of Parliament\ncould not work. Laws were passed to\nmake sure the Thames River never\ngot so bad again.\nWho is responsible for preserving\nthe quality of the water you use and\ndrink?\nThe truth is that everyone has a\ncertain amount of responsibility for\nkeeping water safe to drink. The\nfarmers in the second photograph\nrecognize that. That is why they are\nbuilding a fence to keep cattle out of\na stream.\nIn the past, many people died\nfrom diseases because they did not\nunderstand how diseases spread. In\nthis chapter you will explore what\npeople have learned about the spread\nof disease.\nIn the third photograph,\nresearchers test water for possible\ncontamination. In this chapter \nyou will learn about other health\nprograms and assess how important\nsuch programs are in building\nhealthy communities.\n174 MHR • Disease Defence and Human Health\nCHAPTERCHAPTER\nSociety’s ResponseSociety’s Response10\n• What is an epidemic and\nhow does it affect society?\n• How does your lifestyle\naffect your health?\n• How does washing your\nhands stop the spread\nof disease?\n• Where can you find\ninformation on diseases\nthat might affect you in\nthe future?\n• What can you do to\nprotect yourself from\ncommunicable diseases?\nLondoners called 1858 “The Year of the Great Stink.”\nSC2-10/Q  5/21/03  10:16 AM  Page 174","originalImage":"assets/textbook-page-15.jpg"},{"printed":175,"physical":16,"label":"175","image":"assets/reader-pages/textbook-page-16.jpg","text":"Starting Point\nSociety’s Response to Disease• MHR 175\nResponding to an \nOutbreak of Flu\nMost people get the flu at some point. They\nsuffer aching muscles, fever, chills, and\ncongestion. Usually, these symptoms pass\nafter a couple of days. But flu can be deadly.\nDuring 1918, over one billion people — half \nthe world’s total population — got the same flu.\nMany of them died.\nImagine you are an official responsible for\nyour community’s health. Use what you know\nabout how diseases spread to design a poster\nshowing ways people can protect themselves\nfrom the flu.\nWhat You Need\nposter board\ncoloured markers\nWhat to Do \n1.Brainstorm the content of your poster. To\nhelp you, make a chart with two columns.\n• In the first column, list factors that may\ncontribute to the spread of flu.\n• In the second column, list how you might\nprevent the spread of flu.\n2.Create a poster that shows people how\nto protect\n themselves from the flu. Use\ncolour and\n visuals to attract attention to\nyour poster.\nto Diseaseto Disease\nWhat You Will LearnYou Will LearnY\nIn this chapter you will learn:\n• about widespread diseases and how they affect society\n• about the importance of health programs and good\npersonal hygiene\n• how public health guidelines help maintain the health of\na community\n• how individuals help maintain personal and public health\nWhy It Is Important\nSkills You Will Use\n• There are many public health services that can assist you\nin keeping healthy. But unless you know about them,\nunderstand their importance, and actually use them, they\nwill not benefit you. Most of these programs are free —\nwhy not use them?\nIn this chapter you will:\n• list the effects of widespread diseases\n• analyze the impact of contaminated water\n• assess the need for public health guidelines\n• assess the role of individuals in maintaining personal and\npublic health\n• design a public education campaign\nSC2-10/Q  5/21/03  10:16 AM  Page 175","originalImage":"assets/textbook-page-16.jpg"},{"printed":176,"physical":17,"label":"176","image":"assets/reader-pages/textbook-page-17.jpg","text":"How Diseases Affect Society\n176 MHR • Disease Defence and Human Health\n10.1\nEuropean explorers brought many things to the New \nWorld — horses, iron pots, rifles, new seeds. Perhaps \nwhat affected Aboriginal groups the most were the  \ndiseases they brought \n— including smallpox, \ntuberculosis, flu.\nAboriginal groups were not able to fight the \ndiseases because \nthey had never before been exposed \nto certain illnesses. As a result, millions died.\nEffect on Aboriginal Groups \nThe result of so many deaths was tragic.\n•\nWith fewer hunters, more people starved.\n•Many young women died. The birth rate in\nAboriginal communities slowed.\n• Many elders died before passing on the\nknowledge of important traditions. \nPandemic Disease\nToday, diseases such as AIDS and Ebola are affecting \nAfrican society in a similar way. Despite modern \nknowledge of sanitation and personal hygiene, we are \nnot able to prevent the spread of communicable \ndiseases like AIDS because people continue doing \nthings that increase their risk of getting such diseases.\nScientists have a special word for diseases, such as \nAIDS, that are extremely difficult to control. They \nrefer to them as pandemics. Pandemic diseases affect \na large proportion of the population over a large \ngeographic area.\nFigure 10.1 Three\nmembers of this family\ndied within a month. Both\nhistorians and scientists\nread tombstones to learn\nabout past diseases. But\nmany members of one\nfamily dying from an\nepidemic do not tell the entire story. Consider how such\ndeaths affect the community. For example, in farming\ncommunities, many deaths might result in fewer workers,\nmore orphans, and food shortages.\nBiological warfare is not a twentieth century\ninvention. In the 1700s, a British general used\ndisease as a weapon against Aboriginal groups.\nHe distributed blankets from people who had died\nof smallpox. Aboriginals who used the blankets\nquickly contracted the disease and died, as did\nmany others. \nSC2-10/Q  5/21/03  10:17 AM  Page 176","originalImage":"assets/textbook-page-17.jpg"},{"printed":177,"physical":18,"label":"177","image":"assets/reader-pages/textbook-page-18.jpg","text":"Society’s Response to Disease• MHR 177\n10–A10–A\nAIDS and the Law\nThink About It\nAIDS is a communicable disease that is spreading  \naround the world. Some people infected with the \nAIDS \nvirus are knowingly spreading it to others. \nShould these people be charged with a criminal \noffence? Use the following guide to help you \ndevelop and state an opinion.\nWhat to Do \n1 Use Internet sources to gather\ninformation about how AIDS is spread.\n2 (a) Read and think about the articles that\ndiscuss whether or not people with AIDS\nshould be charged with a criminal offence\nif they spread the virus.\n(b) Discuss the ideas with your friends and\nfamily to get further input.\n3 Make a decision about how you feel.\n• Do you think people should not be charged\nunder any circumstances? Then say so and\nexplain why. Remember to provide\nsupporting points for your argument.\n• Do you think some people should be\ncharged but not others? Explain who should\nbe charged, and why. Explain who should\nnot be charged, and why.\n4  Listen to other people’s ideas. \nAnalyze\n1.Think about the ideas expressed by others.  \n(a) List three points you might support. For\neach one, provide a reason for your support.\n(b)List three points you reject. For each one,\nprovide a reason for your lack of support.\n2.Should people with AIDS be responsible for\ntelling the people around them? Consider\nboth sides by suggesting an argument for and\nagainst that each of the following people\nmight make.\n• employer\n• teacher\n• sexual partner\n• member of the community\n• life insurance representative\nSKILLCHECK\nPerforming and Recording\n Communication and Teamwork\nInitiating and Planning\nPerforming and Recording\nAnalyzing and Interpreting\n Communication and Teamwork\nSC2-10/Q  5/21/03  10:17 AM  Page 177","originalImage":"assets/textbook-page-18.jpg"},{"printed":178,"physical":19,"label":"178","image":"assets/reader-pages/textbook-page-19.jpg","text":"Pandemic and Epidemic Diseases\nPandemic diseases affect a large proportion of the people over a large \ngeographic area and are difficult to control. Contagious diseases that are not so \nwidespread are called epidemics. This word is used when many people in a \nlocal area suffer from a disease at the same time.\nStudy the time line below to learn about outbreaks of various pandemic and \nepidemic diseases. Note how each of \nthe outbreaks affected society. Also note \nthe social conditions that contributed to the spread of each disease.\n178 MHR • Disease Defence and Human Health\nThe bubonic plague is a dangerous bacterial disease\nwith symptoms of fever, chills, and swollen glands.\nFrom 1346 to 1350, it spread through Asia and Europe.\nAfter the 1300s, the bubonic plague was not as \nwidespread for several centuries. There were two \nmore pandemics — one in 1542, the other in \n1900. .\n• overcrowded cities\n• limited clean water\n• no waste disposal facilities\n• poor sanitation and hygiene\n• high population of rats that carried the disease\n• 30 to 50 percent of the population died\n• over 100 million deaths worldwide\n•People with the plague were put into\nquarantine. They were held in a sealed-off area\nuntil they died or got better and no longer\nposed a disease threat to others. Only\nauthorities with special permission could enter\nthe quarantine area.\n• crime rate dropped\nTuberculosis is a bacterial disease that damages the \nlungs. It was common in Europe and was spread \naround the world by European explorers.\nIn Canada, tuberculosis is responsible for a lot of\nillness and many deaths among Aboriginal peoples.\nProblems were particularly bad in the North. During\nthe 1950s and 1960s, more than 70 percent of the\nInuit in Keewatin were infected with the tuberculosis\nbacteria.\n• Aboriginal population had no previous exposure\nto the disease\n• overcrowding in boarding schools\n•lack of sanitation\n• poor diets\n•patients were sent to special treatment facilities\ncalled sanatoriums\n• many children were put up for adoption instead\nof being returned to their families\n• some Aboriginal adults lost contact with their\ncommunities\nSocial Conditions\nImpact\n1346–1350\nBubonic Plague Pandemic\n1500s to 1700s\nTuberculosis Epidemic\nFigure 10.2\nIn western Canada in the early\n1900s, 25 percent of Aboriginal and\nInuit children in residential schools\ndied of tuberculosis. Aboriginal and\nInuit people are seven times more\nlikely to get this disease.\nSC2-10/Q  5/21/03  10:17 AM  Page 178","originalImage":"assets/textbook-page-19.jpg"},{"printed":179,"physical":20,"label":"179","image":"assets/reader-pages/textbook-page-20.jpg","text":"Society’s Response to Disease• MHR 179\nThe Spanish flu is a viral disease that spread around\nthe world during 1918. It killed thousands of people\non every continent except Antarctica.• soldiers travelling during World War I spread flu\nto people who had not previously been exposed\n• poor sanitation\n• poor diets\n• little or no access to medical care as health-care\nprofessionals were treating sick and injured\nsoldiers\n• in Canada, more people died from Spanish flu\n(50 000) than from the war\n• 21 million deaths worldwide\n• loss of income for businesses such as theatres\nand restaurants because of fear of catching\nthe flu\n• crime rate dropped\nAIDS is a viral disease that weakens the ability of the\nbody to fight diseases. AIDS was officially recognized\nas a disease in 1980. It is common around the world\nand increasing in severity. In Canada, there is\napproximately a 10 percent increase in new infections\neach year.\n• sexual contact\n• sharing needles (drugs, tattoos)\n• infants born from infected mothers\n• transfusions of infected blood\n• fourth leading cause of death worldwide\n• high costs for treatment; no cure\n• fear and confusion about AIDS results in\nnegative treatment of infected individuals\nSocial Conditions\nImpact\n1918\nSpanish Flu Pandemic\n1980s to present\nAIDS Pandemic\nThe Spanish flu arrived in Alberta in\nOctober 1918, with 15 ill soldiers who were\nreturning from World War I. Although the\nsoldiers were isolated at Scarcee Military\nCamp, the disease spread. The numbers \nof infected people grew so high that the\ngovernment banned public gatherings.\nMore than 3000 Albertans died.\nIn some countries of Africa (e.g., Uganda), up to one-third of the people of child-bearing age are\ninfected with HIV. As a result, many children are poorly cared for or are orphaned at a young\nage. So many people are unable to work that the economy has been adversely affected. The cost\nof treating AIDS is so high that governments cannot afford to treat victims.\nSC2-10/Q  5/21/03  10:17 AM  Page 179","originalImage":"assets/textbook-page-20.jpg"},{"printed":180,"physical":21,"label":"180","image":"assets/reader-pages/textbook-page-21.jpg","text":"The Beginning of Public Health\nImagine living during the bubonic plague pandemic, \nwhen people \ndid not know what caused disease. \nImagine how frightened you would be.\nAt first, nothing was done to kill the rats that \noriginally spread the disease. In addition, people \ndumped human waste in the streets. After some \npeople began to understand that there might be a \nconnection between sanitation and disease, city \nofficials ordered streets to be cleaned and \nquarantined sick people in special facilities.\nAs people began to see the results of these kinds of \nmeasures, they became more interested in working \ntogether to develop healthy communities. This is \nreferred to as public health.\nGradually, the government got involved in caring for public health. In \nEngland, “The Year of the Great Stink” helped speed the development of these \nlaws. People who dumped waste and sewage in the Thames River were fined. \nEven though the new laws were not very well enforced, they were the beginnings \nof the public health system we have today.\n180 MHR • Disease Defence and Human Health\nFigure 10.4 Sanitary public toilets are not available everywhere\naround the world. Some countries use a cesspit, which is like an\nopen hole. When the cesspit becomes full, urine and feces slop\nover the sides and could run into the street, spreading any \ndisease pathogens that are present. \nCheck Your Understanding \n1. When does an epidemic become a pandemic?\n2. Make a list of the impact of pandemic diseases on society.\n3. List three pandemic diseases. Identify the social conditions that contributed\nto the spread of each one.\n4.With a partner, use the Internet to research one of the following epidemic \ndiseases: smallpox, cholera, typhoid fever, diphtheria, whooping cough. \nDevelop a short presentation that mentions:\n• how it spreads\n• details about the disease\n• its impact on society\npandemics\nepidemics\nquarantine\npublic health\nKey Terms\nSC2-10/Q  5/21/03  10:17 AM  Page 180","originalImage":"assets/textbook-page-21.jpg"},{"printed":181,"physical":22,"label":"181","image":"assets/reader-pages/textbook-page-22.jpg","text":"Health programs came to Canada after World War I as a direct result of the 1918 \nSpanish flu pandemic. Canadians realized they needed to rebuild the population. \nThey also realized that they never wanted to suffer such a pandemic again.\nIn 1919, the Canadian government established its first department of health. \nToday, provincial health departments throughout the country do such jobs as:\n•monitoring the safety of drinking water,\n•checking the pollutants in the air we breathe, and\n•taking measures to avoid outbreaks of disease.\nIn Alberta, the public health service is called the Regional Health Authority.\nThis authority offers many public health programs and services. Study Figures\n10.5 to 10.11 and the captions with each figure. As you do, make notes about\nthe programs and services provided by public health organizations and how\neach improves human health.\nSociety’s Response to Disease• MHR 181\nImproving Human Health10.2\nWater Quality Removal of Garbage\n• Water is tested on a regular basis to ensure it is\nsafe for drinking, cooking, bathing, or swimming.\n• Water is treated to make it safe to drink.\nTreatment plants use chemicals such as chlorine\nto kill harmful bacteria.\n• Landfill sites prevent waste materials from\nharming the environment or entering the\nwater system. Before the landfill is used, the\nground is sealed to prevent toxic chemicals\nfrom accidentally entering the water supply.\nFigure 10.5 Water quality specialists test beach water and report\nany problems to the public. For example, if the bacterial count in\na lake reaches dangerous levels, beaches may be closed until the\ncount returns to safe levels. \nFigure 10.6 Most of our garbage ends up in landfill sites like the\none shown here. \nSC2-10/Q  5/21/03  10:17 AM  Page 181","originalImage":"assets/textbook-page-22.jpg"},{"printed":182,"physical":23,"label":"182","image":"assets/reader-pages/textbook-page-23.jpg","text":"Treatment of Human and Animal Wastes\n• In sewage treatment plants, solid wastes are removed by settling or filtering.\nHelpful bacteria decompose any organic matter. The water is treated\nchemically to make it safe to drink. \n• Large-scale livestock operations produce large quantities of manure that\nmust be treated. Some producers store the manure in large lagoons on\ntheir farms. Modern treatment facilities separate solids from liquids,\nremove excess fertilizers, and recycle clean water for farm use. The liquid\nmanure is then spread on cropland. \n182 MHR • Disease Defence and Human Health\nAir Quality Index (AQI) Categories\n0 – 15 Very Good\n16 – 31 Good\n32 – 49 Moderate\n50 – 99 Poor\n100/H11001 Very Poor\nFigure 10.7 The Air Quality Index provides a reading of air quality\nand reasons for poor quality for many communities. Smog, which\nis a mixture of air pollutants, might be one reason for poor quality\nair. A smog alert warns people who are at risk or suffer from\nheart or lung problems to take protective action such as choosing\nto stay indoors. \nFigure 10.8 When children are two months old, they begin \nreceiving injections that provide them with protection from various \ncontagious diseases. Most children get injections regularly until \nthey are four to six years old. As they get older, they may receive \nbooster shots to renew their protection. \nAir Quality Mass Vaccination\n• Air quality is tested and the results are provided\nto the public. Health Canada has developed\nstandards and guidelines that list allowable levels\nof pollutants in the air you breathe. When the\nlevels of pollutants are too high, people are\nadvised to stay indoors and avoid heavy physical\nexercise. Physical exercise increases the body’s\nneed for oxygen, which may be difficult to get\nwhen there is poor air quality.\n•\nVaccinations increase people’s ability to fight off \na disease. In Canada, children are often \nvaccinated against diphtheria, whooping cough, \nmeasles, mumps, tetanus, polio, and rubella. \nPeople who travel to other countries may get \nshots against yellow fever, typhoid fever, or \nhepatitis. They need to check health information \nfor the destinations they are travelling to in order \nto adequately protect themselves.\n•Public health officials often develop new\nvaccinations \nthat respond to new outbreaks of\ndisease. For example, meningitis is an inflammation\nof the \ncovering of the brain. When this disease\nstarts to spread in an area, public health officials\nprovide free \nvaccinations against it to children\nand teens, who are most likely to get the infection.\nDescribe four concerns\nthat public health programs\nhave addressed.\nSC2-10/Q  5/21/03  10:17 AM  Page 182","originalImage":"assets/textbook-page-23.jpg"},{"printed":183,"physical":24,"label":"183","image":"assets/reader-pages/textbook-page-24.jpg","text":"The Choice Is Yours\nThese are just some of the programs developed to decrease \nthe spread of disease and protect human health. The fact \nthat you are studying this in school suggests that public \nhealth authorities consider educating people about health \nto be very important.\nThe next link in the chain is you. Are you concerned enough\nabout your health to learn the many ways you can stay healthy?\nDo you care enough to maintain high standards of personal\nhygiene? When you get sick, are you willing to make sure \nthat you do not spread the disease to others? Do you take time\nto learn how to protect your own and others’ health and safety\nby taking training in first aid, swimming, lifesaving, or\nbabysitter’s training?\nSociety’s Response to Disease• MHR 183\nFigure 10.9 Education campaigns reduce the \nnumber of illnesses spread by poor food \nhandling. The campaign promotes four points: \n•Clean — wash hands and surfaces often\n•Cook — cook to proper temperature\n•Separate — do not cross-contaminate (for\nexample, keep separate cutting boards for \nmeats and vegetables)\n•Chill — refrigerate promptly\nFood Safety\n•Health authorities use newspapers, \nradio, pamphlets, brochures, and the \nInternet to promote food safety \nawareness. Food inspectors check \nthat workers in restaurants, food \ncompanies, and meat packing plants \nhandle food safely.\nCheck Your Understanding \n1. In your own words, explain the role of public health in Canada.\n2. Why is chlorine used to treat swimming pools and drinking water?\n3. (a) How do high standards of personal hygiene affect individuals?\n(b) How do such standards affect the community?\n4. Describe three local public health programs. How does each one protect\ncommunity health?\n.\nvaccinations\nKey Terms\nSC2-10/Q  5/21/03  10:17 AM  Page 183","originalImage":"assets/textbook-page-24.jpg"},{"printed":184,"physical":25,"label":"184","image":"assets/reader-pages/textbook-page-25.jpg","text":"Public Health and You\nVaccinations have reduced the number of people who die from communicable\ndiseases. For example, smallpox has killed millions of people around the world.\nToday, the smallpox virus exists only in laboratories. Vaccination against\nsmallpox is no longer recommended.\nDoes this mean that communicable diseases are no longer a serious problem?\nShould you just ignore public health guidelines?\nThe answer is no. There are many reasons for keeping an eye on public\nhealth guidelines.\nProtecting Health\nDiseases are not going away. In fact, many old diseases that were thought to \nhave \ndisappeared are resurfacing. These include polio and drug-resistant \nvariations of \ntuberculosis. New diseases, such as AIDS and SARS, are also \nemerging\n. Public health guidelines help to protect you from these and other \ndiseases. T\nable 10.1 explains how.\nTable 10.1 Factors that spread disease and Public Health Guidelines\n184 MHR • Disease Defence and Human Health\nConcern Public Health Guidelines\n• overcrowded conditions • Good personal hygiene reduces the spread of pathogens.\nFactor \npopulation growth and \novercrowding increase the chances of being • Treating and disposing of wastes also reduces their spread.\nexposed to pathogens\nmigration • diseases may be carried from • Disease monitoring keeps an eye on the level of disease.\ncountry to country or from rural • When levels are high, emergency response plans may prevent migration.\ncommunities to cities • Travellers and their belongings are disinfected to prevent the spread of\npathogens.\nlifestyle • people eat out • Restaurant inspections ensure food-handling practices are safe and\neating areas and utensils are kept sanitary.\ntravel • increased exposure to disease • T ravellers receive special vaccinations before travelling to some countries.\n(for example, eating improperly • Travellers receive brochures explaining how to protect themselves from\nprepared foods, using unsanitary pathogens in food and water.\npublic washrooms)\nfood supply • food comes from many • Food inspectors test foods for pathogens.\ncountries\n• food may harbour pathogens\n• sexual contact results in • STD awareness programs provide the facts.sexual activity and \nchildbirth spread of sexually transmitted • Prenatal nutrition programs teach mothers proper nutrition.\ndiseases (STDs) • Awareness education programs for fetal alcohol spectrum disorder reduce\nunderweight babies, the number of mothers who drink during pregnancy.\n• unhealthy mothers number of mothers who drink during pregnancy.\n10.3\nGive three reasons why\npublic health guidelines\nare necessary.\nSC2-10/Q  6/9/04  10:52 AM  Page 184","originalImage":"assets/textbook-page-25.jpg"},{"printed":185,"physical":26,"label":"185","image":"assets/reader-pages/textbook-page-26.jpg","text":"Health Warnings\nSociety’s Response to Disease• MHR 185\nFigure 10.12 Public health guidelines \nexplain how to correctly install and adjust \nchild car seats. The correct use of child \nsafety seats protects infants and young \nchildren from injury. \nFigure 10.11 Public health\nofficials encouraged\nlegislators to pass a law\nrequiring all cyclists under 18\nto wear helmets when they are\nbiking. Falling off a bicycle —\neven onto a soft surface when\nyou are biking at a low speed\n— can cause brain damage. \nHow do you know when there is a major health \nconcern? Health authorities release warnings or \nadvisories to alert you. These include:\n•food recalls — In a food recall, all products \ncontaining a contaminated ingredient must \nbe removed from store shelves. Radio and \ntelevision news programs name the product, \nexplain the danger, and tell the public what \nto do.\n•boil-water advisories — When tests show \ndrinking water is unsafe, health authorities \nwarn members of the public to boil all water \nused for personal purposes such as drinking, \ncooking, and brushing teeth.\n•mass vaccinations — When a communicable \ndisease is beginning to spread, health \nofficials provide free vaccinations for people \nlikely to get the disease.\n•road safety — In order to protect people \nwho ride bicycles or drive\nvehicles, public health authorities \nprovide information about the\nproper use of helmets, seatbelts,\nand other safety equipment.\nAlberta also has laws enforcing\nthe use of child safety seats and\nbike helmets.\nFigure 10.10 The concern\nabout infectious diseases\nis worldwide. This\nChinese poster tells\npeople how to reduce the\nspread of scarlet fever. It\nsays: \n• Go to hospital as early\nas possible when\ninfected.\n• See a doctor as soon\nas you have a sore\nthroat.\n• Take the vaccination.\nSC2-10/Q  5/21/03  10:17 AM  Page 185","originalImage":"assets/textbook-page-26.jpg"},{"printed":187,"physical":27,"label":"187","image":"assets/reader-pages/textbook-page-27.jpg","text":"From the Womb to the Grave\nPublic health guidelines help prevent disease and promote wellness. Study the\nvisuals below and read the captions to see how public health programs can\nimprove the quality of life during each stage of an individual’s development.\nSociety’s Response to Disease• MHR 187\nWhat are two ways in\nwhich public health\nservices help prevent\ndisease?\nFigure 10.14 Children are vaccinated against\ncommon diseases before starting school. These\nvaccinations reduce the spread of communicable\ndiseases. Vaccinations are provided for other high-\nrisk groups too. For example, seniors, health-care\nworkers, and teachers may get flu shots to protect\nthem during the flu season. \nFigure 10.15 Public health nurses work with teachers\nto promote health. For example, tobacco is an important\npublic health issue. Using ads such as this one developed\nby Health Canada helps take the glamour out of\nsmoking. Learning about health risks allows you to\nmake informed choices. \nFigure 10.16 Health\nguidelines promote staying\nactive and fit to live long\nand live well. Practising\nTaoist Tai Chi is one way\nthat you can keep fit\nmentally and physically. \nFigure 10.13 The Canada Prenatal Nutrition\nProgram educates pregnant women about\nlifestyle issues. This program works with\nwomen who have risk factors that may\nthreaten their health and the development of\ntheir baby. For example, they work with\nyoung mothers to encourage them to eat\nfoods that will help the baby develop properly.\nSimilarly, they advise pregnant women that\nthe use of alcohol, tobacco, or drugs\nnegatively affects the development of a baby. \nSC2-10/Q  5/21/03  10:17 AM  Page 187","originalImage":"assets/textbook-page-27.jpg"},{"printed":189,"physical":28,"label":"189","image":"assets/reader-pages/textbook-page-28.jpg","text":"How Important Are Your Personal Actions?\nProper hand washing is only one aspect of personal health.\nYou have other important choices to make. Consider these.\n1. Protect your own health — take care of your personal\nhygiene; get vaccinations; keep informed about health\nadvisories\n2. Make wise lifestyle choices — exercise regularly; eat a\nwell-balanced diet; avoid smoking, alcohol, and non-\nprescription drugs; avoid sexual contact\n3. Adopt safer practices — wash your hands often; wear bike\nhelmets and seat belts; when you become sexually active,\npractise safe sex\nYour choices — wise or otherwise —\nwill affect the people around you.\nSociety’s Response to Disease• MHR 189\nFigure 10.17 How does\nwashing your hands protect\nothers from disease? \nHow do personal actions contribute to\nthe health of your community?\nCheck Your Understanding \n1. List five factors that account for the spread of communicable disease.\n2. Do you think it is important to have public health guidelines? Use\nexamples to help you explain why or why not.\n3. Defend the statement, “An ounce of prevention is worth a pound of cure.”\n4. What are three steps you can take to protect your own health? Provide a\nspecific example of each.\nSC2-10/Q  5/21/03  10:17 AM  Page 189","originalImage":"assets/textbook-page-28.jpg"},{"printed":192,"physical":29,"label":"192","image":"assets/reader-pages/textbook-page-29.jpg","text":"Don’t touch the keyboard!\nThere’s a chicken pox virus hanging\naround.\nHold your breath — someone\njust sneezed!\nYou have many opportunities to\nbe exposed to disease. Why don’t\nyou get sick more often?\nThe answer is that your body has\nseveral lines of defence against\ndisease. In this chapter you will learn\nabout the ways your body protects\nitself from invaders. You will learn\nabout treatments available for when\nyou do get sick. For example, you can\nprevent tetanus, which is caused by\nbacteria that enter your body through\na cut, by getting a vaccination against\nit, and then continuing to get booster\nshots periodically.\nAre your vaccinations and booster\nshots up to date? By the end of this\nchapter, you might want to check.\nTake a look at the mould in the\nphotograph at the top of page 193.\nPenicillin, which was the first\nantibiotic developed, comes from\nthis mould, which grows on bread!\nToday, there are many types of\nantibiotics. In this chapter you will\nalso learn why you need to use\nantibiotics properly.\n192 MHR • Disease Defence and Human Health\nCHAPTERCHAPTER\nProtecting YourselfProtecting Yourself11\n• How does your body\nprotect itself from\ndisease?\n• What does your immune\nsystem do?\n• What vaccinations have\nyou had?\n• How might using\nmedicines improperly\nharm you?\nSC2-11/Q  5/21/03  10:27 AM  Page 192","originalImage":"assets/textbook-page-29.jpg"},{"printed":193,"physical":30,"label":"193","image":"assets/reader-pages/textbook-page-30.jpg","text":"Protecting Yourself from Disease• MHR 193\nfrom Diseasefrom Disease\nWhat You Will LearnYou Will LearnY\nIn this chapter you will learn:\n• how your body’s physical defences prevent infection\n• how your blood helps control pathogens\n• how your immune system protects you\n• how antibiotics and vaccinations prevent or treat disease\n• about the dangers of using antibiotics improperly\nWhy It Is Important\nSkills You Will Use\n• You have likely taken antibiotics in order to fight\ninfections. When antibiotics are used incorrectly, the\nbacteria and viruses in your body become resistant to\nthem and the antibiotics may no longer work. Knowing\nhow this happens will help you use antibiotics so they\ncontinue to be effective.\nIn this chapter you will:\n• identify physical defences against infection\n• explain the role of blood in controlling pathogens\n• describe the body’s immune system\n• describe how antibiotics and vaccinations prevent\nor treat disease\n• analyze cold remedies\nSC2-11/Q  5/21/03  10:27 AM  Page 193","originalImage":"assets/textbook-page-30.jpg"},{"printed":194,"physical":31,"label":"194","image":"assets/reader-pages/textbook-page-31.jpg","text":"Defences against Pathogens\nMillions of potentially harmful pathogens surround you every day . They live on \nyour body and on most surfaces you touch. So why aren’t you sick all the time? It is \nbecause \nyour body has three lines of defence against pathogens: physical defences, \nthe \ninflammatory response, and the action of antibodies. Antibodies are released by \nwhite blood cells in order to destroy pathogens that have invaded the body .\nFigure 11.1 shows you the physical defences. This first line of defence \ninvolves \nbody structures such as the skin and secretions such as mucus. Each of  \nthese forms a physical barrier against pathogens. Read the labels with Figure 11.1  \nto learn how your body’s physical defences work and where they are located.\n194 MHR • Disease Defence and Human Health\nSkin\nconsists of a thick barrier with an acidic surface that\nprevents pathogens from entering\nprevents loss of body fluids\n•\nTonsils and Adenoids\n•\n•\ncatch pathogens before they enter body; may become infected\nto help the immune system resist and fight future infections\nstore white blood cells\n•\n•\nStomach\ncontains hydrochloric acid that kills pathogens\nNose and Sinuses\n•\n•\ncontain hair and mucus, which trap pathogens before they\ncan enter the respiratory system\nwarm incoming air\nHair\ntraps or repels pathogens•\nEar\ncontains wax, which traps pathogens and small particles•\nEyelids\ncover the eyeball to keep out pathogens, dust, and other particles\nblink automatically to repel objects\n•\n•\n•\nTears\nconsist of salty fluids that wash eyes clean\nEyelashes • \nprotect the eye\nFigure 11.1 Physical defences\nList the body’s physical\ndefences against disease.\n11.1\nSC2-11/Q  5/21/03  10:27 AM  Page 194","originalImage":"assets/textbook-page-31.jpg"},{"printed":195,"physical":32,"label":"195","image":"assets/reader-pages/textbook-page-32.jpg","text":"The Inflammatory Response\nHave you ever got a sliver — and soon afterward noticed an inflammation \naround the area? This is an example of an inflammatory response. During an \ninflammatory response, the blood vessels surrounding the injury swell. The \narea becomes red and warm as more blood arrives.\nThe body has several inflammatory responses.\n•If pathogens get past the physical barrier created by the skin, the body \nsends white \nblood cells, that are apart of the immune system, to repel the \ninvader. \nStudy Figure 11.2 and read the caption to see how this works.\n•An inflammatory response can also occur when the skin is hit, for instance, \nwhen you fall and hit the ground. This response is caused because blood  \noozes from the ruptured blood vessels into surrounding tissue. White \nblood cells engulf damaged cells and cell parts at the site of the bruise in \norder to clean up and heal the bruised area.\n•Any kind of infection (e.g. tonsillitis or appendicitis) will trigger an \ninflammatory response. The ‘itis’ ending of these words means\n“inflammation of.”\nPhysical defences and the inflammatory responses\nare called general defences because the body reacts\nin the same way regardless of what kind of pathogen\nis invading. For example, you will blink when\nsomething enters your eye. This happens both \nwhen it is something you want there, such as a\ncontact lens, or something damaging, such as dust.\nThe third line of defence is the formation of \nantibodies in the immune system. This line of \ndefence targets specific pathogens and will be \ndiscussed \nin detail in the next section of this chapter. \nProtecting Yourself from Disease• MHR 195\nFigure 11.2 The blood vessels surrounding this splinter \nswell. The area becomes red and warm as more blood \na\nrrives. Specialized white blood cells called macrophages \nsurround and destroy damaged cells and pathogens such \nas viruses \nand bacteria. Macrophages engulf the splinter \nand start destroying it.\nFigure 11.3 Look at\nhow macrophages\nengulf invading cells.\nWhite blood cells leave\ncapillaries (A) and\nengulf harmful bacteria\n(B). Macrophages can\nconsume large numbers\nof pathogens at once.\ncapillary\nmacrophage\nharmful\nbacteria\ncapillary wall\nwhite\nblood cellA\nB\nSC2-11/Q  5/21/03  10:27 AM  Page 195","originalImage":"assets/textbook-page-32.jpg"},{"printed":197,"physical":33,"label":"197","image":"assets/reader-pages/textbook-page-33.jpg","text":"Have you or someone you know ever had the chicken pox? Few of your friends \nmay have \nhad this disease, since there is now a vaccination for it. However, even if \nyou have \nnot been vaccinated, if you have already had the disease, you are unlikely \nto get it \nagain. This is because you have built up immunity — or resistance — to \nchicken pox. If you were exposed to the virus again, your immune system would \nrecognize and resist it.\nYour body recognizes substances called antigens that are not part of itself. \nAntigens are specifically \nshaped structures that are attached to pathogens. All \nliving tissues such as viruses, bacteria, and fungi contain antigens. So do pollen,  \ntransfused blood, \ntransplanted organs, and cancer cells.\nHow does your immune system respond to the antigens it encounters? Most \nof this \nis done at the cellular level by white blood cells. White blood cells make \nand release Y-shaped protein compounds called antibodies . Antibodies bind to \nspecific antigens. This makes it easier for white blood cells to destroy them.\n•When you first contacted the chicken pox virus, your body did not have\nantibodies against the chicken pox antigen. It immediately started\nproducing them.\n•Once your body has antibodies to a pathogen such as chicken pox, your \nimmune system recognizes and destroys the antigen whenever it shows up \nagain. This is why you are considered to be immune to the disease.\nFigure 11.4 explains how antibodies combine with antigens.\nProtecting Yourself from Disease• MHR 197\nImmunity11.2\nThe average person has\nmore than 100 000\nantibodies waiting for the\ninvasion of antigens.\nDescribe how antigens\nand antibodies interact.\ninvading pathogens\nbinding site\nantigen\nmarkers\nantibody\nmarker\nAntibody\nType A\nAntibody\nType B\nFigure 11.4 Each antibody has a shape that matches a specific\nantigen. This means that an antibody produced against a cold\nvirus, for example, would not fit with an HIV antigen.\n• Antibody Type A attaches one type of antigen with a\ncomplementary shape, like a lock and key. For example, a flu\nantibody would combine with flu antigens.\n• Antibody Type B does not combine with the antigen because\ntheir shapes do not match. Notice the outer edge of each arm\nof the antibody and the antigen. The antibody markers are\ndifferent from those found on the antigen.\nSC2-11/Q  5/21/03  10:27 AM  Page 197","originalImage":"assets/textbook-page-33.jpg"},{"printed":199,"physical":34,"label":"199","image":"assets/reader-pages/textbook-page-34.jpg","text":"Types of Immunity\nYou are born with a certain amount of immunity. This is called inherited  \nimmunity. Inherited immunity refers to the resistance that organisms have to  \nmost diseases. This form of resistance is passed on from your mother.\nFrom birth on, you build what is called acquired immunity. Figure 11.6 shows \nthat acquired immunity is divided into two types according to how you get it.\n•Your body develops active immunity by making antibodies against diseases \nto which you have been exposed. This is the type of immunity you might \ndevelop against chicken pox.\n•You acquire passive immunity from antibodies produced in another\nanimal and put in your body. This is the kind of immunity you get when \nyou get a vaccination.\nProtecting Yourself from Disease• MHR 199\nExplain the different ways\nthat people can develop \nor acquire immunity. \nGive an example of each.\nImmunity\n• ability to resist disease\nInherited Immunity\n• present in the body\nfrom birth\n• lasts over a lifetime\nAcquired Immunity\n• develops in the body\nduring lifetime\nActive Immunity\n• the body makes its\nown antibodies\n• is usually permanent\nPassive Immunity\n• antibodies are\nintroduced to the body\n• does not last as long as\nactive immunity\nA. Naturally Acquired Active\nImmunity “Strawberry tongue”\nis often a symptom of scarlet\nfever. Once you have had\nscarlet fever, you are unlikely to\nget it again. That is because\nyour body builds immunity\nagainst the disease.\nB. Artificially Acquired Active\nImmunity Hepatitis B vaccine\nworks well against hepatitis in\nteens. This provides artificial\nimmunity. The hepatitis virus\nis cultivated by infecting \nyeast cells.\nC. Naturally Acquired Passive\nImmunity As long as babies\ncontinue to breast-feed, they\nare immune to many of the\nsame diseases as their mother.\nD. Artificially Acquired Passive\nImmunity Small amounts of snake\nvenom are injected into animals\nsuch as cows or horses to create\nantibodies. The antibodies are\ncalled antitoxins. The antitoxin is\nremoved from the animal’s blood\nand used to provide immunity in\npeople who are bitten by that type\nof poisonous snake. \nFigure 11.6\nSC2-11/Q  5/21/03  10:28 AM  Page 199","originalImage":"assets/textbook-page-34.jpg"},{"printed":200,"physical":35,"label":"200","image":"assets/reader-pages/textbook-page-35.jpg","text":"Blood Transfusions\nDo you know which blood type you are?\nThere are four blood types: A, B, AB, and O. Doctors check patients’ blood\ntype before giving a transfusion. That is because the blood type of the\ntransfusion must match the blood type of the person who gets it.\nBlood types must match because there are two kinds of antigens on the red \nblood cells of humans and two kinds of antibodies in the plasma. If the blood \ntypes do not match, antigens will react with antibodies, causing blood cells to \nclump, clumping can lead to heart attacks and strokes.\n Following is a chart that outlines donor blood compatability.\n200 MHR • Disease Defence and Human Health\nSC2-11/Q  5/21/03  10:28 AM  Page 200\nWhy do some people get a flu shot each year?\nThey know that their body can develop immunity by  getting \neither an injection of vaccine.\n•A vaccine consists of weakened or dead disease\npathogens. Once a vaccination or immunization is inside  your body,\nyour body begins to produce antibodies against the antigens in the\nvaccine. The disease is weaker  than usual because of the weakened or\ndead pathogens.\nAs a result, you get few or no symptoms. After your body\nproduces antibodies, you have lasting protection against the real disease.\n11.3 Immunization\nantigens\ninherited immunity\nacquired immunity\nactive immunity\npassive immunity\nKey Terms","originalImage":"assets/textbook-page-35.jpg"},{"printed":201,"physical":36,"label":"201","image":"assets/reader-pages/textbook-page-36.jpg","text":"See Table 11.1 for the \nlist of preventable diseases most Canadians are\nimmunized against, and the effects of each disease.\nProtecting Yourself from Disease• MHR 201\nDisease Effects of Disease\ndiphtheria • infection in nose and throat can make breathing difficult\n• skin infections, rapid pulse\n• heart failure, paralysis, death\nmeasles • red rash, high fever, cough, sore throat\n• often ear infections and pneumonia\nmumps • painful, swollen salivary glands; fever; headache\npolio • fever, headache, stiff neck and back, muscle weakness\n• often permanent paralysis, death\nrubella • mild fever, rash, swelling of the neck\n• dangerous during early pregnancy; causes miscarriages and handicaps\ntetanus • muscle spasms, difficulties breathing\n• death\nwhooping cough • severe coughing, difficulties breathing\n• often pneumonia\n• sometimes brain damage and death\nTable 11.1 Preventable Diseases \nYou were born with all of your \nmother’s antibodies. These \nantibodies lasted a short time, \nlonger if you \nwere breastfed. \nChildhood vaccinations allow \nyou to continue having the \nbenefits of this immunity.\nSC2-11/Q  5/21/03  10:28 AM  Page 201\nWhy Get Immunization Shots?\nSome people \ndo not get immunized for personal or medical reasons. For example, some people react \nto \ncertain immunizations. Such reactions often occur in people whose immune systems have been \nweakened by a\n disease such as asthma or by severe allergies. In such people, whooping cough vaccine \ncan occasionally cause\n reactions such as high fevers or seizures.\nIf vaccinations can cause such reactions, why do most people get them?\nBasically, immunizations prevent more problems than they create. Immunizations have reduced \nthe incidence of communicable diseases and the number of deaths from them. Worldwide \nimmunization against smallpox, for example, has actually eliminated that disease.\nRecently, some countries have stopped or limited immunization \nprograms. As a \nresult, there have been increases in diseases, such as \npolio, that had almost disappeared.\nWhy should you get\nimmunizations?\nAllergies\nAllergies develop when the immune system overreacts and becomes sensitive to\nsubstances such as pollen, dust, or mould. The immune system then treats the\nsubstance as though it were a pathogen and begins to build antibodies against\nit. These antibodies result in a variety of symptoms. Mild reactions include a\nrunny nose and itchy or watery eyes. Severe symptoms can include breathing\ndifficulties, and can build to extreme allergic reactions that cause death.\nScratch tests identify allergens. Drops of antigen are absorbed under the\nscratched skin. Allergic reactions produce redness, swelling, and itching along\nthe scratch.\nPeople who suffer from allergies sometimes get immunotherapy. This\ninvolves injections of weakened allergens. Regular injections build the number\nof antibodies against the allergen.","originalImage":"assets/textbook-page-36.jpg"},{"printed":204,"physical":37,"label":"204","image":"assets/reader-pages/textbook-page-37.jpg","text":"Treating Infectious Diseases\nNo vaccine has yet been developed that can prevent colds! That’s because the \ncold virus keeps mutating. As fast as someone tries to develop a vaccine for the \ncommon cold, a new cold virus appears. When you get a cold, your body is \nusually able to heal itself within about a week. There are times, however, when \nyour body needs help.\nUsually, people try over-the-counter drugs to relieve or treat symptoms. \nOver-the-counter drugs are sold without a doctor’s prescription. They relieve \nsymptoms such as fevers and headaches that accompany colds, but do not kill \nthe viruses that cause the cold.\nIf symptoms of infection \ncontinue, your doctor may \nprescribe an antibiotic. \nAntibiotics fight bacterial \ninfections by either killing \nbacteria or preventing them from \nreproducing. Each antibiotic is \neffective against specific types of \nbacteria. They do not, however, \nhelp with a viral infection.\nWhen treating a cold or strep \nthroat, you need to know\nwhether or not the infection is \nbacterial or viral. Viruses cause \ncolds, the flu, most sore throats,\ncoughs, and sinus infections. Since antibiotics do not work \nagainst viruses, the best thing you can do for these is to drink \nplenty of fluids, get rest, and perhaps take over-the-counter \ndrugs to relieve any symptoms. Since bacteria cause strep \nthroat and pneumonia, an antibiotic might be effective in \ntreating these.\n204 MHR • Disease Defence and Human Health\n11.4\nHow can you decide\nbetween using an\nantibiotic or an over-the-\ncounter drug?\nFigure 11.8 A blue mould called \npenicillium notatum became famous \nafter Sir Alexander Fleming of \nScotland discovered it by accident in \n1929. He noticed some mould \ncolonies growing in a dish of \nbacteria he was studying. No \nbacteria were growing around each \nmould colony. Fleming concluded \nthat the mould produced a \nsubstance that killed the bacteria. \nHis work led to the discovery of \npenicillin — the first antibiotic. \nToday scientists develop antibiotics \nfrom fungi, moulds, and bacteria. \nFigure 11.9 Scientists test antibiotics by growing\nbacterial colonies and introducing small disks of\nantibiotics to the bacteria. You can see the mould\nis killing some bacteria. Scientists determine the\neffectiveness of antibiotics by measuring the size\nof the “no-growth” zone. \nSC2-11/Q  5/21/03  10:28 AM  Page 204","originalImage":"assets/textbook-page-37.jpg"},{"printed":205,"physical":38,"label":"205","image":"assets/reader-pages/textbook-page-38.jpg","text":"Problems with Antibiotics\nSome people demand antibiotics to fight every cold and sore throat they have. \nThis is not a good idea for the following reasons: \n•They kill harmful and helpful bacteria — Your body contains many \nhelpful bacteria that aid in such things as digestion. Antibiotics kill these, \nand can cause symptoms such as an upset stomach, diarrhea, or vaginal \nyeast infection.\n•They can cause side effects — Some people develop allergies to\nantibiotics. Report any symptoms, such as an itchy rash, to your doctor.\n•Overuse can help the development of resistant bacteria — Figure 11.10\nshows how bacteria can build resistance against an antibiotic. Study this\nfigure and the accompanying caption.\nProtecting Yourself from Disease• MHR 205\nA.\nB.\nAntibiotics kill\nnon-resistant bacteria.\nA mutation allows some\nbacteria to survive and\nreproduce.\nA new strain of bacteria\nhas developed. The old\nantibiotic is unable to\nkill them.\nresistant bacterium\nbacterium\nsurvivor\nreproduces\nantibiotic\nFigure 11.10 When you take an antibiotic, it usually kills bacteria over a period of seven to 10 days. \nRegularly occurring mutations mean that some of the bacteria are immune to the antibiotic. These \nbacteria survive and reproduce, forming a new antibiotic-resistant strain of infection. Not taking all of \nthe antibiotic the doctor prescribes can increase the chance of bacteria becoming resistant. \nThe resistant bacteria are often called superbugs. When the superbugs reproduce, the new strain of\nthe disease begins to infect many people. People die from infections that used to be treatable because\nthe new superbugs are resistant to one — or sometimes many — antibiotics.\nEven if you are a healthy person who has never taken an antibiotic, you could become infected with a\nsuperbug from other people. That is why bacterial resistance poses such a threat. The best way you can help\navoid this is by using antibiotics only when necessary and following the doctor’s directions for their use.\nExplain how resistant\nbacteria develop and \nwhat you can do to help.\nSC2-11/Q  5/21/03  10:28 AM  Page 205","originalImage":"assets/textbook-page-38.jpg"},{"printed":206,"physical":39,"label":"206","image":"assets/reader-pages/textbook-page-39.jpg","text":"Use Antibiotics Safely\n•Ask questions— Ask your doctor or pharmacist about precautions to\ntake when using a medicine, and about any side effects. Before you take\ntwo or more medicines at the same time, ask if they can be taken\ntogether safely.\n•Read the label— Find out how and when to take medicine. Some\nmedicines must be taken with food; others on an empty stomach. Some\nmedicines cause sensitivity to the Sun. Also check the expiration date\nand discard any medication that has passed the expiry date.\n•Take drugs properly— Follow the directions on the label until you\nhave taken all of the medication. Not doing so may lead to the\ndevelopment of antibiotic-resistant bacteria.\nHandling Over-the-Counter Drugs\nIn most cases, over-the-counter drugs are considered safe to use. However,\nthere are risks if you treat yourself without professional advice.\nGenerally, you should not assume that you have a specific disease and choose\na medication to treat it. The same symptom can result from one of several\ndiseases, and you may be treating the wrong ailment. For this reason, avoid\nself-diagnosis unless you are dealing with a problem you have had before and\nhave exactly the same symptoms.\n206 MHR • Disease Defence and Human Health\nDrug reactions account\nfor one in five hospital\nadmissions. Nine out of\n10 patients do not take\nmedicines properly. For\nexample, combining\nmedicines may produce\neffects different from\nthose produced when \na medicine is taken\nalone, or it may produce\nside effects.\nFigure 11.11 Many different diseases have the same\nsymptoms. For this reason, it is best to check with a doctor\nor pharmacist before buying an over-the-counter drug. \nChoosing Over-the-Counter Drugs\nWhen you have a choice among several medications,\nread the labels carefully.\n•Find out what symptoms the medicine treats. If\nyou have a headache, look for something that\nrelieves headaches.\n•Read the warnings and list of side effects. Many\nmedications make you drowsy. If you must take\none of these, you may need to ask a friend to drive\nor postpone a date.\n•Use exactly the amount of medication prescribed,\nand use it for the recommended length of time.\nWhat information should you read on\nthe label of an over-the-counter drug?\nSC2-11/Q  5/21/03  10:28 AM  Page 206","originalImage":"assets/textbook-page-39.jpg"},{"printed":210,"physical":40,"label":"210","image":"assets/reader-pages/textbook-page-40.jpg","text":"C an you roll your tongue?\nAre your earlobes detached? Can\nyou bend back your thumb? These\nare just a few of the characteristics\nthat you may have inherited. In\nfact, millions of combinations of\ncharacteristics are passed from one\ngeneration of a family to the next.\nStudy the photograph of the extended\nfamily. What characteristics do you\nthink the grandparents passed to\nthe children?\nPeople can also inherit certain\ndisorders. In this chapter you will\nlearn more about heredity and some\ninherited disorders.\nRecently, scientists identified all of\nthe characteristics that make up human\nbeings. Now they are studying diseases\ncaused by alterations in genetic make-\nup. You will investigate some issues\nrelated to these advances in research.\nThe environment plays a\nsignificant role in human development\nand health. Exposure to environmental\nelements may cause changes in\ninherited characteristics. For example,\nwhat an expectant mother eats,\ndrinks, or breathes may affect her\nunborn child. You will investigate\nthe effects of environmental\nfactors on health.\nAs you learn about heredity and\nsee what a complex combination of\ntraits you have, you may decide to\ntrace some traits in your own family.\n210 MHR • Disease Defence and Human Health\nCHAPTERCHAPTER\nGenetics andGenetics and\n• What characteristics have\nbeen passed from one\ngeneration to another\nin your family?\n• What environmental\nfactors might affect the\ndevelopment of a fetus?\n• What determines whether\na baby will be a girl or\na boy?\n• How does overexposure\nto the Sun affect cells?\n• What is the Human\nGenome Project?\n12\nSC2-12/Q  5/21/03  10:34 AM  Page 210","originalImage":"assets/textbook-page-40.jpg"},{"printed":211,"physical":41,"label":"211","image":"assets/reader-pages/textbook-page-41.jpg","text":"Genetics and Health• MHR 211\nHealthHealth\nWhat You Will LearnYou Will LearnY\nIn this chapter you will learn:\n• how physical characteristics are inherited in humans\n• how chromosomes determine the sex of a child\n• how genetic information is organized in the cells of\nyour body\n• about human diseases that result from changes to\ngenetic make-up\n• about ethical and social issues related to genetic research\nWhy It Is Important\nSkills You Will Use\n• Some babies are born with disorders that could have\nbeen prevented. Identifying the risk factors that may\ncause preventable disorders can help you protect your\nhealth and the health of children born in the future.\nThis is important for both males and females, since\nboth provide genetic material to the fetus.\nIn this chapter you will:\n• use techniques to illustrate and interpret hereditary\ncharacteristics\n• predict the occurrence of some characteristics passed\nfrom parents to offspring \n• construct a model of how genetic information is\norganized in cells \n• investigate the effects of changes in genetic make-up\n• identify points of view about issues related to genetic\nresearch\nSC2-12/Q  5/21/03  10:34 AM  Page 211","originalImage":"assets/textbook-page-41.jpg"},{"printed":212,"physical":42,"label":"212","image":"assets/reader-pages/textbook-page-42.jpg","text":"Structure of DNA\n212 MHR • Disease Defence and Human Health\n12.1\nA\nC\nB\nD\nC G\nT A\nC G\nT A\nDraw a picture to show\nhow DNA is organized.\nFigure 12.1\nA. Your body contains about \n10 trillion cells.\nB. Each cell contains a nucleus\nwith chromosomes.\nC. Each chromosome consists\nof double-helix shaped\nmolecules of DNA. This\nchromosome has an identical\ncopy attached because the\ncell has just divided.\nD. DNA is divided into\nsegments called genes.\nThese control or determine\ninherited traits.\nPeople may have told you that you look like your mother or dad — or perhaps\na grandparent. Do you know how these characteristics get passed down to you? \nThe answer involves a branch of science called genetics. Genetics is the\nstudy of how characteristics or traits are passed from parents to offspring.\nTo understand how you ended up with the traits you did, think about how\nyour body is made up of systems, organs, tissues, and cells. The unique code for\nyour genetic make-up is stored in the nucleus of each one of these cells. Figure\n12.1 explains how your genetic information is organized. Study the four parts of\nthe diagram.\nThe Structure of DNA\nLook closely at how the DNA is organized in part D of Figure 12.1. Notice\nthat it appears as a twisted ladder. Look at the rungs on the ladder.\nChemical compounds called bases make up the rungs. A pair of bases forms\neach rung. One molecule of DNA contains about three billion base pairs.\nDifferent genes are made up of different arrangements of these base pairs.\nThe sequence of the base pairs determines the traits you inherit.\nSC2-12/Q  5/21/03  10:34 AM  Page 212","originalImage":"assets/textbook-page-42.jpg"},{"printed":213,"physical":43,"label":"213","image":"assets/reader-pages/textbook-page-43.jpg","text":"Chromosomes\nHuman body cells contain 46 chromosomes arranged in 23 pairs that hold\nall the genetic information. One chromosome of each pair comes from the\nmother and the other chromosome of each pair comes from the father.\nFigure 12.2 describes how scientists study chromosomes. First, they group\nthem into pairs, and then they organize them by size, beginning with the\nlongest pair. The sex chromosome pair is organized last. In humans, there are\ntwo kinds of sex chromosomes: X and Y. The Y chromosome is found only in\nmales. Females have XX chromosomes. Males have XY chromosomes.Genetics and Health• MHR 213\nThe DNA of all people\non Earth is 99.9 percent\nidentical. It is the\n0.1 percent difference\nthat makes each one\nof us unique.\nWhat chromosome\ncombination determines\nthe sex of human\noffspring? \nFigure 12.2 Scientists put a sample of white blood cells that are dividing under a microscope and\ntake a photograph. They use the photograph to make a chromosome map like the one shown here.\nNote that the chromosomes are grouped in numbered pairs according to their size and shape. \nFind the pair of sex chromosomes. How large is the X chromosome compared to the Y?\nDoes this map represent a male or a female? How do you know?\nSC2-12/Q  5/21/03  10:34 AM  Page 213","originalImage":"assets/textbook-page-43.jpg"},{"printed":216,"physical":44,"label":"216","image":"assets/reader-pages/textbook-page-44.jpg","text":"Inheritance and Genetics\nHalf of your genetic make-up comes from your mother and\nthe other half from your father. Then why don’t all brothers\nand sisters look alike? How do traits skip generations?\nThe answers to these questions have to do with\nheredity, which is the passing of characteristics from\nparents to offspring.\nDuring the mid-1800s, Gregor Mendel, an Austrian monk, experimented\nwith pea plants to show that traits do not happen by accident. He noticed that\npea plants vary in height. Some are tall, others short. He crossed tall and short\npea plants to see how height would be affected in the offspring.\nMendel recorded the traits of the offspring plants over several generations.\nFigure 12.3 summarizes what he discovered about the trait of tallness in pea\nplants. Study the pictures and read the captions to help you understand the\ndifference between dominant and recessive traits.\nDuring the Starting Point Activity on page 211, you surveyed what traits appear\nmost often in humans and which traits appear less often. Read the caption with\nFigure 12.3 and notice the definition for a dominant and a recessive traits. Go\nback to your survey and identify the traits that were dominant and recessive.\n216 MHR • Disease Defence and Human Health\n12.2\nWhat is heredity?\nA. tall parent + tall parent = pure tall plants\n• Mendel looked at the results of the crosses shown in A and B. He referred to the parent\nplants as purebreds. Purebreds have identical genes for each trait. In this case, the \nparents in A and B had identical genes for tallness.\nC. pure tall parent + pure short parent = hybrid tall plants\n• When Mendel crossed the pure tall plants with the pure short\nplants, the offspring were always tall. The short trait seemed to \ndisappear.\n• Mendel called tallness a dominant trait because it seemed to\ndominate the short trait.\n• He called shortness a recessive trait because it seemed\nto disappear.\n• Offspring of this cross are called hybrids. Hybrids carry one\ngene of each kind for each trait. In this case, they carry one \ngene of each kind for tallness.\nD. hybrid tall plant + hybrid tall plant = mix of tall and \nshort plants (3 tall, 1 short)\n• Mendel crossed hybrid tall plants with hybrid tall plants.\nHe was surprised to discover that sometimes shortness \nappeared in the offspring.\n• From these observations, Mendel concluded that\ntallness must be controlled by factors inherited from \nboth parents.\nB. short parent + short parent = pure short plants\n++\n++\nFigure 12.3\nSC2-12/Q  5/21/03  10:34 AM  Page 216","originalImage":"assets/textbook-page-44.jpg"},{"printed":217,"physical":45,"label":"217","image":"assets/reader-pages/textbook-page-45.jpg","text":"Recording Inherited Traits\nSince chromosomes come in pairs, genes for traits do too. Many traits are\ncontrolled by only one pair of genes, others by two or more pairs.\nFor traits controlled by one pair of genes, geneticists use two letters to\nrepresent the genotype or combination of genes.\n• Capital letters represent dominant genes. For example, the letter T could\nrepresent the dominant gene for tallness, which is the tall gene.\n• Lower case letter represent recessive genes. For example, the letter t could\nrepresent the recessive gene for tallness.\nDuring reproduction, chromosomes separate so that each sperm or egg cell\ngets only one chromosome of each kind. As a result, only one gene for each\ntrait is passed on to the offspring from each parent.\nPunnett Squares\nGeneticists use a Punnett square to predict the probability of offspring\ninheriting certain traits. Figure 12.5 shows the results of crosses in Figure 12.3.\nNote that:\n• the possible genes in the eggs from the female are across the top;\n• the possible genes in the sperm from the male are down the left side; and\n• the possible gene combinations of offspring are shown in the four squares.\nThere are four possible gene combinations in the offspring. Look at the offspring in Punnett \nsquares C and D. Mendel used results like these to show that recessive traits can skip generations.\nIn Punnett square C, shortness did not appear in the offspring because tallness is dominant. \nHowever, shortness reappeared in the next generation (Punnett square D). This occurred because \none of the offspring inherited two genes for shortness.\nGenetics and Health• MHR 217\nFemales have XX genotype. Males have XY genotype. Complete a Punnett square to \ndiscover the chances of giving birth to a male or female child.\nFigure 12.4 This lowland\ngorilla has no pigment or\nnatural colouring of its\nskin, eyes, or hair. Such\nan individual is called an\nalbino. Albinos have\ninherited two recessive\ngenes. They have two\ncopies of the gene for\nalbinism and no copy\nof the gene that makes\nnormal pigment.\nABCD\nTT\nTT TT\nTT TT\nT\nT\ntt\ntt tt\ntt tt\nTT\nTt Tt\nTt Tt\nt\nt\nt\nt\nTt\nTT Tt\nTt tt\nT\nt\nFigure 12.5 Describe the appearance of each offspring in A, B, C, and D.\nWhy were there no short plants in C, even though one plant was short?\nSC2-12/Q  5/21/03  10:34 AM  Page 217\nA type of scientist called a geneticist uses a tool called a family tree or pedigree to trace traits in a family. A \npedigree is a diagram that shows the history of a trait from generation to generation. Pedigrees show traits \nwith different characteristics, such as long eyelashes or short eyelashes, through many generations. Plant and \nanimal breeders use the information from pedigrees to increase the chances of breeding plants and animals \nwith only desirable traits.","originalImage":"assets/textbook-page-45.jpg"},{"printed":220,"physical":46,"label":"220","image":"assets/reader-pages/textbook-page-46.jpg","text":"Genetic Changes\nMost of the time the process of cell reproduction and copying genes works\nwell. Mistakes, however, can happen during reproduction when chromosomes\nare copied. In most cases, body cells recognize errors and fix them. In other\ncases, a cell’s repair mechanisms can fail. These mistakes are then passed from\ngeneration to generation. \nSuch changes in genetic information can result in an abnormal gene called \na mutation. Mutations can occur in several ways. Figure 12.7 shows how the \nchange in one of the base pairs of a gene can lead to sickle-cell anemia.\nExposure to environmental factors can also cause mutations. Environmental \nfactors that cause mutations are called mutagens. These include radiation; \nultraviolet light; and many chemicals, including PCBs, those in cigarettes, and \nalcohol and other drugs.\nMost of these errors do not pass from one generation to the next. There are\nexceptions. For example, children may pass on some effects from their mother’s\nexposure to radiation.\nInherited Genetic Disorders\nSometimes, a mutation may be helpful. For example, giraffes with a mutation \nfor a longer neck increase their ability to obtain food. Usually mutations result \nin genetic disorders, which result from alterations to the genes. For example, \nsickle cell anemia results from an abnormal form of hemoglobin. Hemoglobin \nis the substance in red blood cells that carries oxygen through the body. \nSomeone with sickle cell anemia has abnormal hemoglobin. This leads to poor \nresistance to infection and low levels of iron in the blood.\n220 MHR • Disease Defence and Human Health\n12.3\nExplain how inherited\nand environmental\nmutations can occur. C G\nT A\nT A\nC G\nA T\nT A\ngene A gene a\nsegment of gene for \nnormal hemoglobin\nsame segment \nafter mutation\nUse Punnett squares to determine the chances for each of the\nfollowing sets of parents having a child with sickle-cell anemia.\n(a) one parent carries the gene (Aa x AA)\n(b) both parents carry the gene (Aa x Aa)\n(c) one parent carries the gene and the other has the disease\n(Aa x aa)\nFor each set of parents, what is the chance of having a child\nwith sickle-cell anemia?\nFigure 12.7 Look at the pairs in gene A and gene a. How do they differ?\nGene A produces normal hemoglobin. Gene a produces defective\nhemoglobin which causes sickle-cell anemia.\nSC2-12/Q  5/21/03  10:34 AM  Page 220","originalImage":"assets/textbook-page-46.jpg"},{"printed":222,"physical":47,"label":"222","image":"assets/reader-pages/textbook-page-47.jpg","text":"Genetic Disorders Caused by Mutagens\nRadiation from X-ray machines and ultraviolet light \nin sunlight or tanning lamps can cause mutations. \nSuch radiation releases particles smaller than atoms \ninto cells and causes chromosomal changes. An \noverdose may cause cancer, skin burns, and other \nserious conditions.\nDoctors use radiation beneficially to treat\ndiseases such as cancer. They focus large doses of\nradiation on the cancer cells in an attempt to destroy\nthe cell nuclei. Damage to non-cancerous tissue is\nlimited by shielding the healthy tissue from radiation.\nThe amount of radiation is also carefully monitored.\nHuman embryos are particularly at risk from exposure\nto mutagens. Table 12.2 examines some dangerous\nchemicals and their effects on human embryos.\n222 MHR • Disease Defence and Human Health\nmutation\nmutagens\ngenetic disorders\nKey Terms\nFigure 12.8 Radiation alters the DNA in normal cells to form\ncancer cells. The cancer cells keep dividing and build up\nmasses of tissue called a tumour. \nMutagen Effect\nExposure to alcohol • low birth weight\n• Children born to mothers who consume • facial and joint abnormalities, small heads\nany alcohol during their pregnancy • heart defects\nmay suffer from a condition called • difficulties with learning, behaviour, and mental health\nfetal alcohol spectrum disorder (FASD).\nExposure to prescription and illegal drugs • premature births\n• Pregnant women should take • low birth weight\nprescription drugs only under a • drug addiction at birth\ndoctor’s care. Doctors who know • possible mental limitations\nthe woman is pregnant look for • possible birth defects\nmedications that do not harm the fetus.\nPCBs (polychlorinated biphenyls) • low birth weight\n• PCBs are a mixture of toxic chemicals • mild symptoms that often disappear with age: anemia,\npresent in the environment because liver conditions, skin rashes\nof improper disposal of wastes and • difficulties co-ordinating movement and problems with\nconsumer products. Some are linked to short-term memory that last several years\nvarious forms of cancer, including liver • delays in normal development\nand kidney cancer. • problems with immune system\nTable 12.1 Mutagens and Effects on Human Embryos\nCheck Your Understanding \n1. Briefly describe how a mutation might occur when chromosomes are\ncopied. Use a sketch if you wish.\n2. (a) What are mutagens?\n(b) Name one example of a mutagen and identify a genetic disorder that\nresults from exposure to it. \n3. Why is it important that pregnant women avoid consuming any amount of\nalcohol or taking any type of drug?\nName three mutagens\nthat harm human\nembryos and describe\nthe effect of each.\nSC2-12/Q  5/21/03  10:35 AM  Page 222","originalImage":"assets/textbook-page-47.jpg"},{"printed":223,"physical":48,"label":"223","image":"assets/reader-pages/textbook-page-48.jpg","text":"Issues in Genetic Research\nGenetics and Health• MHR 223\nIdentify at least three\nbenefits of genetic\nresearch.\n12.4\nMany people believe that the Human Genome Project is the most important\nscientific effort that humans have ever attempted. All of the genes found in a\ncomplete set of chromosomes — the set of genetic instructions that makes you\nwhat you are — form a genome. Scientists working on the genome project have\nmapped where each gene belongs on 46 human chromosomes. \nThis kind of information has many benefits. One benefit is that scientists can\nuse this knowledge to transfer genes from one organism to another to give one\norganism the traits of another. Transferring genes from one organism or type\nof organism to another is referred to as genetic engineering. For example,\nscientists have inserted a spider gene into goats. The goat then produces a\nprotein identical to the protein found in spider silk. The protein is removed\nfrom goat milk to produce silk fibres used to make bulletproof vests.\nBenefit Examples\n• identifying the source of thousands of genetic • If scientists can identify the gene that causes a\ndisorders (such as colourblindness, disease such as epilepsy, they may be able to\nhemophilia, or cystic fibrosis) alter that gene and thus cure the condition.\n• developing new drugs and treatments • Researchers identified the human DNA\nresponsible for insulin production. They\ninserted that DNA into bacteria. Each time the\nbacteria cells divide, the human insulin gene\nis duplicated. The technology produces an\ninexpensive supply of insulin for people who\nhave diabetes.\n• helping people make lifestyle choices • By studying a family’s genes, researchers can\ndetermine which diseases people with that\ngenetic make-up are most likely to develop.\nSomeone with a family history of heart disease,\nfor example, might take special care to eat a\nlow fat diet and exercise regularly.\nThis pregnant woman is having an amniocentesis. This procedure is\nused to determine the chromosomal make-up of a fetus. The test\nshows whether a fetus may have a genetic abnormality. Some\nparents use such tests to decide whether or not to continue with a\npregnancy. This picture shows ultrasound being used to locate the\nfetus. Doctors need to\nknow where the fetus \nis so that they do not\ndamage it when they\ninsert a large hollow\nneedle to withdraw\namniotic fluid.\nFigure 12.9\nSomeone who suspects they have a genetic\ndisorder such as a genetic disposition toward\ncystic fibrosis or breast cancer, may use\ngenetic research to check their chances of\ndeveloping a specific disease. They may\ncontact a genetic counsellor, who gathers\nmedical information about the individual’s\nfamily and analyzes the person’s chromosomes\nto help predict the chances of the person\ndeveloping a particular disorder.\nTable 12.3 outlines some of the benefits of\nthese advances in genetic research and\nengineering. But there are also concerns,\nwhich you will learn about on the next page.\nTable 12.2 Benefits of Genetic Research\nSC2-12/Q  5/21/03  10:35 AM  Page 223","originalImage":"assets/textbook-page-48.jpg"},{"printed":225,"physical":49,"label":"225","image":"assets/reader-pages/textbook-page-49.jpg","text":"Concerns about Genetic Research\nWhat would happen if all parents decided to have only male — or only female —\nchildren? This is the kind of question people ask when discussing genetic research.\nSuch questions are ethical questions. They consider what is right or wrong.\nSome ethical concerns deal with questions about who should have access to\ngenetic information. For example, might employers ask for genetic information\nabout employees? How might they use it?\nConsider the ethical issues below, and then identify the ethical concerns\nraised in Figures 12.10 and 12.11.\n• Who has a right to genetic data that provide information about your\nchances of developing various conditions? What might happen if health\ninsurance companies had access to everyone’s genetic make-up? Could\nthey refuse to provide some people with health insurance? What might\nhappen if an employer found out that an employee had genes that often\nresult in substance abuse? Might the employee be fired?\n• Do you want to know genetic information that may tell you of a terrible\ndisease you are likely to develop but unable to do anything about? How\nmight knowing this affect the way you live? Might you suffer from\ndepression or adopt behaviours that put you more at risk?\nCheck Your Understanding \n1. How might amniocentesis create an ethical problem for some people?\n2. Working with a partner, list three pros\nand cons of using advances in genetics.\nDevelop a chart similar to the one shown\nhere to help you organize your information.\n3. Choose one ethical dilemma related to genetic research. Work with a\npartner to discuss the points of view on this dilemma. Consider how you\nfeel about the issue. Express your point of view orally.\nGenetics and Health• MHR 225\ngenetic engineering\namniocentesis\nKey Terms\nIdentify two concerns\nabout advances in\ngenetic research.\nFigure 12.10 Scientists do\nnot know all the risks of new\ntechnologies. For example,\nDolly, the world’s first cloned\nsheep, developed arthritis\nbefore she was six years old.\nResearchers do not know\nwhether Dolly’s arthritis was\ncaused by environmental\nfactors or genetic factors. \nFigure 12.11 Many people\nquestion the ethics of using\na human embryo such as\nthe one shown here to\nharvest stem cells. Stem\ncells are unspecialized cells\nthat are the building blocks\nfor many body parts.\nResearchers hope to use\nstem cells to treat a variety\nof diseases, including\nAlzheimer’s disease, and\ngrow new organs. Is it right\nto kill an embryo in order\nto do this? \nPro Con\nSC2-12/Q  5/21/03  10:35 AM  Page 225","originalImage":"assets/textbook-page-49.jpg"}]}],"bookQuestions":[{"id":"s24-c-textbook-p162-question-page","title":"Original questions · p. 162","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":162,"physicalPage":6,"topic":"02","image":"assets/reader-pages/textbook-page-06.jpg","originalText":"Protists\nProtists are single-celled organisms that share some characteristics\nwith both animals and plants. Two common protists are the\namoeba and the paramecium.\nSome protists cause serious diseases such as malaria, African\nsleeping sickness, and amoebic dysentery. Malaria is spread by\nmosquitoes, sleeping sickness by Tsetse flies. Amoeba can be\npicked up from contaminated water or food.\nA protist called Giardia lives in the intestines of infected\nhumans or animals. Gi ardia may be found in water, food, soil, or\nsurfaces that have been contaminated with the feces from infected\nhumans or animals. You can become infected after you drink the \ncontaminated water.\nTo prevent getting Giardia, drink only safe water. \nFungi\nFungi include molds, yeasts, and \nmushrooms. They cannot make \ntheir own food by photosynthesis. \nSome fungi are parasites and can \nlive only on host organisms. Fungi, \nsuch as mushrooms taste great on \npizza or salad. Others cause disease. \nTwo examples of this are athlete’s \nfoot and ringworm, two fungi that \nlive on the body.\nCheck Your Understanding\n1. Describe three factors that cause disease. Provide an example for each one.\n2. What is a pathogen? Give three examples of pathogens.\n3. Explain how viruses such as the AIDS virus spread.\n4. What might happen to the bacteria in a hamburger you left on the counter\nfor a few hours? Explain why.\n162 MHR • Disease Defence and Human Health\nFigure 9.5 Giardia is the\nmost common protist in the\nworld. In Canada, it is also\ncalled beaver fever because\nbeavers often carry and\nspread the protist.\nFigure 9.6 Athlete’s foot is caused by a fungus \nthat lives on the skin. It breeds under warm, moist\nconditions such as those found in sweaty socks and\nshoes. To prevent it, wear leather shoes and sandals\nso your feet can “breathe.” Wear sandals or slippers\nin places such as change rooms with showers.\npasteurization\ndisease\nmicrobes\npathogens\nbacteria\nviruses\nfungi\nprotist\nparasites\nKey Terms\nHow do protists spread?\nSC2-09/Q  5/21/03  10:11 AM  Page 162"},{"id":"s24-c-textbook-p164-question-page","title":"Original questions · p. 164","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":164,"physicalPage":8,"topic":"03","image":"assets/reader-pages/textbook-page-08.jpg","originalText":"The Importance of a Clean Environment \nDiseases can be spread by air, water, food, and contact. Why aren’t we all sick\nmost of the time?\nThe answer has to do with our environment. Clean environments reduce the\nnumber of viruses and bacteria present. As a result, there are fewer pathogens\nto make us sick.\nSome environments have to be super clean. There are so many pathogens \nassociated with human feces that bathrooms have to be sanitary. This means \nmaintaining clean, germ-free conditions to help prevent disease. This form of \ncleaning uses special cleaners such as chlorine and anti-bacterial soaps to eliminate \nmost bacteria and viruses. Sanitary cleaning and handling practices should be used \nin all environments where there is a chance of high numbers of bacteria and viruses.\nPeople who work with food must wear protective gloves when they are handling\nfood, to avoid spreading pathogens to people who will eat the food they serve.\nAnother reason they need to handle food carefully is to prevent food poisoning.\nFood poisoning results from eating food that is infected with harmful micro-\norganisms. Such food can make you very ill. In some cases, it can be fatal.\n164 MHR • Disease Defence and Human Health\nFoods containing  \nchicken may beco me \ncontaminated with \nbacteria if they  are not \nhandled properly. To \nprevent salmonell osis, \nchicken needs to  be\nkept hot or cooled\nrapidly after it is cooked\nthoroughly. Chicken not\neaten right away should\nbe refrigerated.\nHow does a clean\nenvironment protect\nyou from disease?\nSC2-09/Q  5/21/03  10:11 AM  Page 164"},{"id":"s24-c-textbook-p165-question-page","title":"Original questions · p. 165","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":165,"physicalPage":9,"topic":"03","image":"assets/reader-pages/textbook-page-09.jpg","originalText":"How Do You Get a Non-communicable Disease?\nCommunicable diseases are caused by bacteria and viruses spread by air, water,\nfood, and contact. \nMany non-communicable diseases are the result of bad environmental\nconditions, poor diets, unhealthy lifestyles, and genetics.\nCheck the figures that follow to see how each of these can result in disease.\nDisease• MHR 165\nFigure 9.7 Where do you \nfind the most polluted air?\nWhether or not you\n \nsmoke, it is probably in \nyour home. This is \nbecause it is difficult to \ncirculate fresh air inside \na building. Exposure \nto polluted air (from \ncigarettes, for example) \ncauses diseases such as \nemphysema. Emphysema \nis \na lung condition in \nwhich breathing becomes \ndifficult. \nFigure 9.10 Genetics refers to\nthe characteristics you inherit\nfrom your birth parents.\nGenetic factors are associated\nwith diseases such as cystic\nfibrosis (CF), which damages\nthe respiratory and digestive\nsystems. Exercise may benefit\npeople with CF by improving\ntheir strength and endurance. \nFigure 9.8 If you eat this\nmeal once in a while, don’t\nworry! If you eat this way\nregularly, however, you\nhave a poor diet. People\nwith poor diets often \nsuffer from high levels \nof sickness. For example, \na diet high in fat and\ncholesterol may cause\nheart disease. In heart\ndisease, blood flow to \nthe arteries supplying \nthe heart becomes more\nand more restricted.\nCheck Your Understanding \n1. Define “communicable disease.” List three examples.\n2. Define “non-communicable disease.” List three examples.\n3. Make a table with three columns.\n• In the first column, list at least five diseases you or your family members\nhave or have had.\n• In the second column, identify each disease as communicable or non-\ncommunicable.\n• In the third column, list the effects of each disease on health.\nFigure 9.9 Screen time may be important to you. But \nyou need to balance the amount of down time with active\nexercise. Lack of exercise can result in obesity. People who\nare 10 percent over the ideal body weight for their height\nand bone structure are obese. Being obese strains your\nheart’s ability to function and increases your chances of\ndeveloping Type II diabetes. \ncommunicable\nnon-communicable\nbotulism\nsalmonellosis\nsanitary\nKey Terms\nSC2-09/Q  5/21/03  10:11 AM  Page 165"},{"id":"s24-c-textbook-p167-question-page","title":"Original questions · p. 167","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":167,"physicalPage":11,"topic":"03","image":"assets/reader-pages/textbook-page-11.jpg","originalText":"Table 9.2 Risk Factors and Disease\nDisease• MHR 167\nRisk Factor Possible Disease Source of Risk\nnot eating properly obesity, diabetes, heart disease, cancer, tuberculosis economic, social\ndrinking unclean water diarrhea, parasites, E. coli economic\nnot having a toilet diarrhea, tuberculosis, parasites economic\nnot practising personal hygiene tuberculosis, food poisoning economic, social\nsuch as washing hands frequently\nhaving sex AIDS and STDs social\nsmoking tobacco emphysema, bronchitis, and other respiratory conditions; social\narteriosclerosis and other circulatory diseases; cancer\nconsuming excess alcohol liver disease, dementia, malnutrition social\nCheck Your Understanding \n1. What is poverty?\n2. Use Table 9.2 to identify what diseases you may be at risk of getting.\nExplain how you could reduce your risk of getting each one.\n3. Defend the statement, “Access to safe water reflects the health of a\ncountry’s people.”\n4.\nWhat type of disease kills most people in poor countries? in rich countries?\nFigure 9.12 Natural disasters, like this flood in Badger, Newfoundl and, in 2003, can result in sanitation \nproblems.  Once the ice thaws, water run-o ff provides breeding grounds for bacteria and viruses. As a \nresult, victims may have limited access to clean water. Large numbers of injured people may overload \nmedical facilities. People may get infections from the unsanitary conditions.\nIn poor countries, all of these problems are worse. In addition, food supplies may not be handled \nor stored properly. As a result, they may become contaminated.\npoverty\nKey Terms\nSC2-09/Q  5/21/03  10:11 AM  Page 167"},{"id":"s24-c-textbook-p169-question-page","title":"Original questions · p. 169","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":169,"physicalPage":13,"topic":"04","image":"assets/reader-pages/textbook-page-13.jpg","originalText":"Let’s Go \non a Picnic! \nThink About It \nUse what you have learned about safe food handling\npractices to plan a picnic for friends on a hot,\nsunny day. \nWhat to Do \n1Use a chart to organize the following information. \n•In the first column, list each of the foods on\nthe menu: chicken wraps, coleslaw, home-\ncanned black bean salsa, coconut cream pie,\nlemonade, fresh strawberries.\n•In the second column, describe how it\nshould be prepared.\n•In the third column, describe how it should\nbe kept safe from contamination.\n•In the fourth column, identify what form of\nfood poisoning might occur if it is handled\nimproperly.\nAnalyze \n1. (a)If the canned salsa is two years old and the\nseal is broken, what type of illness might\nthe picnickers get? \n(b)What would the symptoms be? \n2.\nWhat advice would you give to a friend who \nwanted to eat potato salad left on a picnic \ntable for several hours?\nExtend Your Skills \n3.Describe your favourite meal. For each food, list\nthe steps you need to follow to keep it safe to\neat. Include steps during and after preparation.\n4.The picnickers decide to help clean up. If\nthere is a choice between dishcloths and paper\ntowels, which would you recommend using?\nExplain why.\nDisease• MHR 169\n9–B9–B\nConsider the foods that have to be kept in a refrigerator. List 10\nor more food products that need to be refrigerated to slow\ndown the rate of food spoilage.\nSKILLCHECK\nInitiating and Planning\n Communication and Teamwork\nInitiating and Planning\nPerforming and Recording\nAnalyzing and Interpreting\n Communication and Teamwork\nThe glass dome over the salad bar is actually a sneeze\nguard to keep bacteria out of salads. \nFigure 9.13\nSC2-09/Q  5/21/03  10:12 AM  Page 169"},{"id":"s24-c-textbook-p170-question-page","title":"Original questions · p. 170","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":170,"physicalPage":14,"topic":"05","image":"assets/reader-pages/textbook-page-14.jpg","originalText":"Keeping Hospitals Healthy\nTwo hundred years ago, people expected to die when \nthey went \nto the hospital. Hospitals were so unsanitary \nthat patients often picked up diseases in the hospital. \nToday, this is less common because of the work of \nscientists such as Florence Nightingale, Joseph Lister, \nand Robert Koch.\nIn the 1800s, Florence Nightingale worked in a military \nhospital in Turkey. She reduced the death rate by making \nsure the hospital and patients were kept clean, improving \nwater quality, and bandaging wounds to prevent infections \nfrom spreading to other patients.\nAround the same time, an English surgeon named \nJoseph \nLister realized that many patients died of infections \nfollowing surgery. He began spraying carbolic acid on \npatient wounds and into the air of operating theatres. \nCarbolic \nacid kills pathogens on surfaces and on skin.\nRobert Koch discovered that hot steam was effective in \nkilling pathogens. He began using steam to destroy living \norganisms. This process is called\n sterilization.\n170 MHR • Disease Defence and Human Health\nFigure 9.14 Florence Nightingale \nWhat is the purpose of\nsterilization?\nAseptic Methods\nModern medicine uses many techniques to keep hospital rooms  \nand equipment aseptic or free of pathogens. Aseptic practices \ninclude: \n•using sterile bandages, instruments, linens, masks, and\nclothing during surgery;\n•scrubbing all exposed skin of the surgeon before and after\nsurgery;\n•having surgical staff wear rubber gloves to prevent the\nspread of pathogens that might hide under fingernails.\nIn addition, antiseptics are used on people to disinfect the skin.\nSuch antiseptics include iodine solution and alcohol.\nDisinfectants are used on objects and surfaces to sterilize them. \nSome common disinfectants include iodine, chlorine, bleach, and \nantibacterial soaps.\nSC2-09/Q  5/21/03  10:12 AM  Page 170"},{"id":"s24-c-textbook-p180-question-page","title":"Original questions · p. 180","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":180,"physicalPage":21,"topic":"07","image":"assets/reader-pages/textbook-page-21.jpg","originalText":"The Beginning of Public Health\nImagine living during the bubonic plague pandemic, \nwhen people \ndid not know what caused disease. \nImagine how frightened you would be.\nAt first, nothing was done to kill the rats that \noriginally spread the disease. In addition, people \ndumped human waste in the streets. After some \npeople began to understand that there might be a \nconnection between sanitation and disease, city \nofficials ordered streets to be cleaned and \nquarantined sick people in special facilities.\nAs people began to see the results of these kinds of \nmeasures, they became more interested in working \ntogether to develop healthy communities. This is \nreferred to as public health.\nGradually, the government got involved in caring for public health. In \nEngland, “The Year of the Great Stink” helped speed the development of these \nlaws. People who dumped waste and sewage in the Thames River were fined. \nEven though the new laws were not very well enforced, they were the beginnings \nof the public health system we have today.\n180 MHR • Disease Defence and Human Health\nFigure 10.4 Sanitary public toilets are not available everywhere\naround the world. Some countries use a cesspit, which is like an\nopen hole. When the cesspit becomes full, urine and feces slop\nover the sides and could run into the street, spreading any \ndisease pathogens that are present. \nCheck Your Understanding \n1. When does an epidemic become a pandemic?\n2. Make a list of the impact of pandemic diseases on society.\n3. List three pandemic diseases. Identify the social conditions that contributed\nto the spread of each one.\n4.With a partner, use the Internet to research one of the following epidemic \ndiseases: smallpox, cholera, typhoid fever, diphtheria, whooping cough. \nDevelop a short presentation that mentions:\n• how it spreads\n• details about the disease\n• its impact on society\npandemics\nepidemics\nquarantine\npublic health\nKey Terms\nSC2-10/Q  5/21/03  10:17 AM  Page 180"},{"id":"s24-c-textbook-p183-question-page","title":"Original questions · p. 183","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":183,"physicalPage":24,"topic":"07","image":"assets/reader-pages/textbook-page-24.jpg","originalText":"The Choice Is Yours\nThese are just some of the programs developed to decrease \nthe spread of disease and protect human health. The fact \nthat you are studying this in school suggests that public \nhealth authorities consider educating people about health \nto be very important.\nThe next link in the chain is you. Are you concerned enough\nabout your health to learn the many ways you can stay healthy?\nDo you care enough to maintain high standards of personal\nhygiene? When you get sick, are you willing to make sure \nthat you do not spread the disease to others? Do you take time\nto learn how to protect your own and others’ health and safety\nby taking training in first aid, swimming, lifesaving, or\nbabysitter’s training?\nSociety’s Response to Disease• MHR 183\nFigure 10.9 Education campaigns reduce the \nnumber of illnesses spread by poor food \nhandling. The campaign promotes four points: \n•Clean — wash hands and surfaces often\n•Cook — cook to proper temperature\n•Separate — do not cross-contaminate (for\nexample, keep separate cutting boards for \nmeats and vegetables)\n•Chill — refrigerate promptly\nFood Safety\n•Health authorities use newspapers, \nradio, pamphlets, brochures, and the \nInternet to promote food safety \nawareness. Food inspectors check \nthat workers in restaurants, food \ncompanies, and meat packing plants \nhandle food safely.\nCheck Your Understanding \n1. In your own words, explain the role of public health in Canada.\n2. Why is chlorine used to treat swimming pools and drinking water?\n3. (a) How do high standards of personal hygiene affect individuals?\n(b) How do such standards affect the community?\n4. Describe three local public health programs. How does each one protect\ncommunity health?\n.\nvaccinations\nKey Terms\nSC2-10/Q  5/21/03  10:17 AM  Page 183"},{"id":"s24-c-textbook-p184-question-page","title":"Original questions · p. 184","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":184,"physicalPage":25,"topic":"08","image":"assets/reader-pages/textbook-page-25.jpg","originalText":"Public Health and You\nVaccinations have reduced the number of people who die from communicable\ndiseases. For example, smallpox has killed millions of people around the world.\nToday, the smallpox virus exists only in laboratories. Vaccination against\nsmallpox is no longer recommended.\nDoes this mean that communicable diseases are no longer a serious problem?\nShould you just ignore public health guidelines?\nThe answer is no. There are many reasons for keeping an eye on public\nhealth guidelines.\nProtecting Health\nDiseases are not going away. In fact, many old diseases that were thought to \nhave \ndisappeared are resurfacing. These include polio and drug-resistant \nvariations of \ntuberculosis. New diseases, such as AIDS and SARS, are also \nemerging\n. Public health guidelines help to protect you from these and other \ndiseases. T\nable 10.1 explains how.\nTable 10.1 Factors that spread disease and Public Health Guidelines\n184 MHR • Disease Defence and Human Health\nConcern Public Health Guidelines\n• overcrowded conditions • Good personal hygiene reduces the spread of pathogens.\nFactor \npopulation growth and \novercrowding increase the chances of being • Treating and disposing of wastes also reduces their spread.\nexposed to pathogens\nmigration • diseases may be carried from • Disease monitoring keeps an eye on the level of disease.\ncountry to country or from rural • When levels are high, emergency response plans may prevent migration.\ncommunities to cities • Travellers and their belongings are disinfected to prevent the spread of\npathogens.\nlifestyle • people eat out • Restaurant inspections ensure food-handling practices are safe and\neating areas and utensils are kept sanitary.\ntravel • increased exposure to disease • T ravellers receive special vaccinations before travelling to some countries.\n(for example, eating improperly • Travellers receive brochures explaining how to protect themselves from\nprepared foods, using unsanitary pathogens in food and water.\npublic washrooms)\nfood supply • food comes from many • Food inspectors test foods for pathogens.\ncountries\n• food may harbour pathogens\n• sexual contact results in • STD awareness programs provide the facts.sexual activity and \nchildbirth spread of sexually transmitted • Prenatal nutrition programs teach mothers proper nutrition.\ndiseases (STDs) • Awareness education programs for fetal alcohol spectrum disorder reduce\nunderweight babies, the number of mothers who drink during pregnancy.\n• unhealthy mothers number of mothers who drink during pregnancy.\n10.3\nGive three reasons why\npublic health guidelines\nare necessary.\nSC2-10/Q  6/9/04  10:52 AM  Page 184"},{"id":"s24-c-textbook-p189-question-page","title":"Original questions · p. 189","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":189,"physicalPage":28,"topic":"08","image":"assets/reader-pages/textbook-page-28.jpg","originalText":"How Important Are Your Personal Actions?\nProper hand washing is only one aspect of personal health.\nYou have other important choices to make. Consider these.\n1. Protect your own health — take care of your personal\nhygiene; get vaccinations; keep informed about health\nadvisories\n2. Make wise lifestyle choices — exercise regularly; eat a\nwell-balanced diet; avoid smoking, alcohol, and non-\nprescription drugs; avoid sexual contact\n3. Adopt safer practices — wash your hands often; wear bike\nhelmets and seat belts; when you become sexually active,\npractise safe sex\nYour choices — wise or otherwise —\nwill affect the people around you.\nSociety’s Response to Disease• MHR 189\nFigure 10.17 How does\nwashing your hands protect\nothers from disease? \nHow do personal actions contribute to\nthe health of your community?\nCheck Your Understanding \n1. List five factors that account for the spread of communicable disease.\n2. Do you think it is important to have public health guidelines? Use\nexamples to help you explain why or why not.\n3. Defend the statement, “An ounce of prevention is worth a pound of cure.”\n4. What are three steps you can take to protect your own health? Provide a\nspecific example of each.\nSC2-10/Q  5/21/03  10:17 AM  Page 189"},{"id":"s24-c-textbook-p206-question-page","title":"Original questions · p. 206","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":206,"physicalPage":39,"topic":"12","image":"assets/reader-pages/textbook-page-39.jpg","originalText":"Use Antibiotics Safely\n•Ask questions— Ask your doctor or pharmacist about precautions to\ntake when using a medicine, and about any side effects. Before you take\ntwo or more medicines at the same time, ask if they can be taken\ntogether safely.\n•Read the label— Find out how and when to take medicine. Some\nmedicines must be taken with food; others on an empty stomach. Some\nmedicines cause sensitivity to the Sun. Also check the expiration date\nand discard any medication that has passed the expiry date.\n•Take drugs properly— Follow the directions on the label until you\nhave taken all of the medication. Not doing so may lead to the\ndevelopment of antibiotic-resistant bacteria.\nHandling Over-the-Counter Drugs\nIn most cases, over-the-counter drugs are considered safe to use. However,\nthere are risks if you treat yourself without professional advice.\nGenerally, you should not assume that you have a specific disease and choose\na medication to treat it. The same symptom can result from one of several\ndiseases, and you may be treating the wrong ailment. For this reason, avoid\nself-diagnosis unless you are dealing with a problem you have had before and\nhave exactly the same symptoms.\n206 MHR • Disease Defence and Human Health\nDrug reactions account\nfor one in five hospital\nadmissions. Nine out of\n10 patients do not take\nmedicines properly. For\nexample, combining\nmedicines may produce\neffects different from\nthose produced when \na medicine is taken\nalone, or it may produce\nside effects.\nFigure 11.11 Many different diseases have the same\nsymptoms. For this reason, it is best to check with a doctor\nor pharmacist before buying an over-the-counter drug. \nChoosing Over-the-Counter Drugs\nWhen you have a choice among several medications,\nread the labels carefully.\n•Find out what symptoms the medicine treats. If\nyou have a headache, look for something that\nrelieves headaches.\n•Read the warnings and list of side effects. Many\nmedications make you drowsy. If you must take\none of these, you may need to ask a friend to drive\nor postpone a date.\n•Use exactly the amount of medication prescribed,\nand use it for the recommended length of time.\nWhat information should you read on\nthe label of an over-the-counter drug?\nSC2-11/Q  5/21/03  10:28 AM  Page 206"},{"id":"s24-c-textbook-p222-question-page","title":"Original questions · p. 222","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":222,"physicalPage":47,"topic":"16","image":"assets/reader-pages/textbook-page-47.jpg","originalText":"Genetic Disorders Caused by Mutagens\nRadiation from X-ray machines and ultraviolet light \nin sunlight or tanning lamps can cause mutations. \nSuch radiation releases particles smaller than atoms \ninto cells and causes chromosomal changes. An \noverdose may cause cancer, skin burns, and other \nserious conditions.\nDoctors use radiation beneficially to treat\ndiseases such as cancer. They focus large doses of\nradiation on the cancer cells in an attempt to destroy\nthe cell nuclei. Damage to non-cancerous tissue is\nlimited by shielding the healthy tissue from radiation.\nThe amount of radiation is also carefully monitored.\nHuman embryos are particularly at risk from exposure\nto mutagens. Table 12.2 examines some dangerous\nchemicals and their effects on human embryos.\n222 MHR • Disease Defence and Human Health\nmutation\nmutagens\ngenetic disorders\nKey Terms\nFigure 12.8 Radiation alters the DNA in normal cells to form\ncancer cells. The cancer cells keep dividing and build up\nmasses of tissue called a tumour. \nMutagen Effect\nExposure to alcohol • low birth weight\n• Children born to mothers who consume • facial and joint abnormalities, small heads\nany alcohol during their pregnancy • heart defects\nmay suffer from a condition called • difficulties with learning, behaviour, and mental health\nfetal alcohol spectrum disorder (FASD).\nExposure to prescription and illegal drugs • premature births\n• Pregnant women should take • low birth weight\nprescription drugs only under a • drug addiction at birth\ndoctor’s care. Doctors who know • possible mental limitations\nthe woman is pregnant look for • possible birth defects\nmedications that do not harm the fetus.\nPCBs (polychlorinated biphenyls) • low birth weight\n• PCBs are a mixture of toxic chemicals • mild symptoms that often disappear with age: anemia,\npresent in the environment because liver conditions, skin rashes\nof improper disposal of wastes and • difficulties co-ordinating movement and problems with\nconsumer products. Some are linked to short-term memory that last several years\nvarious forms of cancer, including liver • delays in normal development\nand kidney cancer. • problems with immune system\nTable 12.1 Mutagens and Effects on Human Embryos\nCheck Your Understanding \n1. Briefly describe how a mutation might occur when chromosomes are\ncopied. Use a sketch if you wish.\n2. (a) What are mutagens?\n(b) Name one example of a mutagen and identify a genetic disorder that\nresults from exposure to it. \n3. Why is it important that pregnant women avoid consuming any amount of\nalcohol or taking any type of drug?\nName three mutagens\nthat harm human\nembryos and describe\nthe effect of each.\nSC2-12/Q  5/21/03  10:35 AM  Page 222"},{"id":"s24-c-textbook-p225-question-page","title":"Original questions · p. 225","prompt":"Answer the original question(s) on the displayed textbook page. Keep their printed numbers and lettered parts; use the surrounding text and figures.","resourceId":"s24-c-textbook","printedPage":225,"physicalPage":49,"topic":"17","image":"assets/reader-pages/textbook-page-49.jpg","originalText":"Concerns about Genetic Research\nWhat would happen if all parents decided to have only male — or only female —\nchildren? This is the kind of question people ask when discussing genetic research.\nSuch questions are ethical questions. They consider what is right or wrong.\nSome ethical concerns deal with questions about who should have access to\ngenetic information. For example, might employers ask for genetic information\nabout employees? How might they use it?\nConsider the ethical issues below, and then identify the ethical concerns\nraised in Figures 12.10 and 12.11.\n• Who has a right to genetic data that provide information about your\nchances of developing various conditions? What might happen if health\ninsurance companies had access to everyone’s genetic make-up? Could\nthey refuse to provide some people with health insurance? What might\nhappen if an employer found out that an employee had genes that often\nresult in substance abuse? Might the employee be fired?\n• Do you want to know genetic information that may tell you of a terrible\ndisease you are likely to develop but unable to do anything about? How\nmight knowing this affect the way you live? Might you suffer from\ndepression or adopt behaviours that put you more at risk?\nCheck Your Understanding \n1. How might amniocentesis create an ethical problem for some people?\n2. Working with a partner, list three pros\nand cons of using advances in genetics.\nDevelop a chart similar to the one shown\nhere to help you organize your information.\n3. Choose one ethical dilemma related to genetic research. Work with a\npartner to discuss the points of view on this dilemma. Consider how you\nfeel about the issue. Express your point of view orally.\nGenetics and Health• MHR 225\ngenetic engineering\namniocentesis\nKey Terms\nIdentify two concerns\nabout advances in\ngenetic research.\nFigure 12.10 Scientists do\nnot know all the risks of new\ntechnologies. For example,\nDolly, the world’s first cloned\nsheep, developed arthritis\nbefore she was six years old.\nResearchers do not know\nwhether Dolly’s arthritis was\ncaused by environmental\nfactors or genetic factors. \nFigure 12.11 Many people\nquestion the ethics of using\na human embryo such as\nthe one shown here to\nharvest stem cells. Stem\ncells are unspecialized cells\nthat are the building blocks\nfor many body parts.\nResearchers hope to use\nstem cells to treat a variety\nof diseases, including\nAlzheimer’s disease, and\ngrow new organs. Is it right\nto kill an embryo in order\nto do this? \nPro Con\nSC2-12/Q  5/21/03  10:35 AM  Page 225"}],"labeling":[{"id":"s24-c-label-transmission","title":"Trace an infection pathway","prompt":"Match source, exit, transfer and entry in the infection pathway.","image":"assets/transmission-diagram.svg","topic":"02","values":[{"letter":"A","value":"Infected source","answer":"source"},{"letter":"B","value":"Exit route","answer":"exit"},{"letter":"C","value":"Transfer route","answer":"transfer"},{"letter":"D","value":"Entry route","answer":"entry"}],"options":[{"id":"source","text":"Infected source"},{"id":"exit","text":"Exit route"},{"id":"transfer","text":"Transfer route"},{"id":"entry","text":"Entry route"}],"visualDescription":"Match source, exit, transfer and entry in the infection pathway. Four labeled positions A through D are shown in reading order."},{"id":"s24-c-label-water","title":"Trace a community water safeguard","prompt":"Match intake, treatment, monitoring and household delivery.","image":"assets/water-diagram.svg","topic":"07","values":[{"letter":"A","value":"Water intake","answer":"intake"},{"letter":"B","value":"Treatment","answer":"treatment"},{"letter":"C","value":"Monitoring","answer":"monitor"},{"letter":"D","value":"Household tap","answer":"delivery"}],"options":[{"id":"intake","text":"Water intake"},{"id":"treatment","text":"Treatment"},{"id":"monitor","text":"Monitoring"},{"id":"delivery","text":"Household tap"}],"visualDescription":"Match intake, treatment, monitoring and household delivery. Four labeled positions A through D are shown in reading order."},{"id":"s24-c-label-immune","title":"Trace a targeted immune response","prompt":"Match the entering antigen, recognition, response and memory.","image":"assets/immune-diagram.svg","topic":"10","values":[{"letter":"A","value":"Antigen","answer":"antigen"},{"letter":"B","value":"Recognition","answer":"recognition"},{"letter":"C","value":"Response","answer":"response"},{"letter":"D","value":"Memory","answer":"memory"}],"options":[{"id":"antigen","text":"Antigen"},{"id":"recognition","text":"Recognition"},{"id":"response","text":"Response"},{"id":"memory","text":"Memory"}],"visualDescription":"Match the entering antigen, recognition, response and memory. Four labeled positions A through D are shown in reading order."},{"id":"s24-c-label-punnett","title":"Read a Tt × tt cross","prompt":"Identify parent gametes, the four combinations and the genotype tally.","image":"assets/punnett-diagram.svg","topic":"14","values":[{"letter":"A","value":"T or t gamete","answer":"parent1"},{"letter":"B","value":"t gamete","answer":"parent2"},{"letter":"C","value":"Tt and tt cells","answer":"cells"},{"letter":"D","value":"2 Tt : 2 tt","answer":"tally"}],"options":[{"id":"parent1","text":"T or t gamete"},{"id":"parent2","text":"t gamete"},{"id":"cells","text":"Tt and tt cells"},{"id":"tally","text":"2 Tt : 2 tt"}],"visualDescription":"Identify parent gametes, the four combinations and the genotype tally. Four labeled positions A through D are shown in reading order."}],"videos":[{"id":"s24-c-video-food","title":"Food safety: clean, separate, cook and chill","publisher":"U.S. Food and Drug Administration","topic":"04","provider":"youtube","videoId":"iguM_pqetzo","sourceUrl":"https://www.youtube.com/watch?v=iguM_pqetzo","purpose":"Support Lesson 4: food safety: clean, separate, cook and chill.","focus":"Watch for which step interrupts contamination or growth.","written":"Cleaning and separation limit transfer between surfaces and food. Cooking addresses many microorganisms in the food; chilling slows growth. No one step makes all food risks disappear.","verification":"Publisher watch page identified in source search on 2026-09-24; external playback and captions may change."},{"id":"s24-c-video-vaccine","title":"How vaccines work","publisher":"Health Canada via ImmunizeBC","topic":"11","provider":"youtube","videoId":"pMSSu7QLAlw","sourceUrl":"https://www.youtube.com/watch?v=pMSSu7QLAlw","purpose":"Support Lesson 11: how vaccines work.","focus":"Watch for immune recognition and memory; compare the older animation with current vaccine types.","written":"Vaccines expose the immune system to an antigen or instructions for making one, enabling a response and memory without requiring the disease itself. Types differ; a vaccine is not always a weakened or killed whole germ.","verification":"Publisher watch page identified in source search on 2026-09-24; external playback and captions may change."},{"id":"s24-c-video-immune","title":"Immune system","publisher":"Amoeba Sisters","topic":"10","provider":"youtube","videoId":"fSEFXl2XQpc","sourceUrl":"https://www.youtube.com/watch?v=fSEFXl2XQpc","purpose":"Support Lesson 10: immune system.","focus":"Separate barriers, innate responses and targeted responses.","written":"Skin and mucous membranes limit entry. Innate responses react broadly; specific B and T cell responses recognize particular targets. Memory can improve a later response, but neither line guarantees that infection is impossible.","verification":"Publisher watch page identified in source search on 2026-09-24; external playback and captions may change."},{"id":"s24-c-video-antibiotic","title":"Antibiotics and antibiotic resistance","publisher":"World Health Organization SEARO","topic":"12","provider":"youtube","videoId":"UQqABSIUFW4","sourceUrl":"https://www.youtube.com/watch?v=UQqABSIUFW4","purpose":"Support Lesson 12: antibiotics and antibiotic resistance.","focus":"Identify what becomes resistant and why unnecessary use matters.","written":"Antibiotics act against bacterial infections, not directly against viruses. Resistant bacteria can survive and spread under selection pressure; the person does not become antibiotic-resistant. Follow current clinical instructions for personal care.","verification":"Publisher watch page identified in source search on 2026-09-24; external playback and captions may change."},{"id":"s24-c-video-dna","title":"DNA, chromosomes, genes and traits","publisher":"Amoeba Sisters","topic":"13","provider":"youtube","videoId":"8m6hHRlKwxY","sourceUrl":"https://www.youtube.com/watch?v=8m6hHRlKwxY","purpose":"Support Lesson 13: dna, chromosomes, genes and traits.","focus":"Follow the scale from DNA sequence to gene to chromosome and trait.","written":"DNA is a long molecule. A gene is a DNA region with a role in producing a functional product; chromosomes package DNA. Many traits reflect multiple genes and environmental influences.","verification":"Publisher watch page identified in source search on 2026-09-24; external playback and captions may change."},{"id":"s24-c-video-punnett","title":"Punnett squares and sex-linked traits","publisher":"Amoeba Sisters","topic":"14","provider":"youtube","videoId":"dN9SZHO6Wjg","sourceUrl":"https://www.youtube.com/watch?v=dN9SZHO6Wjg","purpose":"Support Lesson 14: punnett squares and sex-linked traits.","focus":"Notice how gametes populate a model and where its prediction stops.","written":"A Punnett square combines possible parental alleles to model probabilities for a specified inheritance pattern. Four boxes do not predict an exact four-child family. Human sex chromosome patterns also vary.","verification":"Publisher watch page identified in source search on 2026-09-24; external playback and captions may change."},{"id":"s24-c-video-pedigree","title":"Pedigrees","publisher":"Amoeba Sisters","topic":"15","provider":"youtube","videoId":"Gd09V2AkZv4","sourceUrl":"https://www.youtube.com/watch?v=Gd09V2AkZv4","purpose":"Support Lesson 15: pedigrees.","focus":"Read symbols and shading, then test possible inheritance models against a family.","written":"A pedigree records relationships and observed traits. Keep each interpretation tied to its own figure: Q11 uses the named family on p. 31, while Q12 uses a separate pedigree on p. 32. In Q12, two unaffected parents have an affected child, supporting recessive inheritance in the intended simple model.","verification":"Publisher watch page identified in source search on 2026-09-24; external playback and captions may change."},{"id":"s24-c-video-defence","title":"How does your immune system work?","publisher":"TED-Ed","topic":"09","provider":"youtube","videoId":"PSRJfaAYkW4","sourceUrl":"https://www.youtube.com/watch?v=PSRJfaAYkW4","purpose":"Support Lesson 9: how does your immune system work?.","focus":"Watch for the order of barriers, recognition and coordinated response.","written":"The immune system coordinates physical barriers, cells and signaling. Inflammation recruits and supports defence but can also produce symptoms. A response is evidence of action, not automatic proof that the body has cleared an infection.","verification":"Publisher watch page identified in source search on 2026-09-24; external playback and captions may change."}],"calcActivities":{},"notes":{"s24-c-l01-transfer":{"title":"Disease causes and germ theory · Use the idea in a new way","prompt":"A school cafeteria finds three people ill after one meal. Write a causal claim, two pieces of evidence that would support it, and one competing explanation to check.","model":"A foodborne pathogen is one possibility. Investigators would compare what each person ate and whether the same organism is found in the food and affected people. A different shared exposure or an unrelated illness must also be checked before naming the meal as the cause.","route":"lesson-01"},"s24-c-l01-later":{"title":"Disease causes and germ theory · Check again later","prompt":"Without opening the lesson, explain why a warm hamburger can become risky while warmth alone is not a pathogen.","model":"Warmth and time can help some bacteria multiply if they are present. The bacteria or their products may cause illness; the temperature changes the conditions rather than becoming the infectious agent.","route":"lesson-01"},"s24-c-l02-transfer":{"title":"Compare bacteria, viruses and other pathogens · Use the idea in a new way","prompt":"A student sees a skin rash and says “it must be bacteria.” Explain why that conclusion is premature and what evidence would help distinguish causes.","model":"A rash can have infectious or non-infectious causes, and a fungal infection is one possibility. The appearance alone does not prove the agent. A health professional may use history, examination or testing to identify the cause before choosing treatment.","route":"lesson-02"},"s24-c-l02-later":{"title":"Compare bacteria, viruses and other pathogens · Check again later","prompt":"From memory, compare where a bacterium and a virus make more of themselves, then name one infection route for a protist.","model":"A bacterium can divide as a cell when conditions permit. A virus must use a suitable host cell. A disease-causing protist such as Giardia can be swallowed in contaminated water.","route":"lesson-02"},"s24-c-l03-transfer":{"title":"Communicable disease and unequal risk · Use the idea in a new way","prompt":"Compare two communities with different water access. Identify the pathogen route, two conditions that may change exposure, and one action that does not blame residents.","model":"If water carries a pathogen, drinking it is the route. Treatment and safe distribution reduce exposure; household crowding can make some infections harder to control. A public water-testing and repair program targets the system rather than blaming people who rely on it.","route":"lesson-03"},"s24-c-l03-later":{"title":"Communicable disease and unequal risk · Check again later","prompt":"From memory, name one communicable and one non-communicable condition, and say why a risk factor is not a pathogen.","model":"A cold is communicable; a single-gene inherited disorder is non-communicable. A factor such as unsafe water affects exposure, but the disease-causing organism is the pathogen.","route":"lesson-03"},"s24-c-l04-transfer":{"title":"Food safety and preservation · Use the idea in a new way","prompt":"Design a safe sequence for preparing raw chicken and a salad. Explain one contamination control and one time/temperature control, including the limit of each.","model":"Use separate or properly cleaned utensils and boards before preparing the salad to prevent transfer. Keep perishable foods at safe cold temperatures until use and cook the chicken appropriately. Chilling slows growth but cannot reverse contamination, so both controls matter.","route":"lesson-04"},"s24-c-l04-later":{"title":"Food safety and preservation · Check again later","prompt":"From memory, compare what refrigeration, drying and pasteurization change. Which one can be assumed to sterilize food?","model":"Refrigeration slows growth through low temperature; drying reduces available water; pasteurization uses controlled heat to reduce harmful microbes. None should be described as universally sterilizing every product.","route":"lesson-04"},"s24-c-l05-transfer":{"title":"Sanitation, sterilization and aseptic practice · Use the idea in a new way","prompt":"A classroom investigation uses cleaned tools and a prepared surface. Identify two points where contamination could still enter and explain controls; keep any practical steps teacher-supervised.","model":"Tools can be re-contaminated if placed on an unclean surface, and hands can transfer microbes after touching another object. Keep prepared tools in a protected area and repeat appropriate hand hygiene as directed. The exact laboratory procedure requires teacher supervision.","route":"lesson-05"},"s24-c-l05-later":{"title":"Sanitation, sterilization and aseptic practice · Check again later","prompt":"From memory, choose the term for living tissue, hard surfaces, complete validated elimination and prevention during a procedure.","model":"Antiseptic is intended for living tissue; disinfectant for suitable hard surfaces; sterilization aims to eliminate all viable microorganisms; aseptic technique prevents contamination during a task.","route":"lesson-05"},"s24-c-l06-transfer":{"title":"Outbreaks, epidemics and historical impact · Use the idea in a new way","prompt":"A news post calls one city's disease cluster a pandemic. Write what evidence would support a local outbreak description and what additional evidence would be needed for pandemic language.","model":"A local increase above expected cases during a stated period could support an outbreak. Pandemic language requires evidence of sustained spread across multiple countries or continents, using comparable surveillance data.","route":"lesson-06"},"s24-c-l06-later":{"title":"Outbreaks, epidemics and historical impact · Check again later","prompt":"From memory, explain why case count alone cannot distinguish outbreak, epidemic and pandemic, and name two context fields for a historical comparison.","model":"The expected baseline, population, time and geographic extent are needed. Historical records should include date, location and measure, such as deaths or cases per population.","route":"lesson-06"},"s24-c-l07-transfer":{"title":"Public systems for water, waste and air · Use the idea in a new way","prompt":"A community receives both a drinking-water warning and an air-quality notice. For each, name the pathway, one measurement or observation, one system-level action and one limit of the evidence.","model":"For water, sampling may indicate contamination; treatment repair and a temporary warning address ingestion risk, but one sample cannot map the whole network. For air, monitors support a local advisory; emission controls or activity advice may reduce exposure, but the notice does not predict one person's illness.","route":"lesson-07"},"s24-c-l07-later":{"title":"Public systems for water, waste and air · Check again later","prompt":"Without looking, write the sequence source → monitoring → control → communication for a drinking-water example.","model":"A water source is sampled, test results are interpreted, treatment or distribution problems are corrected, and the public receives a timely advisory when needed.","route":"lesson-07"},"s24-c-l08-transfer":{"title":"Guidelines, risk decisions and the Walkerton case · Use the idea in a new way","prompt":"Using the original Walkerton workbook task or a teacher-provided timeline, choose one warning sign, one missed or effective control, and one recommendation. Mark any claim that requires evidence beyond the timeline.","model":"A positive water test is a warning sign. A clear rule for confirming, escalating and communicating the result can limit exposure. A timeline alone may not show what every worker knew at the time, so an individual-blame claim needs additional records.","route":"lesson-08"},"s24-c-l08-later":{"title":"Guidelines, risk decisions and the Walkerton case · Check again later","prompt":"From memory, explain how to turn a risk factor into a justified public-health response without blaming a group.","model":"Name the exposure pathway and the system weakness, then choose a control that interrupts it. Assess the action with evidence; do not label people as the hazard.","route":"lesson-08"},"s24-c-l09-transfer":{"title":"Physical barriers and inflammation · Use the idea in a new way","prompt":"A person has irritated airways after smoke exposure. Explain one barrier mechanism that may be impaired, one possible inflammatory response, and one reason not to diagnose an infection from coughing alone.","model":"Smoke can impair cilia and irritate airway surfaces, reducing clearance of trapped material. Irritation can trigger inflammation and coughing. Coughing has multiple possible causes, so symptoms alone do not identify a pathogen.","route":"lesson-09"},"s24-c-l09-later":{"title":"Physical barriers and inflammation · Check again later","prompt":"From memory, trace a pathogen's path past one barrier and into an inflammatory response; name the role of a macrophage.","model":"If a barrier such as skin is breached, tissue signals can change local blood flow and recruit immune cells. A macrophage may engulf microbes or debris.","route":"lesson-09"},"s24-c-l10-transfer":{"title":"Antigens, antibodies and immune response · Use the idea in a new way","prompt":"Compare a vaccinated person and a newborn receiving maternal antibodies. For each, identify where protective antibodies or memory arise and one limit of the comparison.","model":"Vaccination stimulates the person's own active response and can form memory cells; protection varies by vaccine and time. Maternal antibodies are passively received and tend to wane; they are not the infant's own memory response.","route":"lesson-10"},"s24-c-l10-later":{"title":"Antigens, antibodies and immune response · Check again later","prompt":"From memory, distinguish antigen, antibody, active immunity and passive immunity in four linked sentences.","model":"An antigen is a recognizable feature. An antibody can bind a matching feature. Active immunity follows the person's own response, while passive immunity supplies antibodies made elsewhere.","route":"lesson-10"},"s24-c-l11-transfer":{"title":"Blood compatibility, vaccines and immunity · Use the idea in a new way","prompt":"A poster claims 'O-negative means no compatibility checks' and 'all vaccines contain dead germs.' Correct both claims and name the context each missing detail changes.","model":"O-negative is a broad emergency red-cell donor shorthand, but clinical matching and testing still matter and other blood products differ. Vaccines use several platforms, including components and mRNA, so they are not all dead whole germs.","route":"lesson-11"},"s24-c-l11-later":{"title":"Blood compatibility, vaccines and immunity · Check again later","prompt":"Without looking, explain how a red-cell antigen mismatch differs from a vaccine target and why both require careful wording.","model":"A red-cell mismatch can trigger a recipient reaction during transfusion, so product-specific compatibility testing matters. A vaccine target stimulates an active response; vaccine types and durability differ.","route":"lesson-11"},"s24-c-l12-transfer":{"title":"Medicines, antibiotics and safe choices · Use the idea in a new way","prompt":"A friend wants an antibiotic for a cold and two symptom products with the same active ingredient. Explain the two different concerns and the evidence-based next step.","model":"Antibiotics do not act on the virus behind a typical cold; a clinician should decide if a bacterial infection is involved. Duplicate active ingredients may lead to excess dosing, so read the labels and seek pharmacist or clinician advice before combining products.","route":"lesson-12"},"s24-c-l12-later":{"title":"Medicines, antibiotics and safe choices · Check again later","prompt":"From memory, complete this correction: bacteria can become ___; people do not become ___ to antibiotics. Why does a viral cold not need an antibiotic for its virus?","model":"Bacteria can become resistant; a person's body does not become resistant to antibiotics in that sense. Antibiotics target bacterial processes, while a cold virus uses host cells and needs a different approach.","route":"lesson-12"},"s24-c-l13-transfer":{"title":"DNA, chromosomes and inheritance · Use the idea in a new way","prompt":"A student says a karyotype can reveal every gene and tell exactly what a person will be like. Correct the claim with one thing it can show and two things it cannot establish.","model":"A karyotype can show chromosome-number patterns such as trisomy 21. It cannot display every small DNA variant or predict every trait and health outcome. Environment and many genes may also matter.","route":"lesson-13"},"s24-c-l13-later":{"title":"DNA, chromosomes and inheritance · Check again later","prompt":"From memory, arrange DNA, gene and chromosome by relationship and solve the complement of A-C-T.","model":"A gene is a region of DNA, and chromosomes package long DNA molecules. The matching bases across A-C-T are T-G-A.","route":"lesson-13"},"s24-c-l14-transfer":{"title":"Genotypes and Punnett squares · Use the idea in a new way","prompt":"Two white heterozygous sheep have only two lambs, both white. Explain why that observation does not disprove the Ww × Ww square, then give its predicted genotype and phenotype ratios.","model":"Each lamb is a separate possible outcome; a small family can differ from a 3:1 expectation. The simple cross predicts WW:Ww:ww = 1:2:1 and white:black = 3:1 over many outcomes.","route":"lesson-14"},"s24-c-l14-later":{"title":"Genotypes and Punnett squares · Check again later","prompt":"From memory, write the four combinations from Tt × tt and state why a human eye-colour cross needs a limitation note.","model":"The combinations are Tt, Tt, tt and tt. The workbook's human eye-colour model uses one gene for practice, while actual eye colour involves multiple genes.","route":"lesson-14"},"s24-c-l15-transfer":{"title":"Read and construct pedigrees · Use the idea in a new way","prompt":"Construct the workbook Q13 family with a symbol key, but label its brown/blue eye rule as a simplified model. Then write one fact the diagram shows and one genotype it cannot prove without extra information.","model":"A keyed pedigree can show the named family relationships and observed eye colours. Under its simplified rule some genotypes can be inferred, but the actual human trait is multi-gene and unobserved alleles cannot always be identified from shading alone.","route":"lesson-15"},"s24-c-l16-transfer":{"title":"Mutations, mutagens and genetic disorders · Use the idea in a new way","prompt":"A friend says every mutation is inherited and every inherited change is harmful. Correct both parts with a body-cell/germ-cell distinction and one possible effect of a variant.","model":"A change confined to body cells is not automatically passed to children; changes in reproductive cells may be inherited. Many inherited variants are neutral or have context-dependent effects, while some contribute to disease.","route":"lesson-16"},"s24-c-l16-later":{"title":"Mutations, mutagens and genetic disorders · Check again later","prompt":"From memory, explain why a mutagen increases risk without guaranteeing a named disorder, and why cell type matters for inheritance.","model":"A mutagen can increase the chance of DNA damage, but repair, location and chance affect the result. Only changes in a lineage contributing to reproduction can normally be inherited.","route":"lesson-16"},"s24-c-l17-transfer":{"title":"Genetic research and ethical decisions · Use the idea in a new way","prompt":"Choose one workbook genetic-research advance. State a plausible benefit, a limitation, whose consent is needed, one fairness question and a less harmful alternative where relevant.","model":"A genetic test may help explain a condition, but its prediction can be limited and the result may affect relatives. The person tested should understand and consent to use of their data. Access and privacy should be considered, along with existing diagnostic or care options.","route":"lesson-17"},"s24-c-l17-later":{"title":"Genetic research and ethical decisions · Check again later","prompt":"From memory, give four questions you would ask before accepting a claim that a genetic technology will improve health.","model":"What benefit is supported by evidence? What harms and uncertainties remain? Who can consent and control data? Who has access, and what alternatives exist?","route":"lesson-17"},"s24-c-l01-source-work":{"title":"Disease causes and germ theory · Original workbook application","prompt":"Use workbook Chapter 9 questions 1, 2a–b, 3 and 9. Write a cause-and-conditions explanation for the hamburger. Include Koch's and Pasteur's different contributions and one observation that would test your claim.","model":"A pathogen in the food, if present, could multiply with suitable moisture, nutrients, temperature and time. Koch's approach asks for evidence linking a particular organism to illness; Pasteur's heating work supports a way to reduce microbes. Compare exposed and unexposed food and people before naming the cause.","route":"lesson-01"},"s24-c-l02-source-work":{"title":"Compare bacteria, viruses and other pathogens · Original workbook application","prompt":"For workbook Chapter 9 questions 4–8, make a four-row comparison of bacterium, virus, Giardia and athlete's-foot fungus. For each, give the category, one plausible route of exposure and one prevention action tied to that route.","model":"For example, Giardia is a protist that can be swallowed in contaminated untreated water, so treating drinking water interrupts the route. A cold virus replicates in host cells and can spread through respiratory exposure; an antibiotic does not directly stop that replication.","route":"lesson-02"},"s24-c-l03-source-work":{"title":"Communicable disease and unequal risk · Original workbook application","prompt":"Use workbook Chapter 9 questions 10–15 to build two columns: infectious route and non-communicable risk. Then explain how one social condition changes exposure or access without blaming an affected person.","model":"Crowded housing can make some respiratory exposures more likely, while limited access to care can delay treatment. Neither condition identifies a specific pathogen. A non-communicable condition can involve inherited, environmental and other factors without person-to-person transmission.","route":"lesson-03"},"s24-c-l04-source-work":{"title":"Food safety and preservation · Original workbook application","prompt":"Complete workbook Chapter 9 questions 16–17. Group all ten named preservation methods by mechanism, then choose five surface or utensil controls and state the contamination route each prevents.","model":"Refrigeration slows many microbes but does not sterilize food. Pasteurization applies controlled heat to reduce targeted hazards. A separate board for raw meat prevents transfer to ready-to-eat vegetables; washing and sanitizing the board before reuse addresses the same route.","route":"lesson-04"},"s24-c-l05-source-work":{"title":"Sanitation, sterilization and aseptic practice · Original workbook application","prompt":"For workbook Chapter 9 questions 18–20, plan a safe preparation sequence. Name where an antiseptic, a surface disinfectant, sterile equipment and an aseptic handling step belong, then explain the failure if one is omitted.","model":"A surface disinfectant belongs on the preparation surface as directed, not in a wound. Sterile equipment and clean handling reduce transfer into vulnerable tissue. Hand hygiene and suitable barriers support aseptic technique; a neat-looking room alone is not proof of sterility.","route":"lesson-05"},"s24-c-l06-source-work":{"title":"Outbreaks, epidemics and historical impact · Original workbook application","prompt":"Complete the four-column workbook Chapter 10 question 6 table. For each disease, record a dated place, a social condition that affected spread, an impact and one source limitation; then answer questions 1–5 with the same cause-versus-context care.","model":"For 1918 influenza, a respiratory virus spread across countries during a period of mass movement. Crowding and limited treatment options affected impact. A historical mortality figure needs a source and date; it does not describe a current local risk.","route":"lesson-06"},"s24-c-l07-source-work":{"title":"Public systems for water, waste and air · Original workbook application","prompt":"Use workbook Chapter 10 questions 7–14. Draw a source-to-tap control chain, explain waste and air alerts, then identify six textbook vaccine examples and the four food-safety actions. Mark which details are historical and where you would check today's Alberta guidance.","model":"Source protection, treatment, distribution monitoring and a public advisory are separate safeguards. The old AQI bands do not set today's AQHI advice. The textbook lists several vaccine-preventable diseases, while current schedules are maintained by Alberta Health. Clean, Cook, Separate and Chill address different contamination and growth routes.","route":"lesson-07"},"s24-c-l08-source-work":{"title":"Guidelines, risk decisions and the Walkerton case · Original workbook application","prompt":"Complete workbook Chapter 10 questions 15–17. Fill three contrasting factor–concern–control rows and justify a public guideline. For the Walkerton prompt, list the timeline evidence needed before assigning responsibility and identify the page missing from this PDF.","model":"Restaurant inspection addresses food handling; disease monitoring addresses a different community risk. A guideline can reduce preventable exposure but needs clear communication and follow-through. A criminal-charge conclusion cannot be supported from a timeline that is absent from the provided textbook.","route":"lesson-08"},"s24-c-l09-source-work":{"title":"Physical barriers and inflammation · Original workbook application","prompt":"Complete the original workbook Chapter 11 physical-defence chart on page 19. For at least six structures, state the entry route, the barrier action and what might happen if that defence is damaged; include the smoking/cough question with a limit on diagnosis.","model":"Cilia move mucus and trapped particles away from deeper airways. When clearance is impaired, particles and mucus can linger and coughing can increase. A cough can also have other causes, so this mechanism is not an individual diagnosis.","route":"lesson-09"},"s24-c-l10-source-work":{"title":"Antigens, antibodies and immune response · Original workbook application","prompt":"Use workbook Chapter 11 questions 5–13. Order the five response cards on page 21, explain the sliver example, and justify two of the antigen-scenario choices using self-versus-foreign context.","model":"A possible teaching order is entry/engulfment, displayed antigen, helper-cell signalling, B-cell antibody response with other immune cells, then memory. These events overlap in real life. Redness after a sliver reflects inflammation, not proof of a named infection.","route":"lesson-10"},"s24-c-l11-source-work":{"title":"Blood compatibility, vaccines and immunity · Original workbook application","prompt":"Complete workbook Chapter 11 questions 14–22. Draw active and passive branches with an example of each, then compare vaccine with antitoxin and qualify the O-negative donor statement. Use the original page for every case.","model":"Vaccination is active because the recipient develops a response and memory; supplied antitoxin is passive because antibodies are transferred. O-negative red cells can be compatible in many emergency red-cell contexts, but crossmatching and clinical rules still matter.","route":"lesson-11"},"s24-c-l12-source-work":{"title":"Medicines, antibiotics and safe choices · Original workbook application","prompt":"For workbook Chapter 11 questions 1 and 23–27, compare an antibiotic with a symptom-relief product. State each target, a reason it might be inappropriate, and three label or clinician-instruction checks.","model":"An antibiotic targets susceptible bacteria and does not directly treat a viral cold. A pain reliever may reduce a symptom without removing its cause. The user should follow the actual label and clinician or pharmacist advice, including dose and interaction warnings.","route":"lesson-12"},"s24-c-l13-source-work":{"title":"DNA, chromosomes and inheritance · Original workbook application","prompt":"Open workbook Chapter 12 pages 27–28. Write the complementary DNA bases, count one karyotype's key chromosome difference, and justify each of the three image-based identifications using the shown chromosomes.","model":"A pairs with T and G with C, giving T–C–G–A–C. Trisomy 21 has three copies of chromosome 21; a single X and XXY are distinct chromosome patterns. The original image must be read to match each numbered karyotype.","route":"lesson-13"},"s24-c-l14-source-work":{"title":"Genotypes and Punnett squares · Original workbook application","prompt":"Draw and label the three original Chapter 12 crosses on workbook pages 29–30. For each, show parental alleles, gametes, all four cells, genotype probability and phenotype probability; label the eye-colour assumption as simplified.","model":"Tt × tt gives two Tt and two tt boxes, a model 1:1 phenotype ratio if T is dominant. Ww × Ww gives WW, Ww, Ww and ww, or three white to one black in the simple model. Actual small families may differ.","route":"lesson-14"},"s24-c-l16-source-work":{"title":"Mutations, mutagens and genetic disorders · Original workbook application","prompt":"Use workbook Chapter 12 questions 14–17. Build a claim–mechanism–uncertainty table for DNA copying error, one mutagen exposure and prenatal exposure; then write an amniocentesis decision frame with benefits, risks and consent.","model":"A copying error can change a DNA sequence; a mutagen may increase the probability of certain changes, but an exposure does not prove an individual's outcome. Prenatal health decisions need current clinical advice. Amniocentesis is an informed-choice question, not a compulsory conclusion.","route":"lesson-16"},"s24-c-l17-source-work":{"title":"Genetic research and ethical decisions · Original workbook application","prompt":"Complete workbook Chapter 12 questions 18–19. Fill a two-column benefit/concern chart with evidence and limits, then write a consent-and-rights response to the cloning hypothetical that considers at least one alternative.","model":"Genetic research can help explain a disease or guide some care, but evidence, privacy and access matter. Creating a person for organ harvesting would violate that person's autonomy; the classroom argument must address rights and alternatives rather than treating a clone as equipment.","route":"lesson-17"},"s24-c-v4-l15-later":{"title":"Read and construct pedigrees · Check again later","prompt":"From memory, state one observation from Q11 on p. 31 and the different pattern in Q12 on p. 32 that supports a recessive interpretation.","model":"Q11 shows three generations and shades Sue, Joe, Jim and Tim. Q12 uses a different pedigree: two unshaded parents have a shaded child, which supports recessive inheritance in the intended simple model.","route":"lesson-15","id":"s24-c-v4-l15-later"},"s24-c-v4-l15-source-work":{"title":"Read and construct pedigrees · Original workbook application","prompt":"Use original workbook pp. 31–33. Answer Q11 from the named-family figure on p. 31, explain why the separate Q12 figure on p. 32 supports recessive inheritance in the intended simple model, and sketch Q13 with a legend. State the missing textbook-page limitation.","model":"Q11 has three generations; Sue, Joe, Jim and Tim are shaded; Jim has Tim and Lori. Q12 uses a different pedigree where two unaffected parents have an affected child, supporting recessive inheritance in the intended simple model. Q13 needs a legend and correct family connections.","route":"lesson-15"}},"exercises":{"s24-c-l01-error":{"kind":"mc","prompt":"A learner says the warm room itself infected everyone who ate a lunch. Which correction is strongest?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Distinguish a condition that changes growth from the agent and exposure that could cause infection.","id":"s24-c-l01-error","topic":"01","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l01-error-o0","text":"Warmth can favour growth if a pathogen was present; exposure to the pathogen still needs evidence."},{"id":"s24-c-l01-error-o1","text":"Warm conditions alone are sufficient to introduce a pathogen into uncontaminated food."},{"id":"s24-c-l01-error-o2","text":"Temperature alone identifies the exact bacterium."},{"id":"s24-c-l01-error-o3","text":"An inherited condition is established solely by the timing of illness after this meal."}],"answer":"s24-c-l01-error-o0"},"s24-c-l01-guided1":{"kind":"mc","prompt":"Which observation would best begin testing a foodborne explanation?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A comparison across cases and exposures tests the claim better than appearance or assumption.","id":"s24-c-l01-guided1","topic":"01","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l01-guided1-o0","text":"Compare what affected and unaffected people ate and when symptoms began."},{"id":"s24-c-l01-guided1-o1","text":"Ask only whether the room looked clean."},{"id":"s24-c-l01-guided1-o2","text":"Compare package appearance without checking what affected and unaffected people actually ate."},{"id":"s24-c-l01-guided1-o3","text":"Assume everyone at the school had the same exposure."}],"answer":"s24-c-l01-guided1-o0"},"s24-c-l01-guided2":{"kind":"mc","prompt":"Why might a hamburger left warm become riskier over time?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Growth requires an organism and suitable conditions; risk is not a guaranteed outcome.","id":"s24-c-l01-guided2","topic":"01","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l01-guided2-o0","text":"Some bacteria already present may reproduce under suitable conditions."},{"id":"s24-c-l01-guided2-o1","text":"Warmth by itself introduces a new pathogen into otherwise uncontaminated food."},{"id":"s24-c-l01-guided2-o2","text":"Warmth guarantees every eater will become sick."},{"id":"s24-c-l01-guided2-o3","text":"Chilling slows growth but by itself removes every microbe already present."}],"answer":"s24-c-l01-guided2-o0"},"s24-c-l01-independent1":{"kind":"mc","prompt":"A student lists poverty as a pathogen. What is the reasoning error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Keep an infectious agent distinct from conditions that shape risk and response.","id":"s24-c-l01-independent1","topic":"01","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l01-independent1-o0","text":"A social condition can alter exposure and access to care but is not itself an infectious agent."},{"id":"s24-c-l01-independent1-o1","text":"Social conditions can never affect health."},{"id":"s24-c-l01-independent1-o2","text":"Every disease linked to poverty is inherited."},{"id":"s24-c-l01-independent1-o3","text":"A pathogen is just another word for any risk factor."}],"answer":"s24-c-l01-independent1-o0"},"s24-c-l01-independent2":{"kind":"mc","prompt":"Two people ate the same meal; one became ill. What is a defensible conclusion?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Different outcomes do not establish or exclude a food source without more evidence.","id":"s24-c-l01-independent2","topic":"01","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l01-independent2-o0","text":"Investigate agent, dose, other exposures and host factors before assigning a cause."},{"id":"s24-c-l01-independent2-o1","text":"The different outcomes prove one person handled the food incorrectly."},{"id":"s24-c-l01-independent2-o2","text":"The meal is proven safe because one person stayed well."},{"id":"s24-c-l01-independent2-o3","text":"The room temperature alone proves a diagnosis."}],"answer":"s24-c-l01-independent2-o0"},"s24-c-l02-error":{"kind":"mc","prompt":"A learner says a cold virus divides by itself on a sandwich like a bacterial cell. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Bacteria are cells that may divide independently; viruses use host cells for replication.","id":"s24-c-l02-error","topic":"02","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l02-error-o0","text":"A virus needs a suitable host cell to make more virus particles."},{"id":"s24-c-l02-error-o1","text":"Bacteria never reproduce in food."},{"id":"s24-c-l02-error-o2","text":"Viruses and fungi are the same type of cellular organism."},{"id":"s24-c-l02-error-o3","text":"A virus can multiply on food without entering a host cell."}],"answer":"s24-c-l02-error-o0"},"s24-c-l02-guided1":{"kind":"mc","prompt":"Which pair is correctly matched in the workbook examples?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The examples involve different groups and need different transmission explanations.","id":"s24-c-l02-guided1","topic":"02","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l02-guided1-o0","text":"Giardia — protist; athlete's foot — fungus."},{"id":"s24-c-l02-guided1-o1","text":"Giardia — virus; athlete's foot — bacterium."},{"id":"s24-c-l02-guided1-o2","text":"Giardia — fungus; athlete's foot — protist."},{"id":"s24-c-l02-guided1-o3","text":"Both are bacterial diseases with the same exposure route."}],"answer":"s24-c-l02-guided1-o0"},"s24-c-l02-guided2":{"kind":"mc","prompt":"Which route could explain Giardia exposure in a hiking case?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The waterborne route connects an environmental source with entry into the digestive system.","id":"s24-c-l02-guided2","topic":"02","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l02-guided2-o0","text":"Swallowing contaminated untreated water."},{"id":"s24-c-l02-guided2-o1","text":"Knowing that beavers can carry Giardia without a water-exposure pathway."},{"id":"s24-c-l02-guided2-o2","text":"Being outdoors without evidence of a contaminated water source."},{"id":"s24-c-l02-guided2-o3","text":"Having a naturally occurring DNA allele."}],"answer":"s24-c-l02-guided2-o0"},"s24-c-l02-independent1":{"kind":"mc","prompt":"An antibiotic helped one infection, so a learner wants it for every viral cold. Which response uses mechanism?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Treatment depends on the agent and clinical context, not the general word 'infection'.","id":"s24-c-l02-independent1","topic":"02","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l02-independent1-o0","text":"Antibiotics target bacteria; they do not directly act on a cold virus."},{"id":"s24-c-l02-independent1-o1","text":"Fever is enough to classify this infection as bacterial."},{"id":"s24-c-l02-independent1-o2","text":"Viral particles split independently like bacteria."},{"id":"s24-c-l02-independent1-o3","text":"A medicine that helped once must work for every cause."}],"answer":"s24-c-l02-independent1-o0"},"s24-c-l02-independent2":{"kind":"mc","prompt":"A rash is described as definitely fungal from appearance alone. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A symptom can suggest possibilities but does not identify the agent by itself.","id":"s24-c-l02-independent2","topic":"02","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l02-independent2-o0","text":"Evidence distinguishing fungal infection from other infectious and non-infectious causes."},{"id":"s24-c-l02-independent2-o1","text":"A complete list of all nearby microbes, regardless of exposure route."},{"id":"s24-c-l02-independent2-o2","text":"Proof that all skin rashes are contagious."},{"id":"s24-c-l02-independent2-o3","text":"A claim that fungi are viruses."}],"answer":"s24-c-l02-independent2-o0"},"s24-c-l03-error":{"kind":"mc","prompt":"A learner calls crowded housing a pathogen. Which correction is best?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Separate a social condition from the microorganism and transmission route.","id":"s24-c-l03-error","topic":"03","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l03-error-o0","text":"It can increase contact and exposure opportunities; a pathogen is the disease-causing agent."},{"id":"s24-c-l03-error-o1","text":"It can never influence transmission."},{"id":"s24-c-l03-error-o2","text":"It is a kind of virus."},{"id":"s24-c-l03-error-o3","text":"It proves every resident has an infection."}],"answer":"s24-c-l03-error-o0"},"s24-c-l03-guided1":{"kind":"mc","prompt":"Which condition is communicable in the relevant sense?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Communicable describes spread of an infectious condition between hosts.","id":"s24-c-l03-guided1","topic":"03","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l03-guided1-o0","text":"An infection that can pass between hosts through a route."},{"id":"s24-c-l03-guided1-o1","text":"A chromosome-number pattern inherited through reproduction."},{"id":"s24-c-l03-guided1-o2","text":"A broken bone from a fall."},{"id":"s24-c-l03-guided1-o3","text":"A nutritional deficiency with no infectious agent."}],"answer":"s24-c-l03-guided1-o0"},"s24-c-l03-guided2":{"kind":"mc","prompt":"Which question helps compare two old mortality charts fairly?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Time, denominator and measurement type determine whether a comparison is meaningful.","id":"s24-c-l03-guided2","topic":"03","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l03-guided2-o0","text":"Do they use the same date, population, age range and measure?"},{"id":"s24-c-l03-guided2-o1","text":"Compare bar colours without checking the legend, date or denominator."},{"id":"s24-c-l03-guided2-o2","text":"Compare the place names rather than the rates and time periods."},{"id":"s24-c-l03-guided2-o3","text":"Can a dated number be called today's rate?"}],"answer":"s24-c-l03-guided2-o0"},"s24-c-l03-independent1":{"kind":"mc","prompt":"A student says poor water access means residents are biologically more likely to be infected. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The mechanism is exposure through a system, not a trait assigned to a group.","id":"s24-c-l03-independent1","topic":"03","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l03-independent1-o0","text":"Unequal water infrastructure changes exposure; it does not define inherent biology of residents."},{"id":"s24-c-l03-independent1-o1","text":"Water cannot carry infectious agents."},{"id":"s24-c-l03-independent1-o2","text":"Inherited factors alone determine whether a person becomes infected."},{"id":"s24-c-l03-independent1-o3","text":"Public systems cannot reduce exposure."}],"answer":"s24-c-l03-independent1-o0"},"s24-c-l03-independent2":{"kind":"mc","prompt":"Two diseases both harm health, but only one spreads by contact. What should the classification use?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Communicability is about spread between hosts; severity is another dimension.","id":"s24-c-l03-independent2","topic":"03","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l03-independent2-o0","text":"The demonstrated transmission mechanism, not just severity or symptom."},{"id":"s24-c-l03-independent2-o1","text":"Use the larger raw case count without adjusting for population size."},{"id":"s24-c-l03-independent2-o2","text":"Whether someone is worried about it."},{"id":"s24-c-l03-independent2-o3","text":"Use an undated number without checking how or when it was measured."}],"answer":"s24-c-l03-independent2-o0"},"s24-c-l04-error":{"kind":"mc","prompt":"A student says refrigeration sterilizes food. Which correction is best?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Preservation methods change conditions or reduce hazards in different ways; cold storage is not sterilization.","id":"s24-c-l04-error","topic":"04","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l04-error-o0","text":"Cold slows many microbes; it does not reliably eliminate every pathogen."},{"id":"s24-c-l04-error-o1","text":"Cold creates new pathogens."},{"id":"s24-c-l04-error-o2","text":"Refrigeration is identical to pasteurization."},{"id":"s24-c-l04-error-o3","text":"Food safety depends only on colour."}],"answer":"s24-c-l04-error-o0"},"s24-c-l04-guided1":{"kind":"mc","prompt":"Which method primarily reduces available water for microbial growth?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Less available water can limit microbial growth in a specific preservation method.","id":"s24-c-l04-guided1","topic":"04","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l04-guided1-o0","text":"Drying or salting."},{"id":"s24-c-l04-guided1-o1","text":"Leaving food on a warm counter."},{"id":"s24-c-l04-guided1-o2","text":"Using the same unwashed board for raw and ready-to-eat food."},{"id":"s24-c-l04-guided1-o3","text":"Removing the product label."}],"answer":"s24-c-l04-guided1-o0"},"s24-c-l04-guided2":{"kind":"mc","prompt":"Why does pasteurization not mean opened milk may stay warm indefinitely?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Controlled processing has limits; safe storage after opening still matters.","id":"s24-c-l04-guided2","topic":"04","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l04-guided2-o0","text":"It reduces targeted microbes through controlled heat but later contamination and growth remain possible."},{"id":"s24-c-l04-guided2-o1","text":"It makes milk completely sterile, so later storage and handling cannot matter."},{"id":"s24-c-l04-guided2-o2","text":"It works only by freezing the product."},{"id":"s24-c-l04-guided2-o3","text":"It protects milk by adding a vaccine rather than by controlled heat treatment."}],"answer":"s24-c-l04-guided2-o0"},"s24-c-l04-independent1":{"kind":"mc","prompt":"A salad is prepared on a board used for raw poultry. Which intervention addresses the route?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Cross-contamination occurs during transfer from the raw-food surface to ready-to-eat food.","id":"s24-c-l04-independent1","topic":"04","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l04-independent1-o0","text":"Use separate or properly cleaned and sanitized equipment before the salad is prepared."},{"id":"s24-c-l04-independent1-o1","text":"Only chill the salad after contamination."},{"id":"s24-c-l04-independent1-o2","text":"Assume vegetables kill microbes from poultry."},{"id":"s24-c-l04-independent1-o3","text":"Wait until the board looks dry without cleaning it."}],"answer":"s24-c-l04-independent1-o0"},"s24-c-l04-independent2":{"kind":"mc","prompt":"Which statement about freezing is defensible?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Freezing changes growth conditions; organisms may survive and grow after thawing.","id":"s24-c-l04-independent2","topic":"04","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l04-independent2-o0","text":"It slows or stops growth while frozen but cannot be assumed to sterilize the food."},{"id":"s24-c-l04-independent2-o1","text":"It makes all food safe forever."},{"id":"s24-c-l04-independent2-o2","text":"It guarantees every microbe is destroyed."},{"id":"s24-c-l04-independent2-o3","text":"It increases room-temperature bacterial division."}],"answer":"s24-c-l04-independent2-o0"},"s24-c-l05-error":{"kind":"mc","prompt":"A learner puts hard-surface disinfectant on a cut because it 'kills germs.' What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Microbial action and tissue safety are separate requirements.","id":"s24-c-l05-error","topic":"05","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l05-error-o0","text":"A product for surfaces is not interchangeable with a skin antiseptic; follow the intended-use label."},{"id":"s24-c-l05-error-o1","text":"Skin and countertops are the same material."},{"id":"s24-c-l05-error-o2","text":"Antiseptic means a stronger floor cleaner."},{"id":"s24-c-l05-error-o3","text":"All disinfectants are safe on living tissue."}],"answer":"s24-c-l05-error-o0"},"s24-c-l05-guided1":{"kind":"mc","prompt":"What best describes sterilization?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Sterilization has a more demanding outcome than ordinary cleaning or disinfection.","id":"s24-c-l05-guided1","topic":"05","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l05-guided1-o0","text":"A validated process intended to eliminate all viable microorganisms from an item."},{"id":"s24-c-l05-guided1-o1","text":"Any visible wipe of a table."},{"id":"s24-c-l05-guided1-o2","text":"Keeping an item in a refrigerator."},{"id":"s24-c-l05-guided1-o3","text":"Applying hand lotion."}],"answer":"s24-c-l05-guided1-o0"},"s24-c-l05-guided2":{"kind":"mc","prompt":"A prepared tool touches an unclean counter. What changed?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Aseptic practice must prevent re-contamination throughout the procedure.","id":"s24-c-l05-guided2","topic":"05","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l05-guided2-o0","text":"It may have become contaminated despite earlier preparation."},{"id":"s24-c-l05-guided2-o1","text":"It became automatically more sterile."},{"id":"s24-c-l05-guided2-o2","text":"The counter no longer contains any microbes."},{"id":"s24-c-l05-guided2-o3","text":"Gloves alone replace surface preparation and sterile equipment."}],"answer":"s24-c-l05-guided2-o0"},"s24-c-l05-independent1":{"kind":"mc","prompt":"Which method is intended for suitable non-living surfaces?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Disinfectants and antiseptics differ in intended target and safe use.","id":"s24-c-l05-independent1","topic":"05","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l05-independent1-o0","text":"A disinfectant used according to its label."},{"id":"s24-c-l05-independent1-o1","text":"Use a skin antiseptic on an instrument without checking whether it can sterilize the instrument."},{"id":"s24-c-l05-independent1-o2","text":"An antiseptic chosen without label review."},{"id":"s24-c-l05-independent1-o3","text":"Cooling instruments is enough to make them sterile."}],"answer":"s24-c-l05-independent1-o0"},"s24-c-l05-independent2":{"kind":"mc","prompt":"Why is hand cleaning alone insufficient after sterile equipment is put on a dirty surface?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Each new contact can break the chain of controls.","id":"s24-c-l05-independent2","topic":"05","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l05-independent2-o0","text":"The equipment should be treated as potentially contaminated before continuing."},{"id":"s24-c-l05-independent2-o1","text":"Hands can never transfer microbes."},{"id":"s24-c-l05-independent2-o2","text":"Aseptic technique only happens before the task."},{"id":"s24-c-l05-independent2-o3","text":"The original cleaning step makes later contact irrelevant."}],"answer":"s24-c-l05-independent2-o0"},"s24-c-l06-error":{"kind":"mc","prompt":"A learner calls one school's illness cluster a pandemic. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Pandemic describes broad geographic spread, not the seriousness of one local cluster.","id":"s24-c-l06-error","topic":"06","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l06-error-o0","text":"Evidence of spread across multiple countries or continents."},{"id":"s24-c-l06-error-o1","text":"A symptom that feels severe to one person."},{"id":"s24-c-l06-error-o2","text":"A higher number of students in one classroom."}],"answer":"s24-c-l06-error-o0"},"s24-c-l06-guided1":{"kind":"mc","prompt":"A town reports 25 cases this week and usually has about two. What should be investigated first?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A local excess can signal an outbreak, but case definitions, links and reporting still need checking.","id":"s24-c-l06-guided1","topic":"06","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l06-guided1-o0","text":"Whether the increase is real, linked and above the expected baseline in that time and place."},{"id":"s24-c-l06-guided1-o1","text":"Count repeated reports as separate cases without checking whether they describe the same person."},{"id":"s24-c-l06-guided1-o2","text":"Use an old national chart as the current local outbreak rate."}],"answer":"s24-c-l06-guided1-o0"},"s24-c-l06-guided2":{"kind":"mc","prompt":"Why can't a 1918 total-death count be directly ranked against a modern rate per 100,000?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A total and a population-adjusted rate answer different questions.","id":"s24-c-l06-guided2","topic":"06","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l06-guided2-o0","text":"The measures and populations differ; convert or obtain comparable measures."},{"id":"s24-c-l06-guided2-o1","text":"The modern number must always be smaller."},{"id":"s24-c-l06-guided2-o2","text":"Historical records are never useful."}],"answer":"s24-c-l06-guided2-o0"},"s24-c-l06-independent1":{"kind":"mc","prompt":"The workbook asks about disease impacts on First Nations peoples. Which explanation avoids a one-cause story?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Historical impact requires context and avoids treating diverse peoples as one biological category.","id":"s24-c-l06-independent1","topic":"06","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l06-independent1-o0","text":"Consider introduced pathogens alongside displacement, living conditions, care access and colonial policy with historical evidence."},{"id":"s24-c-l06-independent1-o1","text":"Assign one universal biological weakness to all Indigenous peoples."},{"id":"s24-c-l06-independent1-o2","text":"Ignore differences among communities and eras."}],"answer":"s24-c-l06-independent1-o0"},"s24-c-l06-independent2":{"kind":"mc","prompt":"Which claim can a dated plague/tuberculosis/influenza/AIDS table support?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The workbook table is historical evidence whose date, place and measure matter.","id":"s24-c-l06-independent2","topic":"06","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l06-independent2-o0","text":"A comparison of specified cases in their recorded period and place, with limits stated."},{"id":"s24-c-l06-independent2-o1","text":"A permanent ranking of all countries today."},{"id":"s24-c-l06-independent2-o2","text":"A diagnosis for each person in the table."}],"answer":"s24-c-l06-independent2-o0"},"s24-c-l07-error":{"kind":"mc","prompt":"A learner says a clear glass proves drinking water is safe. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Safety evidence comes from source, treatment, monitoring and distribution, not appearance alone.","id":"s24-c-l07-error","topic":"07","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l07-error-o0","text":"Appearance cannot reveal every microorganism or chemical; testing and system records matter."},{"id":"s24-c-l07-error-o1","text":"Clear water must contain no dissolved material."},{"id":"s24-c-l07-error-o2","text":"A normal taste is sufficient evidence that treatment removed hazards."}],"answer":"s24-c-l07-error-o0"},"s24-c-l07-guided1":{"kind":"mc","prompt":"A water sample shows a contamination indicator. What follows first?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A sample is a warning signal that requires interpretation and an appropriate response.","id":"s24-c-l07-guided1","topic":"07","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l07-guided1-o0","text":"Confirm and investigate its location, meaning and the system pathway under current protocols."},{"id":"s24-c-l07-guided1-o1","text":"Treat the result as proof of the same exposure at every tap without locating the sample."},{"id":"s24-c-l07-guided1-o2","text":"Ignore the result because water looks clear."}],"answer":"s24-c-l07-guided1-o0"},"s24-c-l07-guided2":{"kind":"mc","prompt":"How can wastewater treatment reduce disease risk?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Waste treatment acts on a route of environmental exposure, but does not replace drinking-water controls.","id":"s24-c-l07-guided2","topic":"07","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l07-guided2-o0","text":"It reduces release of harmful material before water returns to the environment."},{"id":"s24-c-l07-guided2-o1","text":"It permanently removes every microbial and chemical hazard in one treatment step."},{"id":"s24-c-l07-guided2-o2","text":"It also guarantees that the separate drinking-water distribution system cannot fail."}],"answer":"s24-c-l07-guided2-o0"},"s24-c-l07-independent1":{"kind":"mc","prompt":"An old workbook lists a fixed air-quality number band. What is the best way to advise someone today?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Air advisories depend on current measurement, location, index and personal context.","id":"s24-c-l07-independent1","topic":"07","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l07-independent1-o0","text":"Use a current local authority's index and time-specific advice."},{"id":"s24-c-l07-independent1-o1","text":"Treat a 2003 band as universal current law."},{"id":"s24-c-l07-independent1-o2","text":"Diagnose disease from the number alone."}],"answer":"s24-c-l07-independent1-o0"},"s24-c-l07-independent2":{"kind":"mc","prompt":"Which statement about a landfill liner is defensible?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A control reduces a pathway; it is not proof of zero future risk.","id":"s24-c-l07-independent2","topic":"07","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l07-independent2-o0","text":"It is one design control whose effectiveness depends on construction, operation and monitoring."},{"id":"s24-c-l07-independent2-o1","text":"It guarantees no contaminant can ever reach water."},{"id":"s24-c-l07-independent2-o2","text":"It makes wastewater treatment unnecessary."}],"answer":"s24-c-l07-independent2-o0"},"s24-c-l08-error":{"kind":"mc","prompt":"A learner blames a named worker for every Walkerton outcome from one timeline line. What is the reasoning flaw?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A timeline supports sequence and questions; it may not establish every person's responsibility.","id":"s24-c-l08-error","topic":"08","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l08-error-o0","text":"Assigning individual fault needs evidence beyond event order, including records of knowledge and authority."},{"id":"s24-c-l08-error-o1","text":"A timeline can identify a cause by itself, without testing the proposed pathway."},{"id":"s24-c-l08-error-o2","text":"One positive result should be dismissed without checking its meaning or location."}],"answer":"s24-c-l08-error-o0"},"s24-c-l08-guided1":{"kind":"mc","prompt":"A risk-table row lists population growth. Which response matches the concern?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The response should address system demand and exposure pathways.","id":"s24-c-l08-guided1","topic":"08","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l08-guided1-o0","text":"Scale water, waste, surveillance and emergency communication capacity to the community."},{"id":"s24-c-l08-guided1-o1","text":"Treat crowding itself as an infectious agent instead of a factor affecting exposure."},{"id":"s24-c-l08-guided1-o2","text":"Remove all testing because there are more residents."}],"answer":"s24-c-l08-guided1-o0"},"s24-c-l08-guided2":{"kind":"mc","prompt":"The workbook cites textbook p. 186, missing from the supplied PDF. What should the online course do?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Printed page references must match actual source pages; missing evidence stays visibly missing.","id":"s24-c-l08-guided2","topic":"08","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l08-guided2-o0","text":"State the gap and use the original workbook prompt or a teacher-provided timeline without inventing p. 186."},{"id":"s24-c-l08-guided2-o1","text":"Show printed p. 185 while labeling it p. 186."},{"id":"s24-c-l08-guided2-o2","text":"Claim the missing page was verified."}],"answer":"s24-c-l08-guided2-o0"},"s24-c-l08-independent1":{"kind":"mc","prompt":"An adverse water result is recorded but not escalated. Which control addresses that failure?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Escalation connects a warning sign to the people and actions able to reduce exposure.","id":"s24-c-l08-independent1","topic":"08","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l08-independent1-o0","text":"A clear rule for prompt confirmation, responsible review and public communication when indicated."},{"id":"s24-c-l08-independent1-o1","text":"Assume recording alone prevents exposure."},{"id":"s24-c-l08-independent1-o2","text":"Wait for visible cloudiness before taking a positive test result seriously."}],"answer":"s24-c-l08-independent1-o0"},"s24-c-l08-independent2":{"kind":"mc","prompt":"Which Walkerton response is evidence-based rather than blame-based?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The case asks for a justified mechanism and response tied to documented events.","id":"s24-c-l08-independent2","topic":"08","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l08-independent2-o0","text":"Identify a warning sign, its system control point and a testable prevention action."},{"id":"s24-c-l08-independent2-o1","text":"Name a group as inherently unsafe."},{"id":"s24-c-l08-independent2-o2","text":"Treat one anecdote as the full investigation."}],"answer":"s24-c-l08-independent2-o0"},"s24-c-l09-error":{"kind":"mc","prompt":"A learner says redness after a sliver proves a particular bacterium is present. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Redness, warmth and swelling show a response but are not organism-specific evidence.","id":"s24-c-l09-error","topic":"09","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l09-error-o0","text":"Inflammation can follow sterile injury; symptoms alone do not identify an organism."},{"id":"s24-c-l09-error-o1","text":"Inflammation can only occur after vaccination."},{"id":"s24-c-l09-error-o2","text":"Redness alone identifies a specific inherited disorder."}],"answer":"s24-c-l09-error-o0"},"s24-c-l09-guided1":{"kind":"mc","prompt":"Which structure helps move mucus and trapped particles along airways?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Cilia support clearance after mucus traps inhaled material.","id":"s24-c-l09-guided1","topic":"09","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l09-guided1-o0","text":"Cilia on airway cells."},{"id":"s24-c-l09-guided1-o1","text":"A blood cell circulating nearby, without crossing the damaged barrier."},{"id":"s24-c-l09-guided1-o2","text":"An antibody in the environment rather than a cell responding at the wound."}],"answer":"s24-c-l09-guided1-o0"},"s24-c-l09-guided2":{"kind":"mc","prompt":"What can a macrophage do in an early response?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A macrophage is an immune cell that can engulf material; it is not an antibody molecule.","id":"s24-c-l09-guided2","topic":"09","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l09-guided2-o0","text":"Engulf microbes or debris and help coordinate further defence."},{"id":"s24-c-l09-guided2-o1","text":"Become a red-cell antigen."},{"id":"s24-c-l09-guided2-o2","text":"Inflammation immediately rebuilds the damaged skin barrier."}],"answer":"s24-c-l09-guided2-o0"},"s24-c-l09-independent1":{"kind":"mc","prompt":"A student says a cough after smoke exposure proves infection. Which response is strongest?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A symptom can arise through more than one mechanism.","id":"s24-c-l09-independent1","topic":"09","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l09-independent1-o0","text":"Smoke can irritate airways and impair clearance; coughing alone does not diagnose infection."},{"id":"s24-c-l09-independent1-o1","text":"Coughing always has one bacterial cause."},{"id":"s24-c-l09-independent1-o2","text":"Smoke improves cilia movement in every case."}],"answer":"s24-c-l09-independent1-o0"},"s24-c-l09-independent2":{"kind":"mc","prompt":"Why might a sliver site be warm and swollen?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Inflammation involves tissue signals, blood vessels and immune-cell movement.","id":"s24-c-l09-independent2","topic":"09","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l09-independent2-o0","text":"Local signals change blood flow and fluid movement while immune cells arrive."},{"id":"s24-c-l09-independent2-o1","text":"Inflammation converts damaged body cells into invading microbes."},{"id":"s24-c-l09-independent2-o2","text":"Only antibodies from a vaccine can cause warmth."}],"answer":"s24-c-l09-independent2-o0"},"s24-c-l10-error":{"kind":"mc","prompt":"A learner calls an antibody the antigen on a microbe. What is the correction?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The two molecules have different roles in recognition and binding.","id":"s24-c-l10-error","topic":"10","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l10-error-o0","text":"An antigen is a recognized feature; an antibody is a protein that may bind a matching feature."},{"id":"s24-c-l10-error-o1","text":"Both words mean the same immune cell."},{"id":"s24-c-l10-error-o2","text":"Antigens are always antibiotics."}],"answer":"s24-c-l10-error-o0"},"s24-c-l10-guided1":{"kind":"mc","prompt":"In the workbook's simplified five-step sequence, which event starts the model?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The model begins with encounter and early response before specific activation.","id":"s24-c-l10-guided1","topic":"10","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l10-guided1-o0","text":"A pathogen enters and early cells encounter it."},{"id":"s24-c-l10-guided1-o1","text":"Memory cells appear before any target exists."},{"id":"s24-c-l10-guided1-o2","text":"An antibody is made by a red blood cell."}],"answer":"s24-c-l10-guided1-o0"},"s24-c-l10-guided2":{"kind":"mc","prompt":"Which is an example of passive immunity?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Passive protection supplies antibodies rather than forming the same active response.","id":"s24-c-l10-guided2","topic":"10","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l10-guided2-o0","text":"Receiving antibodies made by another source."},{"id":"s24-c-l10-guided2-o1","text":"Building one's own response after vaccination."},{"id":"s24-c-l10-guided2-o2","text":"Rebuilding a physical barrier rather than making a targeted immune response."}],"answer":"s24-c-l10-guided2-o0"},"s24-c-l10-independent1":{"kind":"mc","prompt":"Why is the CBE chart's 'active immunity is permanent' claim too broad?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Active responses can persist but do not guarantee lifelong complete protection.","id":"s24-c-l10-independent1","topic":"10","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l10-independent1-o0","text":"Protection and memory can vary by agent, vaccine and time."},{"id":"s24-c-l10-independent1-o1","text":"Immune responses never form memory."},{"id":"s24-c-l10-independent1-o2","text":"Only passive antibodies exist."}],"answer":"s24-c-l10-independent1-o0"},"s24-c-l10-independent2":{"kind":"mc","prompt":"A learner says antibodies alone directly destroy every pathogen. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The immune response is a coordinated network, not one universal killing step.","id":"s24-c-l10-independent2","topic":"10","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l10-independent2-o0","text":"Antibody binding can block or mark targets, while other cells and mechanisms may be needed."},{"id":"s24-c-l10-independent2-o1","text":"Antibodies are bacteria that divide independently."},{"id":"s24-c-l10-independent2-o2","text":"An antibody is a population-level warning rather than a protein in an immune response."}],"answer":"s24-c-l10-independent2-o0"},"s24-c-l11-error":{"kind":"mc","prompt":"A learner says O-negative blood can always be given to anyone without tests. What is wrong?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A broad emergency red-cell donor type is not a universal no-test rule.","id":"s24-c-l11-error","topic":"11","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l11-error-o0","text":"The shorthand concerns red-cell compatibility; clinical selection and testing still matter."},{"id":"s24-c-l11-error-o1","text":"O-negative means all blood products are identical."},{"id":"s24-c-l11-error-o2","text":"The ABO system has no antigens."}],"answer":"s24-c-l11-error-o0"},"s24-c-l11-guided1":{"kind":"mc","prompt":"What makes an A-to-B red-cell mismatch hazardous in the classroom model?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The model links red-cell antigens with the recipient's antibody response.","id":"s24-c-l11-guided1","topic":"11","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l11-guided1-o0","text":"A recipient's antibodies may react with incompatible donor red-cell antigens."},{"id":"s24-c-l11-guided1-o1","text":"Family relationship matters more than antigen matching for red-cell compatibility."},{"id":"s24-c-l11-guided1-o2","text":"A respiratory virus is the key factor in ABO red-cell matching."}],"answer":"s24-c-l11-guided1-o0"},"s24-c-l11-guided2":{"kind":"mc","prompt":"Which statement describes modern vaccine platforms accurately?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The Canadian Immunization Guide describes more than the older two-category shorthand.","id":"s24-c-l11-guided2","topic":"11","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l11-guided2-o0","text":"Different vaccines may use attenuated organisms, inactivated material, components or mRNA approaches."},{"id":"s24-c-l11-guided2-o1","text":"Every vaccine is a dead whole pathogen."},{"id":"s24-c-l11-guided2-o2","text":"Every vaccine gives passive maternal antibodies."}],"answer":"s24-c-l11-guided2-o0"},"s24-c-l11-independent1":{"kind":"mc","prompt":"A prepared antibody product and a vaccine are compared. Which difference matters?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The source of antibodies and potential immune memory differ.","id":"s24-c-l11-independent1","topic":"11","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l11-independent1-o0","text":"The product supplies antibodies; vaccination stimulates the recipient's own active response."},{"id":"s24-c-l11-independent1-o1","text":"Both always last forever."},{"id":"s24-c-l11-independent1-o2","text":"Both are red-cell transfusions."}],"answer":"s24-c-l11-independent1-o0"},"s24-c-l11-independent2":{"kind":"mc","prompt":"How should the CBE vaccine/autism page be handled?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A dated source claim needs correction, not false balance.","id":"s24-c-l11-independent2","topic":"11","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l11-independent2-o0","text":"Exclude its false debate framing; the Canadian Immunization Guide states MMR does not cause autism."},{"id":"s24-c-l11-independent2-o1","text":"Teach both claims as equally supported scientific positions."},{"id":"s24-c-l11-independent2-o2","text":"Omit all vaccine science because the old page is wrong."}],"answer":"s24-c-l11-independent2-o0"},"s24-c-l12-error":{"kind":"mc","prompt":"A learner says antibiotics make a person's body resistant so they no longer work. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Selection can increase resistant bacteria; the host's body is not the resistant organism.","id":"s24-c-l12-error","topic":"12","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l12-error-o0","text":"Resistance refers to bacteria able to survive a medicine, not the body becoming immune to it."},{"id":"s24-c-l12-error-o1","text":"Viruses are bacterial cells."},{"id":"s24-c-l12-error-o2","text":"A medicine that reduces symptoms also kills the organism causing them."}],"answer":"s24-c-l12-error-o0"},"s24-c-l12-guided1":{"kind":"mc","prompt":"Why does an antibiotic not directly treat a typical viral cold?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Mechanism depends on the type of infectious agent.","id":"s24-c-l12-guided1","topic":"12","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l12-guided1-o0","text":"Its bacterial targets are not the cold virus's replication machinery."},{"id":"s24-c-l12-guided1-o1","text":"A viral infection always contains no symptoms."},{"id":"s24-c-l12-guided1-o2","text":"The dose is always too small for any illness."}],"answer":"s24-c-l12-guided1-o0"},"s24-c-l12-guided2":{"kind":"mc","prompt":"Two non-prescription products list the same active ingredient. What is the first safety concern?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Ingredient lines and dose directions matter more than brand names.","id":"s24-c-l12-guided2","topic":"12","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l12-guided2-o0","text":"Combining them may duplicate the ingredient and exceed directions."},{"id":"s24-c-l12-guided2-o1","text":"Different brand names guarantee the active ingredients cannot overlap."},{"id":"s24-c-l12-guided2-o2","text":"Every combination is automatically safer."}],"answer":"s24-c-l12-guided2-o0"},"s24-c-l12-independent1":{"kind":"mc","prompt":"A friend offers leftover antibiotics for a new illness. Which response matches current guidance?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Antibiotics need an appropriate indication and directed use.","id":"s24-c-l12-independent1","topic":"12","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l12-independent1-o0","text":"Do not share them; seek appropriate professional assessment and use medicines as directed."},{"id":"s24-c-l12-independent1-o1","text":"Use them because any infection is bacterial."},{"id":"s24-c-l12-independent1-o2","text":"Change the label instructions to fit the leftovers."}],"answer":"s24-c-l12-independent1-o0"},"s24-c-l12-independent2":{"kind":"mc","prompt":"Why can unnecessary antibiotic use contribute to resistance?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Selection changes the composition of bacterial populations over time.","id":"s24-c-l12-independent2","topic":"12","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l12-independent2-o0","text":"It can select bacteria with traits that survive the drug and multiply."},{"id":"s24-c-l12-independent2-o1","text":"It trains the immune response by causing the body to produce an infection indefinitely."},{"id":"s24-c-l12-independent2-o2","text":"It sterilizes all environments permanently."}],"answer":"s24-c-l12-independent2-o0"},"s24-c-l13-error":{"kind":"mc","prompt":"A learner says a gene, DNA and a chromosome are exactly the same object. What is the correction?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The three names refer to related but different scales of organization.","id":"s24-c-l13-error","topic":"13","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l13-error-o0","text":"A gene is a DNA region; chromosomes package long DNA molecules containing many genes."},{"id":"s24-c-l13-error-o1","text":"A visible chromosome shape directly reveals every gene on that chromosome."},{"id":"s24-c-l13-error-o2","text":"Chromosomes contain no DNA."}],"answer":"s24-c-l13-error-o0"},"s24-c-l13-guided1":{"kind":"mc","prompt":"What letters pair across the rungs of A-G-C-T-G?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A pairs with T and C with G at each aligned position.","id":"s24-c-l13-guided1","topic":"13","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l13-guided1-o0","text":"T-C-G-A-C."},{"id":"s24-c-l13-guided1-o1","text":"A-G-C-T-G."},{"id":"s24-c-l13-guided1-o2","text":"G-A-T-C-A."}],"answer":"s24-c-l13-guided1-o0"},"s24-c-l13-guided2":{"kind":"mc","prompt":"A karyotype shows three copies of chromosome 21. What pattern is visible?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The image can show a chromosome-number difference at the labelled pair.","id":"s24-c-l13-guided2","topic":"13","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l13-guided2-o0","text":"Trisomy 21."},{"id":"s24-c-l13-guided2-o1","text":"A one-letter DNA substitution."},{"id":"s24-c-l13-guided2-o2","text":"Proof of every future health outcome."}],"answer":"s24-c-l13-guided2-o0"},"s24-c-l13-independent1":{"kind":"mc","prompt":"A student uses XX/XY as a universal rule for a person's gender. What is the problem?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Genomic variation and personal identity exceed a simplified classroom karyotype model.","id":"s24-c-l13-independent1","topic":"13","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l13-independent1-o0","text":"They are common chromosome patterns with variations and do not establish gender identity."},{"id":"s24-c-l13-independent1-o1","text":"Chromosomes cannot be observed."},{"id":"s24-c-l13-independent1-o2","text":"Every human body cell contains one unpaired chromosome."}],"answer":"s24-c-l13-independent1-o0"},"s24-c-l13-independent2":{"kind":"mc","prompt":"Which claim is beyond what a karyotype image alone can show?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Karyotypes show large patterns, not all sequence-level or future information.","id":"s24-c-l13-independent2","topic":"13","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l13-independent2-o0","text":"A karyotype reveals every small sequence variant and predicts a precise lifetime outcome."},{"id":"s24-c-l13-independent2-o1","text":"The number of visible chromosome 21 copies."},{"id":"s24-c-l13-independent2-o2","text":"Whether a labelled pair appears in the display."}],"answer":"s24-c-l13-independent2-o0"},"s24-c-l14-error":{"kind":"mc","prompt":"A learner says a four-box Punnett square promises four children with one outcome each. What is the error?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Each offspring is another possible outcome under the model.","id":"s24-c-l14-error","topic":"14","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l14-error-o0","text":"Boxes show possible allele combinations and probabilities, not guaranteed family outcomes."},{"id":"s24-c-l14-error-o1","text":"The four boxes record four children who have already been born."},{"id":"s24-c-l14-error-o2","text":"Each child must use a different box."}],"answer":"s24-c-l14-error-o0"},"s24-c-l14-guided1":{"kind":"mc","prompt":"What gametes can a Tt plant contribute in the simple model?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A gamete receives one allele for the modeled gene.","id":"s24-c-l14-guided1","topic":"14","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l14-guided1-o0","text":"T or t."},{"id":"s24-c-l14-guided1-o1","text":"Only TT."},{"id":"s24-c-l14-guided1-o2","text":"Only tt."}],"answer":"s24-c-l14-guided1-o0"},"s24-c-l14-guided2":{"kind":"mc","prompt":"What genotype ratio comes from Ww × Ww?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Combining W and w from each parent gives WW, Ww, Ww and ww.","id":"s24-c-l14-guided2","topic":"14","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l14-guided2-o0","text":"1 WW : 2 Ww : 1 ww."},{"id":"s24-c-l14-guided2-o1","text":"4 WW : 0 Ww : 0 ww."},{"id":"s24-c-l14-guided2-o2","text":"1 WW : 1 ww with no heterozygotes."}],"answer":"s24-c-l14-guided2-o0"},"s24-c-l14-independent1":{"kind":"mc","prompt":"If white wool is dominant to black, what phenotype ratio does Ww × Ww predict?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Three of four equally likely boxes have at least one dominant W allele.","id":"s24-c-l14-independent1","topic":"14","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l14-independent1-o0","text":"3 white : 1 black in the simplified model."},{"id":"s24-c-l14-independent1-o1","text":"1 white : 3 black."},{"id":"s24-c-l14-independent1-o2","text":"Four black lambs guaranteed."}],"answer":"s24-c-l14-independent1-o0"},"s24-c-l14-independent2":{"kind":"mc","prompt":"Why must the workbook's brown/blue human-eye-colour square have a caution note?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The model teaches allele bookkeeping but not a reliable personal eye-colour forecast.","id":"s24-c-l14-independent2","topic":"14","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l14-independent2-o0","text":"Real eye colour involves multiple genes; the one-gene rule is a classroom simplification."},{"id":"s24-c-l14-independent2-o1","text":"One allele pair is enough to predict every detail of human eye colour."},{"id":"s24-c-l14-independent2-o2","text":"The four boxes guarantee four specific children."}],"answer":"s24-c-l14-independent2-o0"},"s24-c-l15-guided1":{"kind":"mc","prompt":"How many generations appear on workbook p. 31?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Generation count follows horizontal descent levels, not affected count.","id":"s24-c-l15-guided1","topic":"15","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l15-guided1-o0","text":"Three."},{"id":"s24-c-l15-guided1-o1","text":"Two, because only two shaded people appear."},{"id":"s24-c-l15-guided1-o2","text":"Four, because four names are shaded."}],"answer":"s24-c-l15-guided1-o0"},"s24-c-l15-guided2":{"kind":"mc","prompt":"Which named people are shaded in the source pedigree?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The page key defines shading as affected status; read each named symbol.","id":"s24-c-l15-guided2","topic":"15","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l15-guided2-o0","text":"Sue, Joe, Jim and Tim."},{"id":"s24-c-l15-guided2-o1","text":"Tom, Sara, Kay and Lori."},{"id":"s24-c-l15-guided2-o2","text":"Only Sue and Kay."}],"answer":"s24-c-l15-guided2-o0"},"s24-c-l15-independent1":{"kind":"mc","prompt":"How many children does Jim have in the drawn family?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Follow Jim and Kay's parent line to their two descendants.","id":"s24-c-l15-independent1","topic":"15","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l15-independent1-o0","text":"Two: Tim and Lori."},{"id":"s24-c-l15-independent1-o1","text":"Four: Sue, Joe, Tim and Lori."},{"id":"s24-c-l15-independent1-o2","text":"One: Kay."}],"answer":"s24-c-l15-independent1-o0"},"s24-c-l16-error":{"kind":"mc","prompt":"A learner says every mutation is harmful and inherited. What is the correction?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Location, effect and cell lineage matter before claiming harm or inheritance.","id":"s24-c-l16-error","topic":"16","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l16-error-o0","text":"Effects vary, and a body-cell change is not automatically passed to children."},{"id":"s24-c-l16-error-o1","text":"Every mutation produces an obvious beneficial trait."},{"id":"s24-c-l16-error-o2","text":"Every DNA difference is visible on a karyotype."}],"answer":"s24-c-l16-error-o0"},"s24-c-l16-guided1":{"kind":"mc","prompt":"What makes a body-cell change different from one in a reproductive-cell lineage?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Inheritance requires a route through egg or sperm formation.","id":"s24-c-l16-guided1","topic":"16","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l16-guided1-o0","text":"Only a change in reproductive cells normally has a direct route to offspring."},{"id":"s24-c-l16-guided1-o1","text":"Body cells contain no DNA."},{"id":"s24-c-l16-guided1-o2","text":"A reproductive cell cannot contain variants."}],"answer":"s24-c-l16-guided1-o0"},"s24-c-l16-guided2":{"kind":"mc","prompt":"A base is copied differently and repair corrects it. What follows?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Repair can prevent a transient copying error from becoming a lasting sequence change.","id":"s24-c-l16-guided2","topic":"16","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l16-guided2-o0","text":"The copying error need not persist as a new variant in that lineage."},{"id":"s24-c-l16-guided2-o1","text":"A genetic disorder is guaranteed."},{"id":"s24-c-l16-guided2-o2","text":"Every DNA copying error changes the total chromosome count."}],"answer":"s24-c-l16-guided2-o0"},"s24-c-l16-independent1":{"kind":"mc","prompt":"Why can't exposure to a mutagen prove a specific future disorder?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Risk is probabilistic and mechanism-specific, not an individual guarantee.","id":"s24-c-l16-independent1","topic":"16","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l16-independent1-o0","text":"Exposure may raise risk, but dose, repair, location and chance affect outcomes."},{"id":"s24-c-l16-independent1-o1","text":"Mutagens have no possible effects."},{"id":"s24-c-l16-independent1-o2","text":"A given exposure always causes the same mutation and outcome in every person."}],"answer":"s24-c-l16-independent1-o0"},"s24-c-l16-independent2":{"kind":"mc","prompt":"Which statement about amniocentesis is appropriate for this course?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The course can analyze evidence and ethics without making an individual medical decision.","id":"s24-c-l16-independent2","topic":"16","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l16-independent2-o0","text":"It involves possible information, procedure risks and personal decisions needing clinical counselling."},{"id":"s24-c-l16-independent2-o1","text":"The class should choose it for each pregnant person."},{"id":"s24-c-l16-independent2-o2","text":"It guarantees the child's whole future."}],"answer":"s24-c-l16-independent2-o0"},"s24-c-l17-error":{"kind":"mc","prompt":"A headline says a genetic test proves someone will develop a complex disease. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Genetic association or screening result is not always a certain personal forecast.","id":"s24-c-l17-error","topic":"17","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-l17-error-o0","text":"Predictive strength, other genes, environment, age and uncertainty."},{"id":"s24-c-l17-error-o1","text":"More precise-looking chart colours without stronger evidence."},{"id":"s24-c-l17-error-o2","text":"A claim that genetic results can never inform any health decision."}],"answer":"s24-c-l17-error-o0"},"s24-c-l17-guided1":{"kind":"mc","prompt":"What makes consent meaningful in a genetic study?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Informed consent includes comprehension and choice about the proposed use.","id":"s24-c-l17-guided1","topic":"17","difficulty":"Foundation","role":"guided1","options":[{"id":"s24-c-l17-guided1-o0","text":"Understanding purpose, data use, risks and alternatives before a voluntary decision."},{"id":"s24-c-l17-guided1-o1","text":"A signature obtained without explanation."},{"id":"s24-c-l17-guided1-o2","text":"A decision based on a headline without checking the original evidence."}],"answer":"s24-c-l17-guided1-o0"},"s24-c-l17-guided2":{"kind":"mc","prompt":"Why can genetic privacy matter to relatives?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Family relationships make some genetic findings relevant beyond one data record.","id":"s24-c-l17-guided2","topic":"17","difficulty":"Application","role":"guided2","options":[{"id":"s24-c-l17-guided2-o0","text":"Shared inherited information may imply something about family members too."},{"id":"s24-c-l17-guided2-o1","text":"Relatives have identical genetic information whenever they share a pedigree."},{"id":"s24-c-l17-guided2-o2","text":"Genetic data are never personal."}],"answer":"s24-c-l17-guided2-o0"},"s24-c-l17-independent1":{"kind":"mc","prompt":"The workbook asks about cloning someone to harvest organs. Which response is ethical reasoning?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A justified response separates a technology claim from the rights of affected people.","id":"s24-c-l17-independent1","topic":"17","difficulty":"Application","role":"independent1","options":[{"id":"s24-c-l17-independent1-o0","text":"Assess claimed benefit, harm, consent, dignity, fairness and alternatives rather than treating a person as a resource."},{"id":"s24-c-l17-independent1-o1","text":"Assume the hypothetical is standard clinical practice."},{"id":"s24-c-l17-independent1-o2","text":"Use an unsupported slogan rather than evidence about benefits and harms."}],"answer":"s24-c-l17-independent1-o0"},"s24-c-l17-independent2":{"kind":"mc","prompt":"A dated chart calls an idea an 'advance'. What should be checked?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"Research examples change; source context and present evidence must be kept separate.","id":"s24-c-l17-independent2","topic":"17","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-l17-independent2-o0","text":"Its date, evidence, current status, limits and who benefits or bears risk."},{"id":"s24-c-l17-independent2-o1","text":"A professional-looking logo is enough to establish the chart’s evidence."},{"id":"s24-c-l17-independent2-o2","text":"Whether the old prediction sounds exciting."}],"answer":"s24-c-l17-independent2-o0"},"s24-c-v4-l15-error":{"kind":"mc","prompt":"A learner uses the named-family pedigree from workbook p. 31 to answer Q12 on p. 32. What is the error?","hint":"Check the printed question number and the figure immediately above it before interpreting the pattern.","explanation":"Q11 and Q12 use different pedigrees. Evidence from the named-family chart on p. 31 cannot replace the separate Q12 chart on p. 32.","id":"s24-c-v4-l15-error","topic":"15","difficulty":"Foundation","role":"error","options":[{"id":"s24-c-v4-l15-error-o0","text":"Q12 has its own pedigree on p. 32, so its inheritance claim must be tested against that figure."},{"id":"s24-c-v4-l15-error-o1","text":"The family names on p. 31 automatically apply to every later pedigree."},{"id":"s24-c-v4-l15-error-o2","text":"Shading has the same meaning as a person’s name."}],"answer":"s24-c-v4-l15-error-o0"},"s24-c-v4-l15-independent2":{"kind":"mc","prompt":"Which feature of the separate Q12 pedigree supports a recessive interpretation in the intended simple model?","hint":"Look for an affected child whose two parents do not display the modeled trait.","explanation":"The Q12 chart includes two unshaded parents with a shaded child. In the intended fully penetrant dominant-or-recessive classroom model, both parents can be unaffected carriers of a recessive allele.","id":"s24-c-v4-l15-independent2","topic":"15","difficulty":"Application","role":"independent2","options":[{"id":"s24-c-v4-l15-independent2-o0","text":"Two parents who do not display the trait have a child who does display it."},{"id":"s24-c-v4-l15-independent2-o1","text":"Every person in the pedigree displays the trait."},{"id":"s24-c-v4-l15-independent2-o2","text":"The chart prints every person’s genotype."}],"answer":"s24-c-v4-l15-independent2-o0"}},"transfer":{"id":"s24-c-transfer-review","title":"Independent application: a community health case","questions":[{"kind":"mc","prompt":"A rash is described as definitely fungal from appearance alone. What is missing?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"A symptom can suggest possibilities but does not identify the agent by itself.","id":"s24-c-l02-transfer1","topic":"02","difficulty":"Application","role":"transfer1","options":[{"id":"s24-c-l02-transfer1-o0","text":"Evidence distinguishing fungal infection from other infectious and non-infectious causes."},{"id":"s24-c-l02-transfer1-o1","text":"A complete list of all nearby microbes, regardless of exposure route."},{"id":"s24-c-l02-transfer1-o2","text":"Proof that all skin rashes are contagious."},{"id":"s24-c-l02-transfer1-o3","text":"A claim that fungi are viruses."}],"answer":"s24-c-l02-transfer1-o0"},{"kind":"mc","prompt":"Which Walkerton response is evidence-based rather than blame-based?","hint":"Identify the cause, pathway or evidence before selecting an answer.","explanation":"The case asks for a justified mechanism and response tied to documented events.","id":"s24-c-l08-transfer2","topic":"08","difficulty":"Application","role":"transfer2","options":[{"id":"s24-c-l08-transfer2-o0","text":"Identify a warning sign, its system control point and a testable prevention action."},{"id":"s24-c-l08-transfer2-o1","text":"Name a group as inherently unsafe."},{"id":"s24-c-l08-transfer2-o2","text":"Treat one anecdote as the full investigation."}],"answer":"s24-c-l08-transfer2-o0"},{"kind":"mc","prompt":"A new pedigree shows two unaffected parents with an affected child. Under a simple dominant-or-recessive model, which explanation fits?","hint":"Look for an affected child whose two parents do not display the modeled trait.","explanation":"Two unaffected carriers can each pass a recessive allele to an affected child. The pattern supports a recessive interpretation within the stated simple model.","id":"s24-c-v4-l15-transfer3","topic":"15","difficulty":"Application","role":"transfer3","options":[{"id":"s24-c-v4-l15-transfer3-o0","text":"A recessive model can fit if both unaffected parents carry the recessive allele."},{"id":"s24-c-v4-l15-transfer3-o1","text":"A fully penetrant dominant model requires both unaffected parents to display the trait."},{"id":"s24-c-v4-l15-transfer3-o2","text":"The pedigree proves the exact genotype of every unshaded person."}],"answer":"s24-c-v4-l15-transfer3-o0"}],"writing":[{"id":"s24-c-transfer-writing","prompt":"A school faces a foodborne illness concern and a family asks about inherited risk. Separate the evidence and response for each situation."}]},"supplementary":[{"id":"workbook","title":"Unit C student workbook (2023)","pdf":"assets/workbook.pdf"},{"id":"workbook-key","title":"Unit C workbook key (2023): attempt questions before self-check","pdf":"assets/workbook-key.pdf"},{"id":"guided-notes","title":"Unit C guided notes","pdf":"assets/guided-notes.pdf"}],"figures":{"transmission":{"title":"Trace an infection pathway","image":"assets/transmission-diagram.svg","alt":"Match source, exit, transfer and entry in the infection pathway."},"water":{"title":"Trace a community water safeguard","image":"assets/water-diagram.svg","alt":"Match intake, treatment, monitoring and household delivery."},"immune":{"title":"Trace a targeted immune response","image":"assets/immune-diagram.svg","alt":"Match the entering antigen, recognition, response and memory."},"punnett":{"title":"Read a Tt × tt cross","image":"assets/punnett-diagram.svg","alt":"Identify parent gametes, the four combinations and the genotype tally."},"dna-scale":{"title":"Keep the three scales separate","image":"assets/dna-scale-diagram.svg","alt":"A cell contains a nucleus, a nucleus contains chromosomes, and chromosomes contain DNA. A karyotype shows chromosome number and arrangement, not every DNA base."},"pedigree-q11":{"title":"Read the actual workbook pedigree","image":"assets/workbook-pedigree-q11.jpg","alt":"The 2023 workbook pedigree shows Tom and Sue as parents of Sara, Joe and Jim; Jim and Kay have Tim and Lori. Sue, Joe, Jim and Tim are shaded."},"inflammation-source":{"title":"Where the response happens","image":"assets/source-inflammation-p195.png","alt":"White blood cell leaves a capillary; a macrophage surrounds bacteria in nearby tissue."},"pedigree-q12":{"title":"Use the separate Q12 pedigree","image":"assets/workbook-page-32.jpg","alt":"Workbook page 32 question 12 pedigree. Two unshaded parents in the second generation have shaded children in the third generation."}}};
